var SENT_DATA = [{"t": "I had called upon my friend, Mr. Sherlock Holmes, one day in the autumn of last year and found him in deep conversation with a very stout, florid-faced, elderly gentleman with fiery red hair.", "sk": "I had called upon my friend and found him in deep conversation.", "skk": "나는 친구를 찾아갔다가, 그가 깊은 대화 중인 것을 보았다.", "ko": "작년 가을 어느 날 나는 친구 셜록 홈즈를 찾아갔다가, 그가 아주 뚱뚱하고 얼굴이 불그레한 노신사와 깊은 이야기를 나누고 있는 것을 보았다. 노신사는 불타는 듯한 빨간 머리를 하고 있었다.", "pi": 0}, {"t": "With an apology for my intrusion, I was about to withdraw when Holmes pulled me abruptly into the room and closed the door behind me.", "sk": "I was about to withdraw when Holmes pulled me into the room.", "skk": "내가 물러나려던 참에 홈즈가 나를 방 안으로 끌어당겼다.", "ko": "방해해서 미안하다고 말하며 막 물러나려던 참에, 홈즈가 나를 불쑥 방 안으로 끌어당기고 내 뒤로 문을 닫았다.", "pi": 0}, {"t": "“You could not possibly have come at a better time, my dear Watson,” he said cordially.", "sk": "You could not have come at a better time.", "skk": "이보다 더 좋은 때에 올 수는 없었을 걸세.", "ko": "\"이보다 더 좋은 때에 오긴 어려웠을 걸세, 왓슨.\" 그가 다정하게 말했다.", "pi": 1}, {"t": "“I was afraid that you were engaged.”", "sk": "I was afraid that you were engaged.", "skk": "자네가 바쁜 줄 알았네.", "ko": "\"자네가 볼일 중인 줄 알았네.\"", "pi": 1}, {"t": "“So I am. Very much so.”", "sk": "So I am.", "skk": "그래, 맞아.", "ko": "\"실제로 그렇다네. 아주 많이.\"", "pi": 1}, {"t": "“Then I can wait in the next room.”", "sk": "I can wait in the next room.", "skk": "옆방에서 기다리겠네.", "ko": "\"그럼 옆방에서 기다리지.\"", "pi": 1}, {"t": "“Not at all. This gentleman, Mr. Wilson, has been my partner and helper in many of my most successful cases, and I have no doubt that he will be of the utmost use to me in yours also.”", "sk": "This gentleman has been my partner and helper.", "skk": "이분은 제 동료이자 조력자였습니다.", "ko": "\"전혀 아닙니다. 윌슨 씨, 이분은 제가 해결한 성공적인 사건들에서 동료이자 조력자였습니다. 당신 사건에서도 더없이 큰 도움이 되리라 확신합니다.\"", "pi": 1}, {"t": "“Try the settee,” said Holmes, relapsing into his armchair and putting his fingertips together, as was his custom when in judicial moods.", "sk": "Said Holmes, relapsing into his armchair.", "skk": "홈즈가 안락의자에 몸을 파묻으며 말했다.", "ko": "\"소파에 앉으시죠.\" 홈즈는 안락의자에 도로 몸을 파묻고 손끝을 맞대며 말했다. 무언가를 판단할 때면 늘 하던 버릇이었다.", "pi": 1}, {"t": "“I know, my dear Watson, that you share my love of all that is bizarre and outside the conventions and humdrum routine of everyday life.", "sk": "I know that you share my love of all that is bizarre.", "skk": "자네가 기이한 것을 좋아하는 내 취향을 함께한다는 걸 아네.", "ko": "\"왓슨, 나는 자네가 기이한 것, 그러니까 일상의 관습과 따분한 반복에서 벗어난 모든 것을 좋아하는 내 취향을 함께한다는 걸 알고 있네.\"", "pi": 1}, {"t": "You have shown your relish for it by the enthusiasm which has prompted you to chronicle, and, if you will excuse my saying so, somewhat to embellish so many of my own little adventures.”", "sk": "You have shown your relish for it by the enthusiasm.", "skk": "자네는 그 열의로 그 취향을 드러냈지.", "ko": "\"자네는 내 사소한 모험들을 그토록 많이 기록하게 만든, 그리고 이런 말 해서 미안하네만 다소 부풀리게 만든 그 열의로, 그 취향을 드러내 보였네.\"", "pi": 1}, {"t": "“Your cases have indeed been of the greatest interest to me,” I observed.", "sk": "Your cases have been of the greatest interest to me.", "skk": "자네 사건들은 내게 더없이 흥미로웠네.", "ko": "\"자네 사건들은 정말이지 내게 더없이 흥미로웠네.\" 내가 말했다.", "pi": 1}, {"t": "“You will remember that I remarked the other day, just before we went into the very simple problem presented by Miss Mary Sutherland, that for strange effects and extraordinary combinations we must go to life itself, which is always far more daring than any effort of the imagination.”", "sk": "You will remember that I remarked that we must go to life itself.", "skk": "삶 그 자체로 가야 한다고 내가 말한 걸 기억할 걸세.", "ko": "\"일전에, 메리 서덜랜드 양이 가져온 그 아주 단순한 사건에 들어가기 직전에, 기이한 결과와 놀라운 조합을 보려면 삶 그 자체로 가야 한다고 내가 말한 걸 기억할 걸세. 삶은 언제나 어떤 상상의 산물보다도 훨씬 대담하니까.\"", "pi": 1}, {"t": "“A proposition which I took the liberty of doubting.”", "sk": "A proposition which I doubted.", "skk": "제가 감히 의심했던 주장이죠.", "ko": "\"제가 실례를 무릅쓰고 의심했던 주장이었죠.\"", "pi": 2}, {"t": "“You did, Doctor, but none the less you must come round to my view, for otherwise I shall keep on piling fact upon fact on you until your reason breaks down under them and acknowledges me to be right.", "sk": "You must come round to my view.", "skk": "자네는 내 견해로 돌아서게 될 걸세.", "ko": "\"그랬지, 왓슨. 하지만 그래도 자네는 내 견해를 받아들이게 될 걸세. 안 그러면 내가 자네에게 사실 위에 사실을 계속 쌓아올려서, 결국 자네 이성이 그 무게에 무너져 내가 옳다고 인정하게 될 테니까.\"", "pi": 2}, {"t": "Now, Mr. Jabez Wilson here has been good enough to call upon me this morning, and to begin a narrative which promises to be one of the most singular which I have listened to for some time.", "sk": "Mr. Wilson has been good enough to call upon me and to begin a narrative.", "skk": "윌슨 씨가 고맙게도 나를 찾아와 이야기를 시작해주었네.", "ko": "\"그런데 여기 이 제이베즈 윌슨 씨가 고맙게도 오늘 아침 나를 찾아와, 근래 들어본 것 중 가장 기이한 축에 들 법한 이야기를 시작해주었네.\"", "pi": 2}, {"t": "You have heard me remark that the strangest and most unique things are very often connected not with the larger but with the smaller crimes, and occasionally, indeed, where there is room for doubt whether any positive crime has been committed.", "sk": "You have heard me remark that the strangest things are connected with the smaller crimes.", "skk": "가장 기이한 일은 작은 범죄와 얽혀 있다고 내가 말한 걸 자네도 들었지.", "ko": "\"가장 기이하고 유례없는 일들은 큰 범죄가 아니라 오히려 작은 범죄와 얽혀 있는 경우가 많고, 때로는 범죄라 할 만한 일이 정말 있었는지조차 의심스러운 경우와 얽혀 있다고, 내가 말하는 걸 자네도 들은 적 있지.\"", "pi": 2}, {"t": "As far as I have heard, it is impossible for me to say whether the present case is an instance of crime or not, but the course of events is certainly among the most singular that I have ever listened to.", "sk": "It is impossible for me to say whether the case is an instance of crime.", "skk": "이 사건이 범죄인지 아닌지는 말할 수 없네.", "ko": "\"지금까지 들은 바로는 이번 일이 범죄에 해당하는지 아닌지 말할 수 없네. 다만 일이 흘러온 과정만큼은 내가 여태 들어본 것 중 가장 기이한 축에 든다는 게 분명하네.\"", "pi": 2}, {"t": "Perhaps, Mr. Wilson, you would have the great kindness to recommence your narrative.”", "sk": "You would have the great kindness to recommence your narrative.", "skk": "이야기를 다시 시작해주시면 고맙겠습니다.", "ko": "\"윌슨 씨, 괜찮으시다면 이야기를 처음부터 다시 해주시겠습니까.\"", "pi": 2}, {"t": "The portly client puffed out his chest with an appearance of some little pride and pulled a dirty and wrinkled newspaper from the inside pocket of his greatcoat.", "sk": "The client puffed out his chest and pulled a newspaper from his pocket.", "skk": "그 손님은 가슴을 내밀고는 주머니에서 신문을 꺼냈다.", "ko": "그 풍채 좋은 손님은 다소 으쓱한 듯 가슴을 내밀더니, 외투 안주머니에서 더럽고 구겨진 신문을 꺼냈다.", "pi": 3}, {"t": "As he glanced down the advertisement column, with his head thrust forward and the paper flattened out upon his knee, I took a good look at the man and endeavoured, after the fashion of my companion, to read the indications which might be presented by his dress or appearance.", "sk": "I took a good look at the man and endeavoured to read the indications.", "skk": "나는 그 남자를 잘 살펴보고 단서를 읽어내려 애썼다.", "ko": "그가 머리를 앞으로 내민 채 무릎 위에 신문을 펼쳐놓고 광고란을 훑어보는 동안, 나는 그 남자를 잘 살펴보며, 내 동료의 방식을 따라 그의 옷차림이나 겉모습이 드러낼 만한 단서를 읽어내려 애썼다.", "pi": 3}, {"t": "I did not gain very much, however, by my inspection.", "sk": "I did not gain very much by my inspection.", "skk": "나는 살펴봐도 별 소득이 없었다.", "ko": "하지만 살펴봐도 별로 얻은 것이 없었다.", "pi": 3}, {"t": "Our visitor bore every mark of being an average commonplace British tradesman, obese, pompous, and slow.", "sk": "Our visitor bore every mark of being an average tradesman.", "skk": "우리 손님은 딱 평범한 상인의 표가 났다.", "ko": "우리 손님은 뚱뚱하고 거들먹거리고 굼뜬, 그야말로 평범한 영국 상인이라는 표가 역력했다.", "pi": 3}, {"t": "He wore rather baggy grey shepherd's check trousers, a not over-clean black frock-coat, unbuttoned in the front, and a drab waistcoat with a heavy brassy Albert chain, and a square pierced bit of metal dangling down as an ornament.", "sk": "He wore trousers, a frock-coat, and a waistcoat with a chain.", "skk": "그는 바지와 프록코트, 사슬 달린 조끼를 입고 있었다.", "ko": "그는 다소 헐렁한 회색 셰퍼드 체크무늬 바지에, 그다지 깨끗하지 않은 검은색 프록코트를 단추도 채우지 않은 채 걸치고, 묵직한 놋쇠 회중시계 사슬이 달린 칙칙한 조끼를 입고 있었다. 그 사슬에는 장식으로 구멍 뚫린 네모난 금속 조각이 매달려 늘어져 있었다.", "pi": 3}, {"t": "A frayed top-hat and a faded brown overcoat with a wrinkled velvet collar lay upon a chair beside him.", "sk": "A top-hat and an overcoat lay upon a chair.", "skk": "모자와 외투가 의자 위에 놓여 있었다.", "ko": "닳아 해진 톱해트와, 벨벳 옷깃이 구겨진 색바랜 갈색 외투가 그의 옆 의자 위에 놓여 있었다.", "pi": 3}, {"t": "Altogether, look as I would, there was nothing remarkable about the man save his blazing red head, and the expression of extreme chagrin and discontent upon his features.", "sk": "There was nothing remarkable about the man save his red head.", "skk": "빨간 머리 말고는 이 남자에게 특별한 게 없었다.", "ko": "전체적으로 아무리 뜯어봐도, 이 남자에게서 특별한 점이라곤 활활 타는 듯한 빨간 머리와, 얼굴에 서린 극도의 분함과 불만의 표정 말고는 없었다.", "pi": 3}, {"t": "Sherlock Holmes' quick eye took in my occupation, and he shook his head with a smile as he noticed my questioning glances.", "sk": "Sherlock Holmes' quick eye took in my occupation, and he shook his head.", "skk": "홈즈의 빠른 눈이 내 직업을 알아채고는, 그가 고개를 저었다.", "ko": "홈즈의 빠른 눈은 내 직업을 이미 알아채고 있었고, 그는 내가 의아해하며 곁눈질하는 것을 보고는 미소 지으며 고개를 저었다.", "pi": 3}, {"t": "“Beyond the obvious facts that he has at some time done manual labour, that he takes snuff, that he is a Freemason, that he has been in China, and that he has done a considerable amount of writing lately, I can deduce nothing else.”", "sk": "I can deduce nothing else beyond the obvious facts.", "skk": "뻔한 사실들 말고는 더 추리할 게 없네.", "ko": "\"뻔히 보이는 사실들, 그러니까 이 사람이 예전에 육체노동을 한 적이 있고, 코담배를 즐기며, 프리메이슨 회원이고, 중국에 다녀왔으며, 최근에 글을 꽤 많이 썼다는 것 말고는, 나로선 더 추리해낼 게 없네.\"", "pi": 3}, {"t": "Mr. Jabez Wilson started up in his chair, with his forefinger upon the paper, but his eyes upon my companion.", "sk": "Mr. Jabez Wilson started up in his chair.", "skk": "윌슨 씨는 의자에서 벌떡 일어났다.", "ko": "제이베즈 윌슨 씨는 손가락은 신문 위에 둔 채, 눈은 내 동료에게 둔 채로 의자에서 벌떡 몸을 일으켰다.", "pi": 3}, {"t": "“How, in the name of good-fortune, did you know all that, Mr. Holmes?” he asked.", "sk": "How did you know all that, Mr. Holmes?", "skk": "대체 그걸 어떻게 아셨습니까, 홈즈 씨?", "ko": "\"대체 어떻게 그 모든 걸 아셨습니까, 홈즈 씨?\" 그가 물었다.", "pi": 3}, {"t": "“How did you know, for example, that I did manual labour? It's as true as gospel, for I began as a ship's carpenter.”", "sk": "How did you know that I did manual labour? I began as a ship's carpenter.", "skk": "제가 육체노동을 했다는 걸 어떻게 아셨죠? 저는 목수로 시작했거든요.", "ko": "\"예를 들어 제가 육체노동을 했다는 건 어떻게 아셨습니까? 틀림없는 사실이긴 합니다, 저는 배 짓는 목수로 시작했으니까요.\"", "pi": 3}, {"t": "“Your hands, my dear sir. Your right hand is quite a size larger than your left.", "sk": "Your right hand is quite a size larger than your left.", "skk": "당신 오른손이 왼손보다 꽤 크군요.", "ko": "\"손을 보면 압니다, 선생. 당신 오른손이 왼손보다 꽤 한 치수는 더 크군요.\"", "pi": 4}, {"t": "You have worked with it, and the muscles are more developed.”", "sk": "You have worked with it, and the muscles are more developed.", "skk": "그 손으로 일을 해왔고, 근육이 더 발달했습니다.", "ko": "\"그 손으로 일을 해왔고, 그래서 근육이 더 발달한 겁니다.\"", "pi": 4}, {"t": "“Well, the snuff, then, and the Freemasonry?”", "sk": "What about the snuff and the Freemasonry?", "skk": "그럼 코담배랑 프리메이슨은요?", "ko": "\"그럼 코담배랑 프리메이슨은요?\"", "pi": 4}, {"t": "“I won't insult your intelligence by telling you how I read that, especially as, rather against the strict rules of your order, you use an arc-and-compass breastpin.”", "sk": "I won't insult your intelligence by telling you how I read that.", "skk": "그걸 어떻게 읽었는지 말해서 당신 지성을 모욕하진 않겠습니다.", "ko": "\"그걸 어떻게 알아냈는지 시시콜콜 설명해서 당신의 지성을 모욕하진 않겠습니다. 더구나 당신은, 소속 조합의 엄격한 규칙에 다소 어긋나게, 컴퍼스와 자 모양의 브로치를 달고 계시니까요.\"", "pi": 4}, {"t": "“Ah, of course, I forgot that. But the writing?”", "sk": "I forgot that. But the writing?", "skk": "그걸 잊었네요. 근데 글씨는요?", "ko": "\"아, 맞다, 그걸 깜빡했네요. 그런데 글씨는요?\"", "pi": 4}, {"t": "“What else can be indicated by that right cuff so very shiny for five inches, and the left one with the smooth patch near the elbow where you rest it upon the desk?”", "sk": "What else can be indicated by that right cuff, and the left one?", "skk": "그 오른쪽 소맷부리랑 왼쪽 소맷부리를 보면 또 뭘 알 수 있겠습니까?", "ko": "\"다섯 인치나 반질반질하게 닳은 그 오른쪽 소맷부리와, 책상에 팔을 괼 때 닿는 팔꿈치 근처가 반들반들해진 왼쪽 소맷부리를 보면, 그것 말고 또 뭘 알 수 있겠습니까?\"", "pi": 4}, {"t": "“Well, but China?”", "sk": "But China?", "skk": "근데 중국은요?", "ko": "\"근데 중국은요?\"", "pi": 4}, {"t": "“The fish that you have tattooed immediately above your right wrist could only have been done in China.", "sk": "The fish could only have been done in China.", "skk": "그 물고기 문신은 중국에서만 가능했습니다.", "ko": "\"당신 오른쪽 손목 바로 위에 새긴 그 물고기 문신은 중국에서만 새길 수 있었던 겁니다.\"", "pi": 4}, {"t": "I have made a small study of tattoo marks and have even contributed to the literature of the subject.", "sk": "I have made a small study of tattoo marks.", "skk": "저는 문신 자국을 조금 연구했습니다.", "ko": "\"저는 문신 자국을 조금 연구했고, 그 주제의 문헌에 글을 보탠 적도 있습니다.\"", "pi": 4}, {"t": "That trick of staining the fishes' scales of a delicate pink is quite peculiar to China.", "sk": "That trick is quite peculiar to China.", "skk": "그 수법은 중국에만 있는 특유한 것입니다.", "ko": "\"물고기 비늘을 은은한 분홍빛으로 물들이는 그 수법은 중국에서만 볼 수 있는 특유한 것이죠.\"", "pi": 4}, {"t": "When, in addition, I see a Chinese coin hanging from your watch-chain, the matter becomes even more simple.”", "sk": "When I see a Chinese coin hanging from your watch-chain, the matter becomes more simple.", "skk": "회중시계 사슬에 매달린 중국 동전을 보면, 문제는 더 간단해집니다.", "ko": "\"게다가 당신 회중시계 사슬에 중국 동전이 매달려 있는 걸 보니, 문제는 한층 더 간단해지는군요.\"", "pi": 4}, {"t": "Mr. Jabez Wilson laughed heavily. “Well, I never!” said he.", "sk": "Wilson laughed. “Well, I never!” said he.", "skk": "윌슨이 웃었다. \"이럴 수가!\" 그가 말했다.", "ko": "제이베즈 윌슨 씨는 크게 웃었다. \"이거 참, 별일을 다 보네!\" 그가 말했다.", "pi": 5}, {"t": "“I thought at first that you had done something clever, but I see that there was nothing in it, after all.”", "sk": "I thought you had done something clever, but there was nothing in it.", "skk": "처음엔 뭔가 대단한 걸 하신 줄 알았는데, 별거 아니었네요.", "ko": "\"처음엔 뭔가 영리한 일을 하신 줄 알았는데, 결국 별거 아니었다는 걸 알겠네요.\"", "pi": 5}, {"t": "“I begin to think, Watson,” said Holmes, “that I make a mistake in explaining.", "sk": "I begin to think that I make a mistake in explaining.", "skk": "설명하는 게 실수인 것 같다는 생각이 드네요.", "ko": "\"왓슨, 설명을 하는 게 실수인 것 같다는 생각이 드는군요,\" 홈즈가 말했다.", "pi": 5}, {"t": "‘Omne ignotum pro magnifico,’ you know, and my poor little reputation, such as it is, will suffer shipwreck if I am so candid.", "sk": "My reputation will suffer shipwreck if I am so candid.", "skk": "제가 너무 솔직하면 제 명성이 결딴날 겁니다.", "ko": "\"'모르는 것은 다 대단해 보이는 법'이잖아요, 그러니 대단찮은 제 명성이나마 제가 너무 솔직해지면 결딴나고 말 겁니다.\"", "pi": 5}, {"t": "Can you not find the advertisement, Mr. Wilson?”", "sk": "Can you find the advertisement?", "skk": "그 광고문 찾으실 수 있겠어요?", "ko": "\"그 광고문 좀 찾아주시겠습니까, 윌슨 씨?\"", "pi": 5}, {"t": "“Yes, I have got it now,” he answered with his thick red finger planted halfway down the column.", "sk": "I have got it now, he answered.", "skk": "찾았습니다, 그가 대답했다.", "ko": "\"네, 찾았습니다,\" 그가 굵은 붉은 손가락을 신문 단 중간쯤에 짚은 채로 대답했다.", "pi": 5}, {"t": "Here it is. This is what began it all. You just read it for yourself, sir.”", "sk": "Here it is. This began it all. Read it for yourself.", "skk": "여기 있습니다. 이게 그 발단입니다. 직접 읽어보세요.", "ko": "\"여기 있습니다. 이게 다 이 일의 발단이지요. 직접 한번 읽어보시죠, 선생님.\"", "pi": 5}, {"t": "I took the paper from him and read as follows:", "sk": "I took the paper and read as follows:", "skk": "나는 신문을 받아 다음과 같이 읽었다.", "ko": "나는 그에게서 신문을 받아 다음과 같이 읽었다.", "pi": 5}, {"t": "TO THE RED-HEADED LEAGUE: On account of the bequest of the late Ezekiah Hopkins, of Lebanon, Pennsylvania, U.S.A., there is now another vacancy open which entitles a member of the League to a salary of £4 a week for purely nominal services.", "sk": "There is now a vacancy which entitles a member to a salary of £4 a week.", "skk": "지금 회원에게 주급 4파운드를 주는 결원이 하나 났다.", "ko": "\"레드헤디드 리그 앞: 고故 에제키아 홉킨스(펜실베이니아주 레바논 출신)의 유증에 따라, 이제 회원 한 명에게 명목상의 업무만으로 주급 4파운드를 지급하는 결원이 하나 새로 났음.\"", "pi": 5}, {"t": "All red-headed men who are sound in body and mind and above the age of twenty-one years, are eligible.", "sk": "All red-headed men are eligible.", "skk": "빨간 머리 남자는 모두 자격이 있다.", "ko": "\"몸과 정신이 멀쩡하고 나이가 21세 이상인 빨간 머리 남자는 누구든 자격이 있음.\"", "pi": 5}, {"t": "Apply in person on Monday, at eleven o'clock, to Duncan Ross, at the offices of the League, 7 Pope's Court, Fleet Street.", "sk": "Apply in person to Duncan Ross at the offices of the League.", "skk": "덩컨 로스 씨에게 리그 사무실로 직접 지원할 것.", "ko": "\"월요일 11시에, 덩컨 로스 씨에게, 리그 사무실(플리트 스트리트 포프스 코트 7번지)로 직접 지원할 것.\"", "pi": 5}, {"t": "“What on earth does this mean?” I ejaculated after I had twice read over the extraordinary announcement.", "sk": "What does this mean? I ejaculated.", "skk": "이게 대체 무슨 뜻이지? 내가 외쳤다.", "ko": "\"대체 이게 무슨 뜻일까?\" 나는 그 기이한 광고문을 두 번이나 읽고 나서 외쳤다.", "pi": 6}, {"t": "Holmes chuckled and wriggled in his chair, as was his habit when in high spirits.", "sk": "Holmes chuckled and wriggled in his chair.", "skk": "홈즈는 킬킬거리며 의자에서 몸을 꼬았다.", "ko": "홈즈는 기분이 좋을 때 늘 그러듯이, 킬킬 웃으며 의자에서 몸을 꼬았다.", "pi": 6}, {"t": "“It is a little off the beaten track, isn't it?” said he.", "sk": "It is a little off the beaten track, isn't it?", "skk": "좀 흔치 않은 일이죠, 안 그런가요?", "ko": "\"이거 참 흔치 않은 일이군요, 안 그렇습니까?\" 그가 말했다.", "pi": 6}, {"t": "“And now, Mr. Wilson, off you go at scratch and tell us all about yourself, your household, and the effect which this advertisement had upon your fortunes.", "sk": "Tell us all about yourself and the effect which this advertisement had upon your fortunes.", "skk": "당신 자신과, 이 광고가 당신 운에 미친 영향에 대해 다 말해주세요.", "ko": "\"자, 이제 윌슨 씨, 처음부터 시작해서 당신 자신과 가족, 그리고 이 광고가 당신 운에 어떤 영향을 미쳤는지 다 말해주시죠.", "pi": 6}, {"t": "You will first make a note, Doctor, of the paper and the date.”", "sk": "You will first make a note of the paper and the date.", "skk": "먼저 신문과 날짜를 적어두세요.", "ko": "\"먼저 왓슨 박사, 그 신문과 날짜부터 적어두시고.\"", "pi": 6}, {"t": "“It is The Morning Chronicle of April 27, 1890. Just two months ago.”", "sk": "It is The Morning Chronicle of April 27, 1890.", "skk": "1890년 4월 27일자 모닝 크로니클입니다.", "ko": "\"1890년 4월 27일자 모닝 크로니클이군요. 딱 두 달 전이네요.\"", "pi": 6}, {"t": "“Very good. Now, Mr. Wilson?”", "sk": "Now, Mr. Wilson?", "skk": "자, 윌슨 씨?", "ko": "\"좋습니다. 자, 윌슨 씨?\"", "pi": 6}, {"t": "“Well, it is just as I have been telling you, Mr. Sherlock Holmes,” said Jabez Wilson, mopping his forehead; “I have a small pawnbroker's business at Coburg Square, near the City.", "sk": "It is just as I have been telling you. I have a small pawnbroker's business at Coburg Square.", "skk": "제가 말씀드린 그대로입니다. 저는 코버그 스퀘어에서 작은 전당포를 하나 하고 있습니다.", "ko": "\"저, 제가 말씀드린 그대로입니다, 셜록 홈즈 씨,\" 이마의 땀을 닦으며 제이베즈 윌슨이 말했다. \"저는 시티 근처 코버그 스퀘어에서 작은 전당포를 하나 하고 있습니다.", "pi": 6}, {"t": "It's not a very large affair, and of late years it has not done more than just give me a living.", "sk": "It's not a very large affair, and it has not done more than give me a living.", "skk": "그리 큰 사업은 아니고, 최근 몇 년은 겨우 먹고살 정도밖에 못 벌었습니다.", "ko": "\"그리 큰 사업은 아니고, 최근 몇 년은 겨우 입에 풀칠할 정도밖에 벌지 못했습니다.\"", "pi": 6}, {"t": "I used to be able to keep two assistants, but now I only keep one; and I would have a job to pay him but that he is willing to come for half wages so as to learn the business.”", "sk": "I used to keep two assistants, but now I keep one, who works for half wages.", "skk": "예전엔 조수를 둘 뒀는데, 지금은 하나뿐이고, 그마저 반값 급여로 일합니다.", "ko": "\"예전엔 조수를 둘이나 뒀는데 지금은 하나뿐이고, 그마저 사업을 배우겠다며 반값 급여로 와 주지 않았으면 월급 주기도 힘들었을 겁니다.\"", "pi": 6}, {"t": "“What is the name of this obliging youth?” asked Sherlock Holmes.", "sk": "What is the name of this youth?", "skk": "그 젊은이 이름이 뭔가요?", "ko": "\"그 고분고분한 젊은이 이름이 뭡니까?\" 셜록 홈즈가 물었다.", "pi": 7}, {"t": "“His name is Vincent Spaulding, and he's not such a youth, either. It's hard to say his age.", "sk": "His name is Vincent Spaulding. It's hard to say his age.", "skk": "이름은 빈센트 스폴딩입니다. 나이는 가늠하기 어렵네요.", "ko": "\"이름은 빈센트 스폴딩입니다. 사실 그리 젊지도 않고요. 나이를 가늠하기가 어렵네요.\"", "pi": 7}, {"t": "I should not wish a smarter assistant, Mr. Holmes; and I know very well that he could better himself and earn twice what I am able to give him.", "sk": "I should not wish a smarter assistant, and I know that he could earn twice what I give him.", "skk": "이보다 나은 조수는 바랄 수 없고, 그가 지금 받는 것의 두 배는 벌 수 있다는 것도 압니다.", "ko": "\"저는 이보다 똑똑한 조수를 바랄 수도 없고요, 홈즈 씨. 그가 마음만 먹으면 더 나은 자리로 가서 제가 주는 것의 두 배는 벌 수 있다는 것도 잘 압니다.\"", "pi": 7}, {"t": "But, after all, if he is satisfied, why should I put ideas in his head?”", "sk": "If he is satisfied, why should I put ideas in his head?", "skk": "그가 만족한다면, 왜 제가 그의 머릿속에 생각을 넣어주겠어요?", "ko": "\"하지만 어쨌든, 그가 만족한다면, 제가 왜 그의 머릿속에 쓸데없는 생각을 넣어주겠습니까?\"", "pi": 7}, {"t": "“Why, indeed? You seem most fortunate in having an employé who comes under the full market price.", "sk": "You seem fortunate in having an employé who comes under the market price.", "skk": "시세보다 싸게 부리는 직원을 뒀으니 운이 좋아 보이는군요.", "ko": "\"그러게요, 정말? 시세보다 싼값에 부리는 직원을 두셨으니 참 운이 좋아 보이는군요.\"", "pi": 7}, {"t": "It is not a common experience among employers in this age.", "sk": "It is not a common experience among employers.", "skk": "요즘 고용주들 사이에서 흔한 경험은 아니죠.", "ko": "\"요즘 같은 시대에 고용주들 사이에서 흔한 경험은 아니지요.\"", "pi": 7}, {"t": "I don't know that your assistant is not as remarkable as your advertisement.”", "sk": "I don't know that your assistant is not as remarkable as your advertisement.", "skk": "당신 조수가 그 광고문 못지않게 놀랍지 않다고는 못 하겠군요.", "ko": "\"당신 조수도 그 광고문 못지않게 놀라운 사람이 아닐지, 저는 잘 모르겠군요.\"", "pi": 7}, {"t": "“Oh, he has his faults, too,” said Mr. Wilson. “Never was such a fellow for photography.", "sk": "He has his faults, too. Never was such a fellow for photography.", "skk": "그에게도 흠이 있긴 하죠. 사진에 그렇게 빠진 녀석은 또 없을 겁니다.", "ko": "\"아, 그에게도 흠이야 있죠,\" 윌슨 씨가 말했다. \"사진에 그렇게 빠진 녀석은 또 없을 겁니다.", "pi": 7}, {"t": "Snapping away with a camera when he ought to be improving his mind, and then diving down into the cellar like a rabbit into its hole to develop his pictures.", "sk": "He is snapping away with a camera and diving down into the cellar to develop his pictures.", "skk": "그는 카메라를 찍어대고, 지하실로 뛰어들어 사진을 현상합니다.", "ko": "\"정신 수양이라도 해야 할 시간에 카메라나 찍어대고, 그러고는 토끼가 굴로 뛰어들 듯 지하실로 뛰어들어가 사진을 현상하죠.\"", "pi": 7}, {"t": "That is his main fault, but on the whole he's a good worker. There's no vice in him.”", "sk": "That is his main fault, but he's a good worker. There's no vice in him.", "skk": "그게 그의 가장 큰 흠이지만, 대체로 일은 잘합니다. 나쁜 버릇은 없어요.", "ko": "\"그게 그의 가장 큰 흠이지만, 대체로 일은 잘하는 편입니다. 나쁜 버릇은 없어요.\"", "pi": 7}, {"t": "“He is still with you, I presume?”", "sk": "He is still with you?", "skk": "그가 아직 당신과 함께 있나요?", "ko": "\"그가 아직 당신과 함께 있겠지요?\"", "pi": 8}, {"t": "“Yes, sir. He and a girl of fourteen, who does a bit of simple cooking and keeps the place clean—that's all I have in the house, for I am a widower and never had any family.", "sk": "He and a girl of fourteen are all I have in the house, for I am a widower.", "skk": "그와 열네 살 소녀, 그게 집에 있는 전부입니다, 저는 홀아비라서요.", "ko": "\"네, 있습니다. 그와, 간단한 요리와 청소를 하는 열네 살짜리 소녀 하나, 집에 있는 건 그게 전부입니다. 저는 홀아비고 가족이 없었으니까요.\"", "pi": 8}, {"t": "We live very quietly, sir, the three of us; and we keep a roof over our heads and pay our debts, if we do nothing more.", "sk": "We live very quietly, and we keep a roof over our heads and pay our debts.", "skk": "우리 셋은 아주 조용히 살고, 지붕은 지키고 빚은 갚습니다.", "ko": "\"우리 셋은 아주 조용히 살고 있고요, 별거 아니어도 지붕은 지키고 빚은 갚으며 지냅니다.\"", "pi": 8}, {"t": "The first thing that put us out was that advertisement.", "sk": "The first thing that put us out was that advertisement.", "skk": "우리를 처음 뒤흔든 건 그 광고였습니다.", "ko": "\"우리를 처음 뒤흔들어 놓은 게 바로 그 광고였습니다.\"", "pi": 8}, {"t": "Spaulding, he came down into the office just this day eight weeks, with this very paper in his hand, and he says:", "sk": "Spaulding came into the office with this paper in his hand, and he says:", "skk": "스폴딩이 이 신문을 손에 들고 사무실로 내려와서 말했습니다.", "ko": "\"스폴딩이, 그가, 딱 팔 주 전 오늘 이 신문을 손에 들고 사무실로 내려오더니 이렇게 말하더군요.\"", "pi": 8}, {"t": "‘I wish to the Lord, Mr. Wilson, that I was a red-headed man.’", "sk": "I wish that I was a red-headed man.", "skk": "제가 빨간 머리였으면 좋겠어요.", "ko": "\"'제가 빨간 머리 남자였으면 정말 좋겠어요, 윌슨 씨.'\"", "pi": 8}, {"t": "‘Why that?’ I asks.", "sk": "Why that? I asks.", "skk": "왜요? 제가 물었죠.", "ko": "\"'왜 그러세요?' 제가 물었죠.\"", "pi": 8}, {"t": "‘Why,’ says he, ‘here's another vacancy on the League of the Red-headed Men. It's worth quite a little fortune to any man who gets it, and I understand that there are more vacancies than there are men, so that the trustees are at their wits' end what to do with the money.", "sk": "Here's another vacancy. It's worth a little fortune, and there are more vacancies than there are men.", "skk": "결원이 또 하나 났어요. 꽤 짭짤하고, 결원이 사람보다 더 많대요.", "ko": "\"'왜냐하면,' 그가 말하길, '레드헤디드 리그에 결원이 또 하나 났거든요. 그걸 얻는 사람한테는 꽤 짭짤한 벌이가 될 텐데, 제가 알기론 결원이 사람보다 많아서 이사들이 그 돈을 어쩌지 못해 쩔쩔맨다더군요.'\"", "pi": 8}, {"t": "If my hair would only change colour, here's a nice little crib all ready for me to step into.’", "sk": "If my hair would change colour, here's a nice little crib for me to step into.", "skk": "제 머리색만 바뀐다면, 딱 맞는 자리가 하나 기다리고 있을 텐데요.", "ko": "\"'제 머리색만 바뀐다면, 제가 들어가기 딱 좋은 자리가 하나 마련되어 있을 텐데요.'\"", "pi": 8}, {"t": "‘Why, what is it, then?’ I asked.", "sk": "Why, what is it? I asked.", "skk": "그게 뭔데요? 제가 물었어요.", "ko": "\"'아니, 그게 대체 뭔데요?' 제가 물었어요.\"", "pi": 8}, {"t": "‘Have you never heard of the League of the Red-headed Men?’", "sk": "Have you never heard of the League of the Red-headed Men?", "skk": "레드헤디드 맨스 리그에 대해 들어본 적 없어요?", "ko": "\"'레드헤디드 맨스 리그에 대해 들어본 적 없으세요?'\"", "pi": 8}, {"t": "‘Never.’", "sk": "Never.", "skk": "전혀요.", "ko": "\"'전혀요.'\"", "pi": 9}, {"t": "‘Why, I wonder at that, for you are eligible yourself for one of the vacancies.’", "sk": "I wonder at that, for you are eligible for one of the vacancies.", "skk": "그게 놀랍네요, 당신도 결원 하나에 자격이 있는데.", "ko": "\"'거참 놀랍네요, 당신도 그 결원들 중 하나에 자격이 있는데 말이에요.'\"", "pi": 9}, {"t": "‘And what are they worth?’ I asked.", "sk": "What are they worth? I asked.", "skk": "그게 얼마나 되나요? 제가 물었어요.", "ko": "\"'그럼 그게 얼마나 값어치가 있나요?' 제가 물었습니다.\"", "pi": 9}, {"t": "‘Oh, merely a couple of hundred a year, but the work is slight, and it need not interfere very much with one's other occupations.’", "sk": "It is merely a couple of hundred a year, but the work is slight.", "skk": "그저 1년에 이백 파운드 남짓인데, 일은 가볍습니다.", "ko": "\"'아, 그저 1년에 이백 파운드 남짓인데, 일이 가벼워서 다른 일에 크게 지장을 주지 않아요.'\"", "pi": 9}, {"t": "He was himself red-headed, and he had a great sympathy for all red-headed men; so, when he died, it was found that he had left his enormous fortune in the hands of trustees, with instructions to apply the interest to the providing of easy berths to men whose hair is of that colour.", "sk": "He was red-headed, and he left his fortune to trustees, with instructions to provide easy berths to red-headed men.", "skk": "그도 빨간 머리였고, 이사들에게 재산을 남기며 빨간 머리 남자들에게 편한 자리를 마련해주라고 지시했습니다.", "ko": "\"그 사람도 빨간 머리였고, 빨간 머리 남자들 전부에게 큰 동질감을 느꼈답니다. 그래서 그가 죽었을 때 보니, 자기 막대한 재산을 이사들 손에 맡기면서, 그 이자로 그런 머리색을 가진 남자들에게 편한 자리를 마련해주라는 지시를 남겨뒀더군요.\"", "pi": 9}, {"t": "‘But,’ said I, ‘there would be millions of red-headed men who would apply.’", "sk": "There would be millions of red-headed men who would apply.", "skk": "지원할 빨간 머리 남자가 수백만 명은 될 텐데요.", "ko": "\"'하지만,' 제가 말했죠, '지원할 빨간 머리 남자가 수백만 명은 될 텐데요.'\"", "pi": 9}, {"t": "‘Not so many as you might think,’ he answered.", "sk": "Not so many as you might think, he answered.", "skk": "생각만큼 많지는 않을 거예요, 그가 대답했다.", "ko": "\"'생각하시는 것만큼 많지는 않을 거예요,' 그가 대답했습니다.\"", "pi": 9}, {"t": "‘You see it is really confined to Londoners, and to grown men. This American had started from London when he was young, and he wanted to do the old town a good turn.", "sk": "It is confined to Londoners and to grown men. This American wanted to do the old town a good turn.", "skk": "런던 사람과 성인 남자로 제한돼요. 이 미국인이 런던에 은혜를 갚고 싶어했거든요.", "ko": "\"'그게, 사실 런던 사람들에다 성인 남자로 제한돼 있어요. 이 미국인이 젊었을 때 런던에서 출발했었는데, 이 도시에 은혜를 갚고 싶어했거든요.\"", "pi": 9}, {"t": "Then, again, I have heard it is no use your applying if your hair is light red, or dark red, or anything but real bright, blazing, fiery red.’", "sk": "I have heard it is no use applying if your hair is anything but real bright red.", "skk": "머리가 진짜 새빨간 색이 아니면 지원해도 소용없다고 들었어요.", "ko": "\"'그리고 또, 머리가 연한 빨강이나 진한 빨강, 그러니까 진짜 밝고 타오르는 듯한 새빨강이 아니면 지원해봐야 소용없다고 들었어요.'\"", "pi": 9}, {"t": "Now, if you cared to apply, Mr. Wilson, you would just walk in; but perhaps it would hardly be worth your while to put yourself out of the way for the sake of a few hundred pounds.’", "sk": "If you cared to apply, you would just walk in; but it would hardly be worth your while.", "skk": "지원하고 싶으시면 그냥 걸어 들어가시면 될 텐데, 그럴 만한 가치는 거의 없을 거예요.", "ko": "\"'그러니 지원하고 싶으시면, 윌슨 씨, 그냥 걸어 들어가시면 됩니다. 하지만 몇백 파운드 때문에 굳이 그렇게까지 하실 만한 가치는 거의 없을 거예요.'\"", "pi": 10}, {"t": "Now, it is a fact, gentlemen, as you may see for yourselves, that my hair is of a very full and rich tint, so that it seemed to me that if there was to be any competition in the matter I stood as good a chance as any man that I had ever met.", "sk": "It is a fact that my hair is of a very rich tint, so I stood as good a chance as any man.", "skk": "제 머리가 아주 짙은 색이라는 게 사실이라, 저도 누구 못지않은 가능성이 있었습니다.", "ko": "\"자, 신사분들도 직접 보시다시피, 제 머리가 아주 숱 많고 짙은 색조라는 건 사실이라서, 만약 이 일에 경쟁이 있다면 저도 제가 지금까지 만난 그 누구 못지않은 가능성이 있어 보였습니다.\"", "pi": 10}, {"t": "Vincent Spaulding seemed to know so much about it that I thought he might prove useful, so I just ordered him to put up the shutters for the day and to come right away with me.", "sk": "Vincent Spaulding seemed to know so much about it, so I ordered him to come with me.", "skk": "빈센트 스폴딩이 그것에 대해 아주 잘 아는 것 같아서, 저는 그에게 저와 함께 가자고 시켰습니다.", "ko": "\"빈센트 스폴딩이 그 일에 대해 아주 잘 아는 것 같아서 도움이 될 거라 생각했고, 그래서 그날은 가게 셔터를 내리고 저와 함께 바로 나서라고 시켰습니다.\"", "pi": 10}, {"t": "He was very willing to have a holiday, so we shut the business up and started off for the address that was given us in the advertisement.", "sk": "He was willing to have a holiday, so we shut the business up and started off for the address.", "skk": "그는 기꺼이 하루 쉬려 했고, 그래서 우리는 가게 문을 닫고 그 주소로 출발했습니다.", "ko": "\"그는 기꺼이 하루 쉬려 했고, 그래서 우리는 가게 문을 닫고 광고에 나와 있던 그 주소로 출발했습니다.\"", "pi": 10}, {"t": "I never hope to see such a sight as that again, Mr. Holmes.", "sk": "I never hope to see such a sight as that again.", "skk": "저는 다시는 그런 광경을 보고 싶지 않습니다, 홈즈 씨.", "ko": "\"저는 다시는 그런 광경을 보고 싶지 않습니다, 홈즈 씨.\"", "pi": 10}, {"t": "From north, south, east, and west every man who had a shade of red in his hair had tramped into the city to answer the advertisement.", "sk": "From north, south, east, and west every man had tramped into the city to answer the advertisement.", "skk": "북쪽, 남쪽, 동쪽, 서쪽에서 머리에 붉은 기가 있는 사람마다 도시로 몰려들어왔습니다.", "ko": "\"북쪽에서, 남쪽에서, 동쪽에서, 서쪽에서, 머리에 붉은 기가 조금이라도 있는 사람이면 누구나 그 광고에 응하려고 도시로 터벅터벅 걸어들어왔습니다.\"", "pi": 10}, {"t": "Fleet Street was choked with red-headed folk, and Pope’s Court looked like a coster’s orange barrow.", "sk": "Fleet Street was choked with red-headed folk, and Pope’s Court looked like a coster’s orange barrow.", "skk": "플리트 가는 빨간 머리 사람들로 발 디딜 틈이 없었고, 포프스 코트는 노점상의 오렌지 손수레 같았습니다.", "ko": "\"플리트 가는 빨간 머리 사람들로 발 디딜 틈이 없었고, 포프스 코트는 노점상이 오렌지를 쌓아놓은 손수레 같았습니다.\"", "pi": 10}, {"t": "I should not have thought there were so many in the whole country as were brought together by that single advertisement.", "sk": "I should not have thought there were so many in the whole country.", "skk": "나라 전체에 그렇게 많은 사람이 있으리라고는 생각하지 못했을 겁니다.", "ko": "\"광고 하나로 모인 그 사람들만큼 나라 전체에 그렇게 많은 이가 있으리라고는 생각하지 못했을 겁니다.\"", "pi": 10}, {"t": "Every shade of colour they were—straw, lemon, orange, brick, Irish-setter, liver, clay; but, as Spaulding said, there were not many who had the real vivid flame-coloured tint.", "sk": "They were every shade of colour, but there were not many who had the real vivid flame-coloured tint.", "skk": "색조는 다양했지만, 진짜 선명한 불꽃색을 가진 사람은 많지 않았습니다.", "ko": "\"색조도 갖가지였습니다—밀짚색, 레몬색, 오렌지색, 벽돌색, 아이리시세터색, 간색, 점토색까지. 하지만 스폴딩 말대로 진짜 선명한 불꽃색 색조를 가진 사람은 많지 않았습니다.\"", "pi": 10}, {"t": "When I saw how many were waiting, I would have given it up in despair; but Spaulding would not hear of it.", "sk": "When I saw how many were waiting, I would have given it up; but Spaulding would not hear of it.", "skk": "얼마나 많이 기다리는지 보고 절망 속에 포기했을 텐데, 스폴딩이 못 하게 했습니다.", "ko": "\"얼마나 많은 사람이 기다리고 있는지 보고는 절망 속에 포기했을 텐데, 스폴딩이 그럴 생각도 못 하게 했습니다.\"", "pi": 10}, {"t": "How he did it I could not imagine, but he pushed and pulled and butted until he got me through the crowd, and right up to the steps which led to the office.", "sk": "I could not imagine how he did it, but he pushed and pulled and butted until he got me through the crowd.", "skk": "그가 어떻게 했는지 알 수 없지만, 그는 밀고 당기고 부딪치며 저를 인파 사이로 뚫고 나갔습니다.", "ko": "\"그가 어떻게 그렇게 했는지 저는 상상도 할 수 없지만, 그는 밀고 당기고 몸으로 부딪치며 저를 인파 사이로, 그리고 사무실로 이어지는 계단까지 곧장 데려갔습니다.\"", "pi": 10}, {"t": "There was a double stream upon the stair, some going up in hope, and some coming back dejected; but we wedged in as well as we could and soon found ourselves in the office.", "sk": "There was a double stream upon the stair; but we wedged in and soon found ourselves in the office.", "skk": "계단에는 두 갈래 흐름이 있었지만, 우리는 비집고 들어가 곧 사무실에 다다랐습니다.", "ko": "\"계단에는 두 갈래 흐름이 있었는데, 어떤 이들은 희망을 품고 올라가고 어떤 이들은 풀 죽어 내려왔습니다. 하지만 우리는 최대한 비집고 들어가 곧 사무실에 다다랐습니다.\"", "pi": 10}, {"t": "There was nothing in the office but a couple of wooden chairs and a deal table, behind which sat a small man with a head that was even redder than mine.", "sk": "There was nothing in the office but a couple of chairs and a table, behind which sat a small man with a head that was even redder than mine.", "skk": "사무실에는 의자 두 개와 탁자 하나뿐이었고, 그 뒤에 저보다 더 빨간 머리를 한 작은 남자가 앉아 있었습니다.", "ko": "\"사무실에는 나무 의자 두 개와 소나무 탁자 하나 말고는 아무것도 없었고, 그 뒤에는 저보다도 더 빨간 머리를 한 작은 남자가 앉아 있었습니다.\"", "pi": 11}, {"t": "He said a few words to each candidate as he came up, and then he always managed to find some fault in them which would disqualify them.", "sk": "He said a few words to each candidate, and then he managed to find some fault in them.", "skk": "그는 지원자마다 몇 마디씩 건넸고, 그다음엔 항상 흠을 찾아냈습니다.", "ko": "\"그는 지원자가 다가올 때마다 몇 마디씩 건넸고, 그러고 나서는 늘 그들을 실격시킬 만한 흠을 하나씩 찾아냈습니다.\"", "pi": 11}, {"t": "Getting a vacancy did not seem to be such a very easy matter, after all.", "sk": "Getting a vacancy did not seem to be such an easy matter, after all.", "skk": "결원을 얻는 게 결국 그렇게 쉬운 일은 아닌 것 같았습니다.", "ko": "\"결원 하나를 따내는 게 결국 그리 쉬운 일은 아닌 것 같았습니다.\"", "pi": 11}, {"t": "However, when our turn came the little man was much more favourable to me than to any of the others, and he closed the door as we entered, so that he might have a private word with us.", "sk": "When our turn came the little man was much more favourable to me than to the others, and he closed the door so that he might have a private word with us.", "skk": "우리 차례가 되자 그 작은 남자는 다른 사람들보다 저에게 훨씬 호의적이었고, 은밀한 이야기를 하려고 문을 닫았습니다.", "ko": "\"하지만 우리 차례가 되자 그 작은 남자는 다른 사람들보다 저에게 훨씬 더 호의적이었고, 우리가 들어서자 문을 닫아서 우리와 은밀한 이야기를 나누려 했습니다.\"", "pi": 11}, {"t": "‘This is Mr. Jabez Wilson,’ said my assistant, ‘and he is willing to fill a vacancy in the League.’", "sk": "This is Mr. Jabez Wilson, said my assistant, and he is willing to fill a vacancy in the League.", "skk": "이쪽은 제이비즈 윌슨 씨입니다, 제 조수가 말했다, 그리고 그는 리그의 결원을 채우고 싶어합니다.", "ko": "\"'이쪽은 제이비즈 윌슨 씨입니다,' 제 조수가 말했습니다, '그리고 이분이 리그의 결원을 채우고 싶어 하십니다.'\"", "pi": 11}, {"t": "‘And he is admirably suited for it,’ the other answered.", "sk": "He is admirably suited for it, the other answered.", "skk": "이분은 훌륭하게 적합합니다, 상대가 대답했다.", "ko": "\"'그리고 이분은 여기에 더할 나위 없이 적합합니다,' 상대편이 대답했습니다.\"", "pi": 11}, {"t": "‘He has every requirement.", "sk": "He has every requirement.", "skk": "이분은 모든 조건을 다 갖췄습니다.", "ko": "\"'이분은 모든 요건을 다 갖췄습니다.'\"", "pi": 11}, {"t": "I cannot recall when I have seen anything so fine.’", "sk": "I cannot recall when I have seen anything so fine.", "skk": "이렇게 훌륭한 걸 언제 봤는지 기억이 안 납니다.", "ko": "\"'이렇게 훌륭한 걸 언제 봤는지 기억이 안 날 정도입니다.'\"", "pi": 11}, {"t": "He took a step backward, cocked his head on one side, and gazed at my hair until I felt quite bashful.", "sk": "He took a step backward, cocked his head on one side, and gazed at my hair until I felt bashful.", "skk": "그는 한 걸음 물러서서 고개를 갸웃하고, 제가 수줍어질 때까지 제 머리를 바라봤습니다.", "ko": "\"그는 한 걸음 뒤로 물러서더니 고개를 한쪽으로 갸웃하고는, 제가 꽤 겸연쩍어질 때까지 제 머리를 바라봤습니다.\"", "pi": 11}, {"t": "Then suddenly he plunged forward, wrung my hand, and congratulated me warmly on my success.", "sk": "Then he plunged forward, wrung my hand, and congratulated me on my success.", "skk": "그러다 갑자기 그는 앞으로 달려들어 제 손을 꽉 쥐고, 제 성공을 축하해줬습니다.", "ko": "\"그러다 갑자기 그는 앞으로 달려들듯 다가와 제 손을 꽉 쥐고는, 제 성공을 열렬히 축하해줬습니다.\"", "pi": 11}, {"t": "‘It would be injustice to hesitate,’ said he.", "sk": "It would be injustice to hesitate, said he.", "skk": "망설이는 건 부당한 일이겠죠, 그가 말했다.", "ko": "\"'망설이는 건 부당한 일일 겁니다,' 그가 말했습니다.\"", "pi": 12}, {"t": "‘You will, however, I am sure, excuse me for taking an obvious precaution.’", "sk": "You will excuse me for taking an obvious precaution.", "skk": "당연한 예방 조치를 취하는 걸 양해해 주시겠죠.", "ko": "\"'하지만 당연한 예방 조치를 하나 취하는 걸 양해해 주시리라 믿습니다.'\"", "pi": 12}, {"t": "With that he seized my hair in both his hands, and tugged until I yelled with the pain.", "sk": "He seized my hair in both his hands, and tugged until I yelled with the pain.", "skk": "그러면서 그는 양손으로 제 머리를 움켜쥐고, 제가 아파서 소리 지를 때까지 잡아당겼습니다.", "ko": "\"그러면서 그는 양손으로 제 머리카락을 움켜쥐고는, 제가 아파서 소리를 지를 때까지 잡아당겼습니다.\"", "pi": 12}, {"t": "‘There is water in your eyes,’ said he as he released me.", "sk": "There is water in your eyes, said he as he released me.", "skk": "눈에 눈물이 고였네요, 그가 저를 놓아주며 말했다.", "ko": "\"'눈에 눈물이 고였군요,' 그는 저를 놓아주며 말했습니다.\"", "pi": 12}, {"t": "‘I perceive that all is as it should be.", "sk": "I perceive that all is as it should be.", "skk": "모든 게 제대로인 것 같군요.", "ko": "\"'모든 게 마땅히 그래야 할 대로군요.'\"", "pi": 12}, {"t": "But we have to be careful, for we have twice been deceived by wigs and once by paint.", "sk": "We have to be careful, for we have been deceived by wigs and by paint.", "skk": "하지만 조심해야 해요, 가발과 화장품에 두 번, 한 번 속은 적이 있거든요.", "ko": "\"하지만 조심해야 합니다, 가발에 두 번, 화장품에 한 번 속은 적이 있으니까요.\"", "pi": 12}, {"t": "I could tell you tales of cobbler’s wax which would disgust you with human nature.’", "sk": "I could tell you tales of cobbler’s wax which would disgust you.", "skk": "구두장이용 왁스에 관한 이야기를 들려드리면 넌더리가 나실 겁니다.", "ko": "\"'구둣방 왁스에 얽힌 이야기들을 들려드리면 인간이란 존재에 넌더리가 나실 겁니다.'\"", "pi": 12}, {"t": "He stepped over to the window and shouted through it at the top of his voice that the vacancy was filled.", "sk": "He stepped over to the window and shouted that the vacancy was filled.", "skk": "그는 창가로 가서 결원이 다 찼다고 목청껏 외쳤습니다.", "ko": "\"그는 창가로 걸어가더니 목청껏 소리쳐 결원이 다 찼다고 외쳤습니다.\"", "pi": 12}, {"t": "A groan of disappointment came up from below, and the folk all trooped away in different directions until there was not a red-head to be seen except my own and that of the manager.", "sk": "A groan of disappointment came up from below, and the folk trooped away until there was not a red-head to be seen except mine and the manager’s.", "skk": "아래에서 실망의 신음이 올라왔고, 사람들이 흩어져서 제 머리와 매니저의 머리만 남았습니다.", "ko": "\"아래에서 실망한 신음 소리가 올라왔고, 사람들은 사방으로 흩어져 가버려서 이제 빨간 머리라곤 제 것과 그 매니저의 것 말고는 남지 않았습니다.\"", "pi": 12}, {"t": "‘My name,’ said he, ‘is Mr. Duncan Ross, and I am myself one of the pensioners upon the fund left by our noble benefactor.", "sk": "My name is Mr. Duncan Ross, and I am one of the pensioners upon the fund left by our benefactor.", "skk": "제 이름은 던컨 로스이고, 저도 그 기금의 수혜자 중 하나입니다.", "ko": "\"'제 이름은,' 그가 말했습니다, '던컨 로스이고, 저도 우리의 그 고귀한 은인이 남긴 기금의 수혜자 중 한 명입니다.'\"", "pi": 12}, {"t": "Are you a married man, Mr. Wilson?", "sk": "Are you a married man?", "skk": "결혼하셨나요, 윌슨 씨?", "ko": "\"'결혼하셨나요, 윌슨 씨?'\"", "pi": 12}, {"t": "Have you a family?’", "sk": "Have you a family?", "skk": "가족은 있으신가요?", "ko": "\"'가족은 있으신가요?'\"", "pi": 12}, {"t": "I answered that I had not.", "sk": "I answered that I had not.", "skk": "저는 아니라고 대답했습니다.", "ko": "\"저는 아니라고 대답했습니다.\"", "pi": 13}, {"t": "His face fell immediately.", "sk": "His face fell immediately.", "skk": "그의 얼굴이 대번에 어두워졌습니다.", "ko": "\"그의 얼굴이 대번에 어두워졌습니다.\"", "pi": 13}, {"t": "‘Dear me!’ he said gravely, ‘that is very serious indeed!", "sk": "Dear me! He said gravely, that is very serious indeed!", "skk": "이런! 그가 근엄하게 말했다, 그거 참 심각하군요!", "ko": "\"'이런!' 그가 근엄하게 말했습니다, '그것 참 심각한 일이군요!'\"", "pi": 13}, {"t": "I am sorry to hear you say that.", "sk": "I am sorry to hear you say that.", "skk": "그렇게 말씀하시니 유감이군요.", "ko": "\"'그렇게 말씀하시니 유감이군요.'\"", "pi": 13}, {"t": "The fund was, of course, for the propagation and spread of the red-heads as well as for their maintenance.", "sk": "The fund was for the propagation and spread of the red-heads as well as for their maintenance.", "skk": "그 기금은 물론 빨간 머리들의 번식과 확산을 위한 것이지, 그들의 존속만을 위한 게 아니었습니다.", "ko": "\"'그 기금은 물론 빨간 머리들을 부양하는 것뿐 아니라, 그들의 번식과 확산을 위한 것이기도 합니다.'\"", "pi": 13}, {"t": "It is exceedingly unfortunate that you should be a bachelor.’", "sk": "It is exceedingly unfortunate that you should be a bachelor.", "skk": "당신이 독신이라는 게 대단히 불행한 일이군요.", "ko": "\"'당신이 독신이라니 그것 참 대단히 딱한 일이군요.'\"", "pi": 13}, {"t": "My face lengthened at this, Mr. Holmes, for I thought that I was not to have the vacancy after all; but after thinking it over for a few minutes he said that it would be all right.", "sk": "My face lengthened at this, for I thought that I was not to have the vacancy after all; but he said that it would be all right.", "skk": "이 말에 제 얼굴이 길어졌습니다, 결국 결원 자리를 못 얻는구나 싶었거든요, 하지만 그는 괜찮을 거라고 말했습니다.", "ko": "\"이 말에 제 얼굴이 울상이 됐습니다, 홈즈 씨, 결국 그 자리를 얻지 못하는구나 싶었으니까요, 하지만 몇 분간 생각해보더니 그가 괜찮을 거라고 말했습니다.\"", "pi": 13}, {"t": "‘In the case of another,’ said he, ‘the objection might be fatal, but we must stretch a point in favour of a man with such a head of hair as yours.", "sk": "In the case of another, the objection might be fatal, but we must stretch a point in favour of a man with such a head of hair as yours.", "skk": "다른 사람의 경우라면, 그 문제가 치명적일 수도 있지만, 당신 같은 머리를 가진 사람을 위해서는 규칙을 좀 봐줘야겠지요.", "ko": "\"'다른 사람의 경우였다면,' 그가 말했습니다, '그 반대 사유가 치명적이었을지도 모릅니다, 하지만 당신처럼 그런 머리를 가진 분을 위해서는 저희가 규칙을 좀 봐드려야겠지요.'\"", "pi": 13}, {"t": "When shall you be able to enter upon your new duties?’", "sk": "When shall you be able to enter upon your new duties?", "skk": "새 직무를 언제부터 시작하실 수 있나요?", "ko": "\"'새 직무를 언제부터 맡으실 수 있겠습니까?'\"", "pi": 13}, {"t": "‘Well, it is a little awkward, for I have a business already,’ said I.", "sk": "It is a little awkward, for I have a business already, said I.", "skk": "조금 곤란한데요, 이미 하는 사업이 있어서요, 제가 말했다.", "ko": "\"'글쎄요, 그게 좀 곤란한데요, 이미 하고 있는 사업이 있어서요,' 제가 말했습니다.\"", "pi": 13}, {"t": "‘Oh, never mind about that, Mr. Wilson!’ said Vincent Spaulding.", "sk": "Never mind about that, Mr. Wilson, said Vincent Spaulding.", "skk": "그건 신경 쓰지 마세요, 윌슨 씨, 빈센트 스폴딩이 말했다.", "ko": "\"'오, 그건 신경 쓰지 마세요, 윌슨 씨!' 빈센트 스폴딩이 말했습니다.\"", "pi": 13}, {"t": "‘I should be able to look after that for you.’", "sk": "I should be able to look after that for you.", "skk": "제가 그건 대신 봐드릴 수 있을 겁니다.", "ko": "\"'제가 그건 당신 대신 봐드릴 수 있을 겁니다.'\"", "pi": 13}, {"t": "‘What would be the hours?’ I asked.", "sk": "What would be the hours? I asked.", "skk": "근무 시간이 어떻게 되나요? 제가 물었다.", "ko": "\"'근무 시간이 어떻게 되나요?' 제가 물었습니다.\"", "pi": 14}, {"t": "‘Ten to two.’", "sk": "Ten to two.", "skk": "10시부터 2시까지요.", "ko": "\"'열 시부터 두 시까지요.'\"", "pi": 14}, {"t": "Now a pawnbroker’s business is mostly done of an evening, Mr. Holmes, especially Thursday and Friday evening, which is just before pay-day; so it would suit me very well to earn a little in the mornings.", "sk": "A pawnbroker’s business is mostly done of an evening, especially before pay-day; so it would suit me very well to earn a little in the mornings.", "skk": "전당포 업은 대개 저녁에 이루어지는데, 특히 월급날 직전에 그러니, 아침에 조금 버는 게 저한테 잘 맞겠죠.", "ko": "\"전당포 업이라는 게 대개 저녁에, 특히 월급날 직전인 목요일과 금요일 저녁에 이루어지는지라, 홈즈 씨, 아침 시간에 조금이나마 버는 게 저한테는 아주 잘 맞을 것 같았습니다.\"", "pi": 14}, {"t": "Besides, I knew that my assistant was a good man, and that he would see to anything that turned up.", "sk": "Besides, I knew that my assistant was a good man, and that he would see to anything that turned up.", "skk": "게다가 저는 제 조수가 좋은 사람이고, 무슨 일이 생기든 그가 처리해줄 거란 걸 알고 있었습니다.", "ko": "\"게다가 저는 제 조수가 좋은 사람이고, 무슨 일이 생기든 그가 알아서 처리해줄 거라는 걸 알고 있었습니다.\"", "pi": 14}, {"t": "‘That would suit me very well,’ said I.", "sk": "That would suit me very well, said I.", "skk": "그거 저한테 아주 잘 맞겠네요, 제가 말했다.", "ko": "\"'그거 저한테 아주 잘 맞겠네요,' 제가 말했습니다.\"", "pi": 14}, {"t": "‘And the pay?’", "sk": "And the pay?", "skk": "그리고 급여는요?", "ko": "\"'그러면 급여는요?'\"", "pi": 14}, {"t": "‘Is £4 a week.’", "sk": "Is £4 a week.", "skk": "주급 4파운드입니다.", "ko": "\"'주급 4파운드입니다.'\"", "pi": 14}, {"t": "‘And the work?’", "sk": "And the work?", "skk": "그럼 업무는요?", "ko": "\"'그럼 일은요?'\"", "pi": 14}, {"t": "‘Is purely nominal.’", "sk": "Is purely nominal.", "skk": "순전히 명목상이에요.", "ko": "\"'순전히 명목상일 뿐입니다.'\"", "pi": 14}, {"t": "‘What do you call purely nominal?’", "sk": "What do you call purely nominal?", "skk": "순전히 명목상이라는 게 무슨 뜻인가요?", "ko": "\"'순전히 명목상이라는 게 무슨 말씀이신가요?'\"", "pi": 14}, {"t": "‘Well, you have to be in the office, or at least in the building, the whole time.", "sk": "You have to be in the office, or at least in the building, the whole time.", "skk": "사무실에, 최소한 건물 안에 내내 있어야 해요.", "ko": "\"'글쎄요, 사무실 안에, 적어도 건물 안에는 그 시간 내내 계셔야 합니다.'\"", "pi": 14}, {"t": "If you leave, you forfeit your whole position forever.", "sk": "If you leave, you forfeit your whole position forever.", "skk": "떠나면, 그 자리를 영영 잃게 됩니다.", "ko": "\"떠나시면, 그 자리 전체를 영영 잃게 됩니다.\"", "pi": 14}, {"t": "The will is very clear upon that point.", "sk": "The will is very clear upon that point.", "skk": "유언장이 그 점에 대해서는 아주 명확합니다.", "ko": "\"유언장이 그 점에 대해서는 아주 명확합니다.\"", "pi": 14}, {"t": "You don’t comply with the conditions if you budge from the office during that time.’", "sk": "You don’t comply with the conditions if you budge from the office during that time.", "skk": "그 시간 동안 사무실에서 조금이라도 벗어나면 조건을 지키지 않는 게 됩니다.", "ko": "\"'그 시간 동안 사무실에서 한 발짝이라도 벗어나면 조건을 지키지 않는 셈이 됩니다.'\"", "pi": 14}, {"t": "‘It’s only four hours a day, and I should not think of leaving,’ said I.", "sk": "It’s only four hours a day, and I should not think of leaving, said I.", "skk": "하루 네 시간뿐인데, 떠날 생각은 안 할 겁니다, 제가 말했다.", "ko": "\"'하루에 네 시간뿐인데, 떠날 생각은 하지 않을 겁니다,' 제가 말했습니다.\"", "pi": 15}, {"t": "‘No excuse will avail,’ said Mr. Duncan Ross; ‘neither sickness nor business nor anything else.", "sk": "No excuse will avail, said Mr. Duncan Ross; neither sickness nor business nor anything else.", "skk": "어떤 변명도 소용없습니다, 던컨 로스가 말했다; 병도, 사업도, 그 무엇도요.", "ko": "\"'어떤 변명도 소용없습니다,' 던컨 로스 씨가 말했습니다, '병도, 사업도, 그 무엇도 안 됩니다.'\"", "pi": 15}, {"t": "There you must stay, or you lose your billet.’", "sk": "There you must stay, or you lose your billet.", "skk": "거기 계속 있어야 합니다, 아니면 일자리를 잃게 됩니다.", "ko": "\"'그곳에 계속 계셔야 합니다, 그러지 않으면 일자리를 잃게 되고요.'\"", "pi": 15}, {"t": "‘And the work?’", "sk": "And the work?", "skk": "그럼 일은요?", "ko": "\"'그럼 하는 일은요?'\"", "pi": 15}, {"t": "‘Is to copy out the Encyclopædia Britannica.", "sk": "Is to copy out the Encyclopædia Britannica.", "skk": "브리태니커 백과사전을 옮겨 적는 일입니다.", "ko": "\"'브리태니커 백과사전을 처음부터 끝까지 옮겨 적는 겁니다.'\"", "pi": 15}, {"t": "There is the first volume of it in that press.", "sk": "There is the first volume of it in that press.", "skk": "저 장롱 안에 그것의 첫째 권이 있습니다.", "ko": "\"저 장롱 안에 그 첫째 권이 있습니다.\"", "pi": 15}, {"t": "You must find your own ink, pens, and blotting-paper, but we provide this table and chair.", "sk": "You must find your own ink, pens, and blotting-paper, but we provide this table and chair.", "skk": "잉크, 펜, 압지는 직접 준비해야 하지만, 이 탁자와 의자는 저희가 제공합니다.", "ko": "\"잉크와 펜, 압지는 직접 마련하셔야 하지만, 이 탁자와 의자는 저희가 제공해드립니다.\"", "pi": 15}, {"t": "Will you be ready to-morrow?’", "sk": "Will you be ready to-morrow?", "skk": "내일 준비되시겠어요?", "ko": "\"'내일 준비되시겠습니까?'\"", "pi": 15}, {"t": "‘Certainly,’ I answered.", "sk": "Certainly, I answered.", "skk": "물론이죠, 제가 대답했다.", "ko": "\"'물론입니다,' 제가 대답했습니다.\"", "pi": 15}, {"t": "‘Then, good-bye, Mr. Jabez Wilson, and let me congratulate you once more on the important position which you have been fortunate enough to gain.’", "sk": "Then, good-bye, Mr. Jabez Wilson, and let me congratulate you on the important position which you have been fortunate enough to gain.", "skk": "그럼 안녕히 가세요, 제이비즈 윌슨 씨, 운 좋게 얻으신 이 중요한 자리를 다시 한 번 축하드립니다.", "ko": "\"'그럼 안녕히 가십시오, 제이비즈 윌슨 씨, 운 좋게도 얻으신 이 중요한 자리를 다시 한번 축하드립니다.'\"", "pi": 15}, {"t": "He bowed me out of the room and I went home with my assistant, hardly knowing what to say or do, I was so pleased at my own good fortune.", "sk": "He bowed me out of the room and I went home with my assistant, hardly knowing what to say or do, I was so pleased at my own good fortune.", "skk": "그는 저를 배웅했고 저는 조수와 집으로 갔습니다, 무슨 말이나 행동을 해야 할지 거의 모른 채, 제 행운이 너무 기뻤거든요.", "ko": "\"그는 저를 방 밖으로 배웅해줬고, 저는 제 조수와 함께 집으로 갔는데, 제 행운이 너무 기쁜 나머지 무슨 말이나 행동을 해야 할지 거의 몰랐습니다.\"", "pi": 15}, {"t": "Well, I thought over the matter all day, and by evening I was in low spirits again; for I had quite persuaded myself that the whole affair must be some great hoax or fraud, though what its object might be I could not imagine.", "sk": "I thought over the matter all day, and by evening I was in low spirits again; for I had persuaded myself that the whole affair must be some great hoax or fraud.", "skk": "저는 하루 종일 그 일을 곱씹었고, 저녁이 되자 다시 우울해졌습니다, 이 모든 일이 큰 사기극이 틀림없다고 확신했거든요.", "ko": "\"저는 하루 종일 그 일을 곱씹었고, 저녁이 되자 다시 기분이 가라앉았습니다, 이 모든 일이 어떤 대단한 사기극이나 협잡이 틀림없다고 스스로 완전히 믿어버렸으니까요, 그 목적이 뭔지는 상상도 안 갔지만요.\"", "pi": 16}, {"t": "It seemed altogether past belief that anyone could make such a will, or that they would pay such a sum for doing anything so simple as copying out the Encyclopædia Britannica.", "sk": "It seemed altogether past belief that anyone could make such a will, or that they would pay such a sum for doing anything so simple as copying out the Encyclopædia Britannica.", "skk": "누군가 그런 유언장을 만들 수 있다는 것도, 백과사전을 옮겨 적는 이런 간단한 일에 그런 큰돈을 지불한다는 것도 도무지 믿기지 않는 일 같았습니다.", "ko": "\"누군가 그런 유언장을 만들 수 있다는 것도, 백과사전을 옮겨 적는 것처럼 그렇게 간단한 일에 그런 큰돈을 지불한다는 것도 도무지 믿을 수 없는 일 같았습니다.\"", "pi": 16}, {"t": "Vincent Spaulding did what he could to cheer me up, but by bedtime I had reasoned myself out of the whole thing.", "sk": "Vincent Spaulding did what he could to cheer me up, but by bedtime I had reasoned myself out of the whole thing.", "skk": "빈센트 스폴딩이 저를 기운 나게 하려고 할 수 있는 걸 다 했지만, 잘 시간쯤엔 제가 스스로 그 일을 다 그만두기로 결론 내렸습니다.", "ko": "\"빈센트 스폴딩이 저를 기운 나게 해주려고 할 수 있는 건 다 했지만, 잠자리에 들 무렵엔 저 스스로 이 일 전체를 없던 일로 치부하고 있었습니다.\"", "pi": 16}, {"t": "However, in the morning I determined to have a look at it anyhow, so I bought a penny bottle of ink, and with a quill-pen, and seven sheets of foolscap paper, I started off for Pope’s Court.", "sk": "However, in the morning I determined to have a look at it anyhow, so I bought ink, a quill-pen, and foolscap paper, and started off for Pope’s Court.", "skk": "하지만 아침이 되자 어쨌든 가서 확인해보기로 마음먹었고, 그래서 잉크와 깃펜, 대판지를 사서 포프스 코트로 향했습니다.", "ko": "\"하지만 아침이 되자 어쨌든 가서 한번 확인해보기로 마음먹었고, 그래서 1페니짜리 잉크 한 병과 깃펜 하나, 대판지 일곱 장을 사서 포프스 코트로 출발했습니다.\"", "pi": 16}, {"t": "Well, to my surprise and delight, everything was as right as possible.", "sk": "To my surprise and delight, everything was as right as possible.", "skk": "놀랍고 기쁘게도, 모든 게 더할 나위 없이 제대로였습니다.", "ko": "\"그런데 놀랍고 기쁘게도, 모든 게 더할 나위 없이 제대로 되어 있었습니다.\"", "pi": 16}, {"t": "The table was set out ready for me, and Mr. Duncan Ross was there to see that I got fairly to work.", "sk": "The table was set out ready for me, and Mr. Duncan Ross was there to see that I got fairly to work.", "skk": "탁자는 저를 위해 준비되어 있었고, 던컨 로스 씨는 제가 제대로 일을 시작하는지 보러 와 있었습니다.", "ko": "\"탁자는 저를 위해 다 준비되어 있었고, 던컨 로스 씨는 제가 제대로 일을 시작하는지 보려고 그곳에 나와 있었습니다.\"", "pi": 16}, {"t": "He started me off upon the letter A, and then he left me; but he would drop in from time to time to see that all was right with me.", "sk": "He started me off upon the letter A, and then he left me; but he would drop in from time to time to see that all was right with me.", "skk": "그는 저를 A 항목부터 시작하게 했고, 그러고는 저를 두고 갔습니다; 하지만 이따금 들러서 제가 잘하고 있는지 확인하곤 했습니다.", "ko": "\"그는 저를 A 항목부터 시작하게 하고서 저를 두고 떠났습니다, 하지만 이따금씩 들러서 저에게 별일 없는지 확인하곤 했습니다.\"", "pi": 16}, {"t": "At two o’clock he bade me good-day, complimented me upon the amount that I had written, and locked the door of the office after me.", "sk": "At two o’clock he bade me good-day, complimented me upon the amount that I had written, and locked the door of the office after me.", "skk": "2시가 되면 그는 저에게 인사를 하고, 제가 쓴 분량을 칭찬하고, 제가 나온 뒤 사무실 문을 잠갔습니다.", "ko": "\"두 시가 되면 그는 저에게 인사를 건네고, 제가 써낸 분량을 칭찬해준 뒤, 제가 나오고 나서 사무실 문을 잠갔습니다.\"", "pi": 16}, {"t": "This went on day after day, Mr. Holmes, and on Saturday the manager came in and planked down four golden sovereigns for my week’s work.", "sk": "This went on day after day, and on Saturday the manager came in and planked down four golden sovereigns for my week’s work.", "skk": "이런 일이 매일매일 계속됐고, 토요일이 되면 매니저가 와서 제 한 주 일당으로 금화 4소버린을 척 내놨습니다.", "ko": "\"이런 일이 나날이 계속됐습니다, 홈즈 씨, 그리고 토요일이면 매니저가 들어와서 제 일주일 치 일당으로 금화 소버린 넉 닢을 척 내놓았습니다.\"", "pi": 16}, {"t": "It was the same next week, and the same the week after.", "sk": "It was the same next week, and the same the week after.", "skk": "다음 주도 마찬가지였고, 그다음 주도 마찬가지였습니다.", "ko": "\"그다음 주도 마찬가지였고, 또 그다음 주도 마찬가지였습니다.\"", "pi": 16}, {"t": "Every morning I was there at ten, and every afternoon I left at two.", "sk": "Every morning I was there at ten, and every afternoon I left at two.", "skk": "매일 아침 10시에 그곳에 있었고, 매일 오후 2시에 나왔습니다.", "ko": "\"매일 아침 열 시면 그곳에 나와 있었고, 매일 오후 두 시면 자리를 떴습니다.\"", "pi": 16}, {"t": "By degrees Mr. Duncan Ross took to coming in only once of a morning, and then, after a time, he did not come in at all.", "sk": "By degrees Mr. Duncan Ross took to coming in only once of a morning, and then, after a time, he did not come in at all.", "skk": "점차 던컨 로스 씨는 아침에 한 번만 들르게 됐고, 그러다 시간이 지나면서 아예 오지 않게 됐습니다.", "ko": "\"점차 던컨 로스 씨는 아침에 한 번만 들르는 걸로 바뀌더니, 얼마 뒤에는 아예 들르지 않게 됐습니다.\"", "pi": 16}, {"t": "Eight weeks passed away like this, and I had written about Abbots and Archery and Armour and Architecture and Attica, and hoped with diligence that I might get on to the B’s before very long.", "sk": "Eight weeks passed away like this, and I had written about Abbots and Archery and Armour and Architecture and Attica, and hoped that I might get on to the B’s before very long.", "skk": "이렇게 8주가 지났고, 저는 Abbots, Archery, Armour, Architecture, Attica 항목을 썼고, 머잖아 B 항목에 이르길 부지런히 바랐습니다.", "ko": "\"이렇게 8주가 지나갔고, 저는 Abbots와 Archery, Armour, Architecture, Attica에 관해 써놓은 상태였는데, 부지런히 하면 머지않아 B 항목에 이를 수 있으리라 바라고 있었습니다.\"", "pi": 17}, {"t": "It cost me something in foolscap, and I had pretty nearly filled a shelf with my writings.", "sk": "It cost me something in foolscap, and I had pretty nearly filled a shelf with my writings.", "skk": "대판지 값이 좀 들었고, 저는 제가 쓴 것으로 선반 하나를 거의 다 채웠습니다.", "ko": "\"대판지 값이 좀 들었고, 제가 써놓은 것들로 선반 하나를 거의 다 채웠습니다.\"", "pi": 17}, {"t": "And then suddenly the whole business came to an end.", "sk": "And then suddenly the whole business came to an end.", "skk": "그러다 갑자기 그 모든 일이 끝나버렸습니다.", "ko": "\"그러다 갑자기 그 모든 일이 끝나버렸습니다.\"", "pi": 17}, {"t": "‘To an end?’", "sk": "To an end?", "skk": "끝나다니요?", "ko": "\"'끝나다니요?'\"", "pi": 17}, {"t": "‘Yes, sir.", "sk": "Yes, sir.", "skk": "네, 그렇습니다.", "ko": "\"'네, 그렇습니다.'\"", "pi": 17}, {"t": "And no later than this morning.", "sk": "And no later than this morning.", "skk": "바로 오늘 아침에요.", "ko": "\"바로 오늘 아침이었습니다.\"", "pi": 17}, {"t": "I went to my work as usual at ten o’clock, but the door was shut and locked, with a little square of cardboard hammered on to the middle of the panel with a tack.", "sk": "I went to my work as usual at ten o’clock, but the door was shut and locked, with a little square of cardboard hammered on to the middle of the panel with a tack.", "skk": "평소처럼 10시에 일하러 갔는데, 문이 닫혀 잠겨 있었고, 작은 마분지 조각이 압정으로 문판 한가운데 박혀 있었습니다.", "ko": "\"평소처럼 열 시에 일을 하러 갔는데, 문이 닫히고 잠겨 있었고, 작은 마분지 조각이 압정으로 문짝 한가운데 박혀 있었습니다.\"", "pi": 17}, {"t": "Here it is, and you can read for yourself.’", "sk": "Here it is, and you can read for yourself.", "skk": "여기 있으니, 직접 읽어보세요.", "ko": "\"'여기 있으니, 직접 한번 읽어보시죠.'\"", "pi": 17}, {"t": "He held up a piece of white cardboard about the size of a sheet of note-paper.", "sk": "He held up a piece of white cardboard about the size of a sheet of note-paper.", "skk": "그는 편지지 한 장 크기 정도의 하얀 마분지 조각을 들어 보였습니다.", "ko": "\"그는 편지지 한 장 크기쯤 되는 하얀 마분지 조각을 들어 보였습니다.\"", "pi": 17}, {"t": "It read in this fashion:", "sk": "It read in this fashion:", "skk": "거기엔 이렇게 쓰여 있었습니다:", "ko": "\"거기엔 이런 식으로 쓰여 있었습니다.\"", "pi": 17}, {"t": "‘THE RED-HEADED LEAGUE IS DISSOLVED. October 9, 1890.’", "sk": "THE RED-HEADED LEAGUE IS DISSOLVED. October 9, 1890.", "skk": "붉은 머리 연맹은 해산되었다. 1890년 10월 9일.", "ko": "\"'붉은 머리 연맹은 해산되었음. 1890년 10월 9일.'\"", "pi": 17}, {"t": "Sherlock Holmes and I surveyed this curt announcement and the rueful face behind it, until the comical side of the affair so completely overtopped every other consideration that we both burst out into a roar of laughter.", "sk": "Sherlock Holmes and I surveyed this curt announcement and the rueful face behind it, until the comical side of the affair overtopped every other consideration that we both burst out into a roar of laughter.", "skk": "셜록 홈즈와 저는 이 짤막한 공고문과 그 뒤의 침울한 얼굴을 바라보다가, 결국 그 일의 우스운 면이 다른 모든 생각을 압도해서 둘 다 웃음을 터뜨렸습니다.", "ko": "\"셜록 홈즈와 나는 이 짤막한 공고문과 그 뒤에 있는 침울한 얼굴을 바라보았는데, 결국 그 일의 우스꽝스러운 면이 다른 모든 생각을 완전히 압도해버려서 우리 둘 다 웃음을 터뜨리고 말았습니다.\"", "pi": 17}, {"t": "‘I cannot see that there is anything very funny,’ cried our client, flushing up to the roots of his flaming head.", "sk": "I cannot see that there is anything very funny, cried our client, flushing up to the roots of his flaming head.", "skk": "저는 뭐가 그렇게 재밌는지 모르겠군요, 우리 의뢰인이 외쳤다, 불타는 머리 뿌리까지 얼굴을 붉히며.", "ko": "\"'저는 뭐가 그렇게 우스운지 모르겠는데요,' 우리 의뢰인이 외쳤습니다, 그 불타는 듯한 머리 뿌리까지 얼굴이 확 붉어져서.\"", "pi": 18}, {"t": "‘If you can do nothing better than laugh at me, I can go elsewhere.’", "sk": "If you can do nothing better than laugh at me, I can go elsewhere.", "skk": "저를 비웃는 것밖에 못하신다면, 저는 다른 데로 가겠습니다.", "ko": "\"'저를 비웃는 것 말고는 아무것도 못 해주신다면, 저는 다른 데로 가겠습니다.'\"", "pi": 18}, {"t": "‘No, no,’ cried Holmes, shoving him back into the chair from which he had half risen.", "sk": "No, no, cried Holmes, shoving him back into the chair from which he had half risen.", "skk": "아니, 아니에요, 홈즈가 외치며, 반쯤 일어섰던 의자로 그를 다시 밀어 넣었다.", "ko": "\"'아니, 아니에요,' 홈즈가 외치며, 반쯤 일어섰던 의자로 그를 도로 밀어 넣었습니다.\"", "pi": 18}, {"t": "‘I really wouldn’t miss your case for the world.", "sk": "I really wouldn’t miss your case for the world.", "skk": "저는 정말이지 당신 사건을 세상 무엇과도 안 바꿀 겁니다.", "ko": "\"'저는 무슨 일이 있어도 당신 사건을 놓치고 싶지 않습니다.'\"", "pi": 18}, {"t": "It is most refreshingly unusual.", "sk": "It is most refreshingly unusual.", "skk": "정말 신선하리만치 특이하군요.", "ko": "\"정말이지 신선하리만치 특이한 사건입니다.\"", "pi": 18}, {"t": "But there is, if you will excuse my saying so, something just a little funny about it.", "sk": "But there is something just a little funny about it.", "skk": "하지만 이런 말씀 드려도 될지 모르겠지만, 여기엔 살짝 우스운 구석이 있어요.", "ko": "\"하지만 이런 말씀을 드려도 괜찮다면, 여기엔 살짝 우스운 구석이 있긴 합니다.\"", "pi": 18}, {"t": "Pray what steps did you take when you found the card upon the door?’", "sk": "What steps did you take when you found the card upon the door?", "skk": "문에서 그 카드를 발견했을 때 어떤 조치를 취하셨나요?", "ko": "\"'그런데 문에서 그 카드를 발견했을 때 어떤 조치를 취하셨습니까?'\"", "pi": 18}, {"t": "‘I was staggered, sir.", "sk": "I was staggered, sir.", "skk": "저는 어안이 벙벙했습니다.", "ko": "\"'저는 어안이 벙벙했습니다.'\"", "pi": 18}, {"t": "I did not know what to do.", "sk": "I did not know what to do.", "skk": "어떻게 해야 할지 몰랐습니다.", "ko": "\"어떻게 해야 할지 몰랐습니다.\"", "pi": 18}, {"t": "Then I called at the offices round, but none of them seemed to know anything about it.", "sk": "Then I called at the offices round, but none of them seemed to know anything about it.", "skk": "그래서 주변 사무실들을 찾아가 봤지만, 아무도 그것에 대해 아는 것 같지 않았습니다.", "ko": "\"그래서 주변 사무실들을 찾아가 봤지만, 그중 누구도 그것에 대해 아는 것 같지 않았습니다.\"", "pi": 18}, {"t": "Finally, I went to the landlord, who is an accountant living on the ground floor, and I asked him if he could tell me what had become of the Red-headed League.", "sk": "Finally, I went to the landlord, who is an accountant living on the ground floor, and I asked him what had become of the Red-headed League.", "skk": "마침내 저는 1층에 사는 회계사인 집주인을 찾아가서, 붉은 머리 연맹이 어떻게 됐는지 물었습니다.", "ko": "\"마침내 저는 1층에 사는 회계사인 집주인을 찾아가서, 붉은 머리 연맹이 어떻게 된 건지 말해줄 수 있는지 물었습니다.\"", "pi": 18}, {"t": "He said that he had never heard of any such body.", "sk": "He said that he had never heard of any such body.", "skk": "그는 그런 단체는 들어본 적이 없다고 말했습니다.", "ko": "\"그는 그런 단체는 들어본 적이 없다고 말했습니다.\"", "pi": 18}, {"t": "Then I asked him who Mr. Duncan Ross was.", "sk": "Then I asked him who Mr. Duncan Ross was.", "skk": "그다음엔 던컨 로스 씨가 누구인지 물었습니다.", "ko": "\"그다음엔 던컨 로스 씨가 누구인지 물었습니다.\"", "pi": 19}, {"t": "He answered that the name was new to him.", "sk": "He answered that the name was new to him.", "skk": "그는 그 이름이 처음 듣는 이름이라고 대답했습니다.", "ko": "\"그는 그 이름이 처음 듣는 이름이라고 대답했습니다.\"", "pi": 19}, {"t": "‘Well,’ said I, ‘the gentleman at No. 4.’", "sk": "Well, the gentleman at No. 4, said I.", "skk": "글쎄요, 4호에 계시던 그 신사분요, 제가 말했다.", "ko": "\"'글쎄요,' 제가 말했습니다, '4호에 계시던 그 신사분 말입니다.'\"", "pi": 19}, {"t": "‘What, the red-headed man?’", "sk": "What, the red-headed man?", "skk": "뭐라고요, 그 빨간 머리 남자요?", "ko": "\"'뭐라고요, 그 빨간 머리 남자 말입니까?'\"", "pi": 19}, {"t": "‘Yes.’", "sk": "Yes.", "skk": "네.", "ko": "\"'네.'\"", "pi": 19}, {"t": "‘Oh,’ said he, ‘his name was William Morris.", "sk": "Oh, his name was William Morris, said he.", "skk": "아, 그의 이름은 윌리엄 모리스였어요, 그가 말했다.", "ko": "\"'아,' 그가 말했습니다, '그 사람 이름은 윌리엄 모리스였습니다.'\"", "pi": 19}, {"t": "He was a solicitor and was using my room as a temporary convenience until his new premises were ready.", "sk": "He was a solicitor and was using my room as a temporary convenience until his new premises were ready.", "skk": "그는 변호사였고 새 사무실이 준비될 때까지 제 방을 임시 편의 시설로 쓰고 있었습니다.", "ko": "\"그는 사무 변호사였고, 새 사무실이 준비될 때까지 제 방을 임시로 편하게 쓰고 있었던 겁니다.\"", "pi": 19}, {"t": "He moved out yesterday.’", "sk": "He moved out yesterday.", "skk": "그는 어제 이사 나갔습니다.", "ko": "\"'그는 어제 이사 나갔습니다.'\"", "pi": 19}, {"t": "‘Where could I find him?’", "sk": "Where could I find him?", "skk": "그를 어디서 찾을 수 있을까요?", "ko": "\"'그를 어디서 찾을 수 있을까요?'\"", "pi": 19}, {"t": "‘Oh, at his new offices.", "sk": "Oh, at his new offices.", "skk": "아, 새 사무실에요.", "ko": "\"'아, 그의 새 사무실에서요.'\"", "pi": 19}, {"t": "He did tell me the address.", "sk": "He did tell me the address.", "skk": "그는 저에게 그 주소를 확실히 알려줬어요.", "ko": "\"그가 저에게 주소를 알려주긴 했습니다.\"", "pi": 19}, {"t": "Yes, 17 King Edward Street, near St. Paul’s.’", "sk": "Yes, 17 King Edward Street, near St. Paul’s.", "skk": "네, 킹 에드워드 가 17번지, 세인트 폴 근처요.", "ko": "\"'네, 킹 에드워드 가 17번지, 세인트 폴 근처였습니다.'\"", "pi": 19}, {"t": "‘I started off, Mr. Holmes, but when I got to that address it was a manufactory of artificial knee-caps, and no one in it had ever heard of either Mr. William Morris or Mr. Duncan Ross.’", "sk": "I started off, but when I got to that address it was a manufactory of artificial knee-caps, and no one in it had ever heard of either Mr. William Morris or Mr. Duncan Ross.", "skk": "저는 출발했지만, 그 주소에 가보니 인공 무릎덮개 공장이었고, 거기서는 아무도 윌리엄 모리스 씨나 던컨 로스 씨를 들어본 적이 없었습니다.", "ko": "\"'저는 바로 출발했습니다, 홈즈 씨, 하지만 그 주소에 가보니 인공 무릎덮개를 만드는 공장이었고, 그곳 사람 중 누구도 윌리엄 모리스 씨나 던컨 로스 씨를 들어본 적이 없었습니다.'\"", "pi": 20}, {"t": "‘And what did you do then?’ asked Holmes.", "sk": "And what did you do then? asked Holmes.", "skk": "그래서 그다음엔 어떻게 했나요? 홈즈가 물었다.", "ko": "\"'그래서 그다음엔 어떻게 하셨습니까?' 홈즈가 물었습니다.\"", "pi": 20}, {"t": "‘I went home to Saxe-Coburg Square, and I took the advice of my assistant.", "sk": "I went home to Saxe-Coburg Square, and I took the advice of my assistant.", "skk": "저는 색스코버그 스퀘어의 집으로 돌아가서, 제 조수의 조언을 구했습니다.", "ko": "\"'저는 색스코버그 스퀘어의 집으로 돌아가서, 제 조수의 조언을 구했습니다.'\"", "pi": 20}, {"t": "But he could not help me in any way.", "sk": "But he could not help me in any way.", "skk": "하지만 그는 어떤 식으로도 저를 도와줄 수 없었습니다.", "ko": "\"하지만 그는 어떤 식으로도 저를 도와줄 수 없었습니다.\"", "pi": 20}, {"t": "He could only say that if I waited I should hear by post.", "sk": "He could only say that if I waited I should hear by post.", "skk": "그는 그저 제가 기다리면 우편으로 소식을 들을 거라고만 말할 수 있었습니다.", "ko": "\"그는 그저 제가 기다리면 우편으로 소식을 듣게 될 거라고만 말할 수 있었습니다.\"", "pi": 20}, {"t": "But that was not quite good enough, Mr. Holmes.", "sk": "But that was not quite good enough, Mr. Holmes.", "skk": "하지만 그것으로는 충분치 않았습니다, 홈즈 씨.", "ko": "\"하지만 그것으로는 충분치 않았습니다, 홈즈 씨.\"", "pi": 20}, {"t": "I did not wish to lose such a place without a struggle, so, as I had heard that you were good enough to give advice to poor folk who were in need of it, I came right away to you.’", "sk": "I did not wish to lose such a place without a struggle, so, as I had heard that you were good enough to give advice to poor folk who were in need of it, I came right away to you.", "skk": "저는 그런 자리를 싸워보지도 않고 잃고 싶지 않았고, 그래서 도움이 필요한 가난한 사람들에게 조언을 해주신다는 얘기를 들었기에, 바로 당신을 찾아왔습니다.", "ko": "\"'저는 그런 자리를 싸워보지도 않고 잃고 싶지 않았습니다, 그래서 도움이 필요한 가난한 사람들에게 기꺼이 조언을 해주신다는 얘기를 들었던 터라, 곧장 당신을 찾아왔습니다.'\"", "pi": 20}, {"t": "‘And you did very wisely,’ said Holmes.", "sk": "And you did very wisely, said Holmes.", "skk": "그리고 아주 현명하게 하셨습니다, 홈즈가 말했다.", "ko": "\"'그리고 그건 아주 현명한 처사였습니다,' 홈즈가 말했습니다.\"", "pi": 20}, {"t": "‘Your case is an exceedingly remarkable one, and I shall be happy to look into it.", "sk": "Your case is a remarkable one, and I shall be happy to look into it.", "skk": "당신 사건은 대단히 놀라운 사건이고, 기꺼이 조사해보겠습니다.", "ko": "\"'당신 사건은 대단히 놀라운 사건이고, 제가 기꺼이 조사해보겠습니다.'\"", "pi": 20}, {"t": "From what you have told me I think that it is possible that graver issues hang from it than might at first sight appear.’", "sk": "From what you have told me I think that it is possible that graver issues hang from it than might at first sight appear.", "skk": "당신이 말해준 것으로 볼 때, 언뜻 보이는 것보다 더 심각한 문제가 걸려 있을 가능성이 있다고 생각합니다.", "ko": "\"'당신이 저에게 말해준 걸로 볼 때, 언뜻 보이는 것보다 더 심각한 문제들이 걸려 있을 가능성이 있다고 생각합니다.'\"", "pi": 20}, {"t": "‘Grave enough!’ said Mr. Jabez Wilson.", "sk": "Grave enough, said Mr. Jabez Wilson.", "skk": "충분히 심각하죠! 제이비즈 윌슨 씨가 말했다.", "ko": "\"'충분히 심각하죠!' 제이비즈 윌슨 씨가 말했습니다.\"", "pi": 20}, {"t": "‘Why, I have lost four pound a week.’", "sk": "Why, I have lost four pound a week.", "skk": "왜냐면, 저는 주급 4파운드를 잃었으니까요.", "ko": "\"'아니, 저는 주급 4파운드를 잃었단 말입니다.'\"", "pi": 20}, {"t": "‘As far as you are personally concerned,’ remarked Holmes, ‘I do not see that you have any grievance against this extraordinary league.", "sk": "As far as you are personally concerned, I do not see that you have any grievance against this extraordinary league.", "skk": "당신 개인적으로만 보면, 이 특이한 리그에 불만을 가질 이유가 없어 보이는데요.", "ko": "\"'당신 개인적으로만 놓고 보면,' 홈즈가 말했습니다, '이 특이한 리그에 대해 불만을 가질 이유는 없어 보입니다.'\"", "pi": 21}, {"t": "On the contrary, you are, as I understand, richer by some £30, to say nothing of the minute knowledge which you have gained on every subject which comes under the letter A.", "sk": "On the contrary, you are richer by some £30, to say nothing of the minute knowledge which you have gained on every subject which comes under the letter A.", "skk": "오히려, 제가 알기로는, 30파운드가량 더 부자가 되셨죠, A로 시작하는 온갖 주제에 대한 세세한 지식을 얻으신 건 말할 것도 없고요.", "ko": "\"오히려, 제가 알기로는, 30파운드가량 더 부자가 되셨습니다, A로 시작하는 온갖 주제에 대해 얻으신 세세한 지식은 말할 것도 없고요.\"", "pi": 21}, {"t": "You have lost nothing by them.’", "sk": "You have lost nothing by them.", "skk": "당신은 그들 때문에 잃은 게 없습니다.", "ko": "\"'당신은 그들 때문에 잃은 게 아무것도 없습니다.'\"", "pi": 21}, {"t": "‘No, sir. But I want to find out about them, and who they are, and what their object was in playing this prank—if it was a prank—upon me.", "sk": "No, sir. But I want to find out about them, and who they are, and what their object was in playing this prank upon me.", "skk": "아뇨. 하지만 그들에 대해, 그들이 누군지, 저에게 이 장난을 친 목적이 뭔지 알고 싶습니다.", "ko": "\"'아뇨, 그렇긴 합니다. 하지만 저는 그들에 대해, 그들이 누구인지, 그리고 이게 장난이었다면 왜 저에게 이런 장난을 쳤는지 그 목적을 알고 싶습니다.'\"", "pi": 21}, {"t": "It was a pretty expensive joke for them, for it cost them two and thirty pounds.’", "sk": "It was a pretty expensive joke for them, for it cost them two and thirty pounds.", "skk": "그들에게는 꽤 비싼 농담이었죠, 32파운드나 들었으니까요.", "ko": "\"'그들 입장에서는 꽤 비싼 농담이었을 겁니다, 32파운드나 들었으니까요.'\"", "pi": 21}, {"t": "‘We shall endeavour to clear up these points for you.", "sk": "We shall endeavour to clear up these points for you.", "skk": "저희가 이 점들을 밝혀보도록 노력하겠습니다.", "ko": "\"'저희가 그 점들을 밝혀보도록 노력하겠습니다.'\"", "pi": 21}, {"t": "And, first, one or two questions, Mr. Wilson.", "sk": "And, first, one or two questions, Mr. Wilson.", "skk": "그리고 먼저, 한두 가지 질문을 드리죠, 윌슨 씨.", "ko": "\"그리고 먼저, 한두 가지만 여쭙겠습니다, 윌슨 씨.\"", "pi": 21}, {"t": "This assistant of yours who first called your attention to the advertisement—how long had he been with you?’", "sk": "This assistant of yours who first called your attention to the advertisement—how long had he been with you?", "skk": "당신 조수, 그 광고를 처음 알려준 사람 말인데, 그가 당신과 함께한 지 얼마나 됐나요?", "ko": "\"'당신 조수, 그 광고를 처음 알려준 사람 말인데요, 그가 당신 밑에 있은 지 얼마나 됐습니까?'\"", "pi": 21}, {"t": "‘About a month then.’", "sk": "About a month then.", "skk": "그때 한 달쯤이요.", "ko": "\"'그때로 치면 한 달쯤 됐었죠.'\"", "pi": 21}, {"t": "‘How did he come?’", "sk": "How did he come?", "skk": "어떻게 오게 됐나요?", "ko": "\"'어떻게 오게 됐습니까?'\"", "pi": 21}, {"t": "‘In answer to an advertisement.’", "sk": "In answer to an advertisement.", "skk": "광고에 답해서요.", "ko": "\"'광고를 보고 왔습니다.'\"", "pi": 21}, {"t": "‘Was he the only applicant?’", "sk": "Was he the only applicant?", "skk": "그가 유일한 지원자였나요?", "ko": "\"'그가 유일한 지원자였습니까?'\"", "pi": 21}, {"t": "‘No, I had a dozen.’", "sk": "No, I had a dozen.", "skk": "아뇨, 열두 명이나 있었습니다.", "ko": "\"'아뇨, 열두 명이나 있었습니다.'\"", "pi": 22}, {"t": "‘Why did you pick him?’", "sk": "Why did you pick him?", "skk": "왜 그를 뽑으셨나요?", "ko": "\"'왜 그를 뽑으셨습니까?'\"", "pi": 22}, {"t": "‘Because he was handy and would come cheap.’", "sk": "Because he was handy and would come cheap.", "skk": "손이 빠르고 싸게 일할 사람이라서요.", "ko": "\"'손이 빠르고 싸게 부릴 수 있을 것 같아서요.'\"", "pi": 22}, {"t": "‘At half wages, in fact.’", "sk": "At half wages, in fact.", "skk": "사실상 반값 급여로요.", "ko": "\"'사실상 반값 급여로 말이죠.'\"", "pi": 22}, {"t": "‘Yes.’", "sk": "Yes.", "skk": "네.", "ko": "\"'네.'\"", "pi": 22}, {"t": "‘What is he like, this Vincent Spaulding?’", "sk": "What is he like, this Vincent Spaulding?", "skk": "이 빈센트 스폴딩이라는 사람은 어떻게 생겼나요?", "ko": "\"'이 빈센트 스폴딩이라는 사람은 어떻게 생겼습니까?'\"", "pi": 22}, {"t": "‘Small, stout-built, very quick in his ways, no hair on his face, though he’s not short of thirty.", "sk": "Small, stout-built, very quick in his ways, no hair on his face, though he’s not short of thirty.", "skk": "작고, 다부지고, 행동이 아주 빠르고, 얼굴에 털이 없어요, 서른 살에 가까운데도요.", "ko": "\"'작고, 다부지고, 행동이 아주 재빠르고, 얼굴에 수염 한 올 없습니다, 서른 살에 가까운데도 말이죠.'\"", "pi": 22}, {"t": "Has a white splash of acid upon his forehead.’", "sk": "Has a white splash of acid upon his forehead.", "skk": "이마에 흰 산 자국이 있어요.", "ko": "\"'이마에 흰색 산성 물질 자국이 있고요.'\"", "pi": 22}, {"t": "Holmes sat up in his chair in considerable excitement.", "sk": "Holmes sat up in his chair in considerable excitement.", "skk": "홈즈는 상당한 흥분 속에 의자에서 몸을 일으켰습니다.", "ko": "\"홈즈는 상당히 흥분한 채로 의자에서 몸을 곧추세웠습니다.\"", "pi": 22}, {"t": "‘I thought as much,’ said he.", "sk": "I thought as much, said he.", "skk": "그럴 줄 알았어요, 그가 말했다.", "ko": "\"'그럴 줄 알았습니다,' 그가 말했습니다.\"", "pi": 22}, {"t": "‘Have you ever observed that his ears are pierced for earrings?’", "sk": "Have you ever observed that his ears are pierced for earrings?", "skk": "그의 귀가 귀걸이를 위해 뚫려 있는 걸 본 적 있나요?", "ko": "\"'그의 귀가 귀걸이를 하려고 뚫려 있는 걸 본 적 있으십니까?'\"", "pi": 22}, {"t": "‘Yes, sir. He told me that a gipsy had done it for him when he was a lad.’", "sk": "Yes, sir. He told me that a gipsy had done it for him when he was a lad.", "skk": "네. 그는 소년 시절 집시가 뚫어줬다고 저에게 말했습니다.", "ko": "\"'네, 그렇습니다. 그는 소년 시절에 집시가 뚫어줬다고 저에게 말했습니다.'\"", "pi": 22}, {"t": "‘Hum!’ said Holmes, sinking back in deep thought.", "sk": "Hum! said Holmes, sinking back in deep thought.", "skk": "흠! 홈즈가 말하며, 깊은 생각에 잠겨 뒤로 기댔다.", "ko": "\"'흠!' 홈즈가 깊은 생각에 잠겨 뒤로 기대며 말했습니다.\"", "pi": 23}, {"t": "‘He is still with you?’", "sk": "He is still with you?", "skk": "아직도 당신과 함께 있나요?", "ko": "\"'그는 아직도 당신 밑에 있습니까?'\"", "pi": 23}, {"t": "‘Oh, yes, sir; I have only just left him.’", "sk": "Oh, yes, sir; I have only just left him.", "skk": "네, 방금 막 그를 두고 왔어요.", "ko": "\"'네, 그렇습니다. 방금 막 그를 두고 왔습니다.'\"", "pi": 23}, {"t": "‘And has your business been attended to in your absence?’", "sk": "And has your business been attended to in your absence?", "skk": "당신이 없는 동안 사업은 잘 돌아갔나요?", "ko": "\"'그리고 당신이 자리를 비운 동안 사업은 잘 돌아갔습니까?'\"", "pi": 23}, {"t": "‘Nothing to complain of, sir.", "sk": "Nothing to complain of, sir.", "skk": "불평할 게 없어요.", "ko": "\"'딱히 불평할 것은 없습니다.'\"", "pi": 23}, {"t": "There’s never very much to do of a morning.’", "sk": "There’s never very much to do of a morning.", "skk": "아침에는 원래 할 일이 그리 많지 않아요.", "ko": "\"'아침에는 원래 할 일이 그리 많지 않으니까요.'\"", "pi": 23}, {"t": "‘That will do, Mr. Wilson.", "sk": "That will do, Mr. Wilson.", "skk": "그거면 됐습니다, 윌슨 씨.", "ko": "\"'그 정도면 됐습니다, 윌슨 씨.'\"", "pi": 23}, {"t": "I shall be happy to give you an opinion upon the subject in the course of a day or two.", "sk": "I shall be happy to give you an opinion upon the subject in the course of a day or two.", "skk": "하루이틀 안에 기꺼이 이 건에 대한 의견을 드리겠습니다.", "ko": "\"하루이틀 안에 기꺼이 이 건에 대한 제 의견을 드리겠습니다.\"", "pi": 23}, {"t": "To-day is Saturday, and I hope that by Monday we may come to a conclusion.’", "sk": "To-day is Saturday, and I hope that by Monday we may come to a conclusion.", "skk": "오늘이 토요일이니, 월요일까지는 결론에 이를 수 있기를 바랍니다.", "ko": "\"'오늘이 토요일이니, 월요일쯤에는 결론에 이를 수 있기를 바랍니다.'\"", "pi": 23}, {"t": "‘Well, Watson,’ said Holmes when our visitor had left us, ‘what do you make of it all?’", "sk": "Well, Watson, said Holmes when our visitor had left us, what do you make of it all?", "skk": "자, 왓슨, 손님이 떠난 뒤 홈즈가 말했다, 이걸 어떻게 생각해요?", "ko": "\"'자, 왓슨,' 손님이 떠나고 나서 홈즈가 말했습니다, '이걸 다 어떻게 보십니까?'\"", "pi": 23}, {"t": "‘I make nothing of it,’ I answered frankly.", "sk": "I make nothing of it, I answered frankly.", "skk": "저는 전혀 모르겠어요, 저는 솔직하게 대답했다.", "ko": "\"'저는 도무지 모르겠습니다,' 저는 솔직하게 대답했습니다.\"", "pi": 23}, {"t": "‘It is a most mysterious business.’", "sk": "It is a most mysterious business.", "skk": "정말 알 수 없는 사건이에요.", "ko": "\"'정말이지 알 수 없는 사건입니다.'\"", "pi": 23}, {"t": "‘As a rule,’ said Holmes, ‘the more bizarre a thing is the less mysterious it proves to be.", "sk": "As a rule, the more bizarre a thing is the less mysterious it proves to be.", "skk": "대체로, 어떤 일이 기이할수록 그것은 덜 알 수 없는 것으로 밝혀지죠.", "ko": "\"'대체로,' 홈즈가 말했습니다, '어떤 일이 기이할수록 오히려 덜 알 수 없는 것으로 밝혀지는 법입니다.'\"", "pi": 24}, {"t": "It is your commonplace, featureless crimes which are really puzzling, just as a commonplace face is the most difficult to identify.", "sk": "It is your commonplace, featureless crimes which are really puzzling, just as a commonplace face is the most difficult to identify.", "skk": "정말로 알쏭달쏭한 건 평범하고 특징 없는 범죄죠, 평범한 얼굴을 알아보기 가장 어려운 것처럼요.", "ko": "\"정말로 알쏭달쏭한 것은 평범하고 특징 없는 범죄입니다, 평범한 얼굴을 가장 알아보기 어려운 것과 마찬가지죠.\"", "pi": 24}, {"t": "But I must be prompt over this matter.’", "sk": "But I must be prompt over this matter.", "skk": "하지만 이 건에 대해서는 신속해야 해요.", "ko": "\"'하지만 이 건에 대해서는 신속하게 움직여야 합니다.'\"", "pi": 24}, {"t": "‘What are you going to do, then?’ I asked.", "sk": "What are you going to do, then? I asked.", "skk": "그럼 뭘 하실 건가요? 제가 물었다.", "ko": "\"'그럼 뭘 하실 겁니까?' 제가 물었습니다.\"", "pi": 24}, {"t": "‘To smoke,’ he answered.", "sk": "To smoke, he answered.", "skk": "담배 피우는 거요, 그가 대답했다.", "ko": "\"'담배를 피울 겁니다,' 그가 대답했습니다.\"", "pi": 24}, {"t": "‘It is quite a three pipe problem, and I beg that you won’t speak to me for fifty minutes.’", "sk": "It is quite a three pipe problem, and I beg that you won’t speak to me for fifty minutes.", "skk": "이건 파이프 세 대짜리 문제예요, 그러니 50분 동안 저에게 말 걸지 말아주세요.", "ko": "\"'이건 완전히 파이프 세 대짜리 문제입니다, 그러니 50분 동안은 저에게 말을 걸지 말아주시길 부탁드립니다.'\"", "pi": 24}, {"t": "He curled himself up in his chair, with his thin knees drawn up to his hawk-like nose, and there he sat with his eyes closed and his black clay pipe thrusting out like the bill of some strange bird.", "sk": "He curled himself up in his chair, with his thin knees drawn up to his hawk-like nose, and there he sat with his eyes closed and his black clay pipe thrusting out like the bill of some strange bird.", "skk": "그는 의자에서 몸을 웅크렸다, 마른 무릎을 매부리코까지 끌어당긴 채, 그리고 눈을 감고 앉아 검은 점토 파이프를 이상한 새의 부리처럼 내밀고 있었다.", "ko": "\"그는 의자에서 몸을 웅크리고 앉아, 마른 무릎을 매부리코까지 끌어당긴 채, 눈을 감고 앉아 검은 점토 파이프를 이상한 새의 부리처럼 쭉 내밀고 있었습니다.\"", "pi": 24}, {"t": "I had come to the conclusion that he had dropped asleep, and indeed was nodding myself, when he suddenly sprang out of his chair with the gesture of a man who has made up his mind and put his pipe down upon the mantelpiece.", "sk": "I had come to the conclusion that he had dropped asleep, and indeed was nodding myself, when he suddenly sprang out of his chair and put his pipe down upon the mantelpiece.", "skk": "저는 그가 잠들었다고 결론짓고, 실은 저도 졸고 있었는데, 그때 그가 갑자기 의자에서 벌떡 일어나 파이프를 벽난로 선반에 내려놨습니다.", "ko": "\"저는 그가 잠들었다고 결론지었고, 사실 저도 졸고 있었는데, 그때 그가 갑자기 마음을 정한 사람의 몸짓으로 의자에서 벌떡 일어나 파이프를 벽난로 선반 위에 내려놓았습니다.\"", "pi": 24}, {"t": "‘Sarasate plays at the St. James’s Hall this afternoon,’ he remarked.", "sk": "Sarasate plays at the St. James’s Hall this afternoon, he remarked.", "skk": "사라사테가 오늘 오후 세인트 제임스 홀에서 연주해요, 그가 말했다.", "ko": "\"'사라사테가 오늘 오후 세인트 제임스 홀에서 연주합니다,' 그가 말했습니다.\"", "pi": 24}, {"t": "‘What do you think, Watson?", "sk": "What do you think, Watson?", "skk": "어떻게 생각해요, 왓슨?", "ko": "\"'어떻게 생각하십니까, 왓슨?'\"", "pi": 24}, {"t": "Could your patients spare you for a few hours?’", "sk": "Could your patients spare you for a few hours?", "skk": "환자분들이 몇 시간 정도 당신을 놔줄 수 있을까요?", "ko": "\"'환자분들이 몇 시간 정도는 당신을 봐드릴 수 있을까요?'\"", "pi": 24}, {"t": "‘I have nothing to do to-day.", "sk": "I have nothing to do to-day.", "skk": "오늘은 할 일이 없어요.", "ko": "\"'오늘은 딱히 할 일이 없습니다.'\"", "pi": 24}, {"t": "My practice is never very absorbing.’", "sk": "My practice is never very absorbing.", "skk": "제 진료가 늘 그리 바쁜 편은 아니에요.", "ko": "\"'제 진료는 원래 그렇게 정신없이 바쁜 편이 아니거든요.'\"", "pi": 25}, {"t": "‘Then put on your hat and come.", "sk": "Then put on your hat and come.", "skk": "그럼 모자 쓰고 와요.", "ko": "\"'그럼 모자를 쓰고 따라오세요.'\"", "pi": 25}, {"t": "I am going through the City first, and we can have some lunch on the way.", "sk": "I am going through the City first, and we can have some lunch on the way.", "skk": "저는 먼저 시티를 거쳐 가는데, 가는 길에 점심을 먹을 수 있어요.", "ko": "\"저는 먼저 시티를 거쳐 갈 건데, 가는 길에 점심을 좀 먹을 수 있겠네요.\"", "pi": 25}, {"t": "I observe that there is a good deal of German music on the programme, which is rather more to my taste than Italian or French.", "sk": "I observe that there is a good deal of German music on the programme, which is rather more to my taste than Italian or French.", "skk": "프로그램에 독일 음악이 꽤 많더군요, 그게 이탈리아나 프랑스 음악보다 제 취향에 더 맞아요.", "ko": "\"보아하니 프로그램에 독일 음악이 꽤 많던데, 그게 이탈리아나 프랑스 음악보다 제 취향에 더 맞습니다.\"", "pi": 25}, {"t": "It is introspective, and I want to introspect.", "sk": "It is introspective, and I want to introspect.", "skk": "그건 성찰적이라서, 저도 성찰하고 싶거든요.", "ko": "\"성찰적인 음악이라서, 저도 좀 성찰을 하고 싶습니다.\"", "pi": 25}, {"t": "Come along!’", "sk": "Come along!", "skk": "같이 가요!", "ko": "\"'자, 같이 갑시다!'\"", "pi": 25}, {"t": "We travelled by the Underground as far as Aldersgate; and a short walk took us to Saxe-Coburg Square, the scene of the singular story which we had listened to in the morning.", "sk": "We travelled by the Underground as far as Aldersgate; and a short walk took us to Saxe-Coburg Square, the scene of the singular story which we had listened to in the morning.", "skk": "우리는 지하철을 타고 알더스게이트까지 갔고, 짧게 걸어서 색스코버그 스퀘어에 도착했습니다, 아침에 들었던 그 기이한 이야기의 무대인.", "ko": "\"우리는 지하철을 타고 알더스게이트까지 갔고, 거기서 조금 걸어 색스코버그 스퀘어에 이르렀습니다, 아침에 우리가 들었던 그 기이한 이야기의 무대인 그곳 말입니다.\"", "pi": 25}, {"t": "It was a poky, little, shabby-genteel place, where four lines of dingy two-storied brick houses looked out into a small railed-in enclosure, where a lawn of weedy grass and a few clumps of faded laurel bushes made a hard fight against a smoke-laden and uncongenial atmosphere.", "sk": "It was a poky, shabby-genteel place, where dingy brick houses looked out into a small enclosure, where weedy grass and faded laurel bushes made a hard fight against an uncongenial atmosphere.", "skk": "그곳은 좁고 초라하면서도 격식 차린 듯한 곳이었습니다, 지저분한 벽돌집들이 작은 울타리 친 공터를 내다보고 있었고, 잡초 무성한 잔디와 시든 월계수 덤불이 답답한 공기와 힘겹게 싸우는 곳이었습니다.", "ko": "\"그곳은 비좁고 초라하지만 나름 격식을 차린 듯한 곳이었습니다, 지저분한 2층짜리 벽돌집 네 줄이 작은 울타리 친 공터를 내다보고 있었고, 그 안에는 잡초 무성한 잔디와 시든 월계수 덤불 몇 그루가 매캐하고 답답한 공기에 맞서 힘겹게 버티고 있었습니다.\"", "pi": 25}, {"t": "Three gilt balls and a brown board with ‘JABEZ WILSON’ in white letters, upon a corner house, announced the place where our red-headed client carried on his business.", "sk": "Three gilt balls and a brown board with JABEZ WILSON in white letters announced the place where our red-headed client carried on his business.", "skk": "금박 공 세 개와 흰 글씨로 '제이비즈 윌슨'이라 적힌 갈색 간판이 우리 빨간 머리 의뢰인이 사업을 하는 곳을 알려줬습니다.", "ko": "\"금박을 입힌 공 세 개와, 흰 글씨로 '제이비즈 윌슨'이라 적힌 갈색 간판이 모퉁이 집에 걸려 있어, 우리 빨간 머리 의뢰인이 사업을 하는 곳임을 알려주고 있었습니다.\"", "pi": 25}, {"t": "Sherlock Holmes stopped in front of it with his head on one side and looked it all over, with his eyes shining brightly between puckered lids.", "sk": "Sherlock Holmes stopped in front of it with his head on one side and looked it all over, with his eyes shining brightly between puckered lids.", "skk": "셜록 홈즈는 고개를 한쪽으로 기울인 채 그 앞에 멈춰 서서 전체를 훑어봤습니다, 찌푸린 눈꺼풀 사이로 눈이 밝게 빛나며.", "ko": "\"셜록 홈즈는 고개를 한쪽으로 기울인 채 그 앞에 멈춰 서서 건물 전체를 훑어봤습니다, 찌푸린 눈꺼풀 사이로 눈이 밝게 빛나는 채로요.\"", "pi": 25}, {"t": "Then he walked slowly up the street, and then down again to the corner, still looking keenly at the houses.", "sk": "Then he walked slowly up the street, and then down again to the corner, still looking keenly at the houses.", "skk": "그러고는 천천히 거리를 걸어 올라갔다가, 다시 모퉁이까지 내려왔습니다, 여전히 집들을 예리하게 살피며.", "ko": "\"그러고는 천천히 거리를 걸어 올라갔다가, 다시 모퉁이까지 걸어 내려왔습니다, 여전히 집들을 예리하게 살피면서요.\"", "pi": 25}, {"t": "Finally he returned to the pawnbroker’s, and, having thumped vigorously upon the pavement with his stick two or three times, he went up to the door and knocked.", "sk": "Finally he returned to the pawnbroker’s, and, having thumped vigorously upon the pavement with his stick two or three times, he went up to the door and knocked.", "skk": "마침내 그는 전당포로 돌아왔고, 지팡이로 인도를 두세 번 세게 두드린 뒤, 문으로 가서 노크했습니다.", "ko": "\"마침내 그는 전당포로 돌아왔고, 지팡이로 보도를 두세 번 세게 쿵쿵 두드린 다음, 문 앞으로 가서 노크를 했습니다.\"", "pi": 25}, {"t": "It was instantly opened by a bright-looking, clean-shaven young fellow, who asked him to step in.", "sk": "It was instantly opened by a bright-looking, clean-shaven young fellow, who asked him to step in.", "skk": "문은 곧바로 총명해 보이는 말끔히 면도한 젊은이가 열어줬고, 그는 들어오라고 청했습니다.", "ko": "\"문은 곧바로 총명해 보이는, 말끔히 면도한 젊은이가 열어줬고, 그는 홈즈에게 들어오라고 청했습니다.\"", "pi": 26}, {"t": "‘Thank you,’ said Holmes, ‘I only wished to ask you how you would go from here to the Strand.’", "sk": "Thank you, said Holmes, I only wished to ask you how you would go from here to the Strand.", "skk": "고마워요, 홈즈가 말했다, 여기서 스트랜드로 어떻게 가는지 물어보고 싶었을 뿐이에요.", "ko": "\"'고맙습니다,' 홈즈가 말했습니다, '여기서 스트랜드까지 어떻게 가는지 여쭤보고 싶었을 뿐입니다.'\"", "pi": 26}, {"t": "‘Third right, fourth left,’ answered the assistant promptly, closing the door.", "sk": "Third right, fourth left, answered the assistant promptly, closing the door.", "skk": "세 번째에서 우회전, 네 번째에서 좌회전이요, 조수가 재빨리 대답하며 문을 닫았습니다.", "ko": "\"'세 번째 길에서 우회전, 네 번째 길에서 좌회전입니다,' 조수가 지체 없이 대답하며 문을 닫았습니다.\"", "pi": 26}, {"t": "‘Smart fellow, that,’ observed Holmes as we walked away.", "sk": "Smart fellow, that, observed Holmes as we walked away.", "skk": "똑똑한 친구네요, 저 사람, 우리가 걸어가면서 홈즈가 말했다.", "ko": "\"'똑똑한 친구로군요, 저 사람은,' 우리가 자리를 뜨며 홈즈가 말했습니다.\"", "pi": 26}, {"t": "‘He is, in my judgment, the fourth smartest man in London, and for daring I am not sure that he has not a claim to be third.", "sk": "He is the fourth smartest man in London, and for daring I am not sure that he has not a claim to be third.", "skk": "제 판단으론 그는 런던에서 네 번째로 똑똑한 사람이고, 대담함으로는 세 번째가 될 자격이 있을지도 몰라요.", "ko": "\"'제 판단으로는 그가 런던에서 네 번째로 똑똑한 사람이고, 대담함으로 치면 세 번째 자리를 노릴 자격이 없지 않을 겁니다.'\"", "pi": 26}, {"t": "I have known something of him before.’", "sk": "I have known something of him before.", "skk": "전에 그에 대해 좀 알고 있었어요.", "ko": "\"'전에 그에 대해 좀 알고 있었거든요.'\"", "pi": 26}, {"t": "‘Evidently,’ said I, ‘Mr. Wilson’s assistant counts for a good deal in this mystery of the Red-headed League.", "sk": "Evidently, said I, Mr. Wilson’s assistant counts for a good deal in this mystery of the Red-headed League.", "skk": "분명히, 제가 말했다, 윌슨의 조수가 이 붉은 머리 연맹 사건에서 큰 비중을 차지하네요.", "ko": "\"'분명히,' 제가 말했습니다, '윌슨 씨의 조수가 이 붉은 머리 연맹 사건에서 상당한 비중을 차지하는군요.'\"", "pi": 26}, {"t": "I am sure that you inquired your way merely in order that you might see him.’", "sk": "I am sure that you inquired your way merely in order that you might see him.", "skk": "당신이 길을 물은 건 그저 그를 보기 위해서였다고 확신해요.", "ko": "\"'당신이 길을 물어본 건 그저 그를 보기 위해서였다고 확신합니다.'\"", "pi": 26}, {"t": "‘Not him.’", "sk": "Not him.", "skk": "그가 아니에요.", "ko": "\"'그를 보려던 게 아니었습니다.'\"", "pi": 26}, {"t": "‘What then?’", "sk": "What then?", "skk": "그럼 뭔가요?", "ko": "\"'그럼 뭘 보려던 겁니까?'\"", "pi": 26}, {"t": "‘The knees of his trousers.’", "sk": "The knees of his trousers.", "skk": "그의 바지 무릎이요.", "ko": "\"'그의 바지 무릎이었죠.'\"", "pi": 26}, {"t": "‘And what did you see?’", "sk": "And what did you see?", "skk": "그래서 뭘 봤나요?", "ko": "\"'그래서 뭘 보셨습니까?'\"", "pi": 26}, {"t": "‘What I expected to see.’", "sk": "What I expected to see.", "skk": "제가 볼 거라고 예상했던 거요.", "ko": "\"'제가 보리라 예상했던 것이었죠.'\"", "pi": 27}, {"t": "‘Why did you beat the pavement?’", "sk": "Why did you beat the pavement?", "skk": "왜 보도를 지팡이로 두드렸나요?", "ko": "\"'그런데 왜 지팡이로 보도를 두드리신 겁니까?'\"", "pi": 27}, {"t": "‘My dear doctor, this is a time for observation, not for talk.", "sk": "My dear doctor, this is a time for observation, not for talk.", "skk": "이보게 왓슨, 지금은 관찰할 때지 이야기할 때가 아니에요.", "ko": "\"'이보게 왓슨, 지금은 관찰할 때지 이야기할 때가 아닙니다.'\"", "pi": 27}, {"t": "We are spies in an enemy’s country.", "sk": "We are spies in an enemy’s country.", "skk": "우리는 적국에 있는 스파이예요.", "ko": "\"우리는 적국에 있는 첩자입니다.\"", "pi": 27}, {"t": "We know something of Saxe-Coburg Square.", "sk": "We know something of Saxe-Coburg Square.", "skk": "색스코버그 스퀘어에 대해서는 좀 알고 있죠.", "ko": "\"색스코버그 스퀘어에 대해서는 이제 좀 알게 되었습니다.\"", "pi": 27}, {"t": "Let us now explore the parts which lie behind it.’", "sk": "Let us now explore the parts which lie behind it.", "skk": "이제 그 뒤편에 있는 곳들을 살펴보죠.", "ko": "\"'이제 그 뒤편에 놓인 곳들을 살펴봅시다.'\"", "pi": 27}, {"t": "The road in which we found ourselves as we turned round the corner from the retired Saxe-Coburg Square presented as great a contrast to it as the front of a picture does to the back.", "sk": "The road presented as great a contrast to it as the front of a picture does to the back.", "skk": "모퉁이를 돌자 나온 그 길은 그림의 앞면이 뒷면과 다르듯 그곳과 극명한 대조를 이루었습니다.", "ko": "\"한적한 색스코버그 스퀘어의 모퉁이를 돌아서자 나타난 그 길은, 마치 그림의 앞면이 뒷면과 다르듯 그곳과 극명한 대조를 이루었습니다.\"", "pi": 27}, {"t": "It was one of the main arteries which conveyed the traffic of the City to the north and west.", "sk": "It was one of the main arteries which conveyed the traffic of the City to the north and west.", "skk": "그곳은 시티의 교통을 북쪽과 서쪽으로 실어 나르는 주요 간선도로 중 하나였습니다.", "ko": "\"그곳은 런던 시티의 교통을 북쪽과 서쪽으로 실어 나르는 주요 간선도로 가운데 하나였습니다.\"", "pi": 27}, {"t": "The roadway was blocked with the immense stream of commerce flowing in a double tide inward and outward, while the footpaths were black with the hurrying swarm of pedestrians.", "sk": "The roadway was blocked with the immense stream of commerce, while the footpaths were black with the hurrying swarm of pedestrians.", "skk": "차도는 안팎으로 이중 물결처럼 흐르는 어마어마한 상업 행렬로 막혀 있었고, 보도는 서두르는 보행자 무리로 새까맸습니다.", "ko": "\"차도는 안팎으로 이중 물결처럼 흘러가는 어마어마한 상업의 흐름으로 꽉 막혀 있었고, 보도는 서둘러 걷는 보행자 무리로 새까맣게 뒤덮여 있었습니다.\"", "pi": 27}, {"t": "It was difficult to realise as we looked at the line of fine shops and stately business premises that they really abutted on the other side upon the faded and stagnant square which we had just quitted.", "sk": "It was difficult to realise that they really abutted upon the faded and stagnant square which we had just quitted.", "skk": "멋진 가게들과 위풍당당한 상점 건물들을 보면서, 그것들이 방금 떠나온 빛바래고 정체된 광장과 실제로 맞닿아 있다는 걸 실감하기 어려웠습니다.", "ko": "\"멋들어진 가게들과 위풍당당한 상점 건물들이 늘어선 것을 보고 있으면, 그것들이 뒤편으로는 방금 떠나온 빛바래고 정체된 그 광장과 실제로 맞닿아 있다는 사실을 실감하기 어려웠습니다.\"", "pi": 27}, {"t": "‘Let me see,’ said Holmes, standing at the corner and glancing along the line, ‘I should like just to remember the order of the houses here.", "sk": "Let me see, said Holmes, I should like just to remember the order of the houses here.", "skk": "어디 보자, 홈즈가 모퉁이에 서서 그 줄지어 선 건물들을 훑어보며 말했다, 이곳 건물들의 순서를 기억해두고 싶네요.", "ko": "\"'어디 보자,' 홈즈가 모퉁이에 서서 늘어선 건물들을 훑어보며 말했습니다, '여기 건물들의 순서를 정확히 기억해두고 싶군요.'\"", "pi": 27}, {"t": "It is a hobby of mine to have an exact knowledge of London.", "sk": "It is a hobby of mine to have an exact knowledge of London.", "skk": "런던을 정확히 아는 게 제 취미거든요.", "ko": "\"런던을 정확하게 속속들이 아는 것이 제 취미거든요.\"", "pi": 27}, {"t": "There is Mortimer’s, the tobacconist, the little newspaper shop, the Coburg branch of the City and Suburban Bank, the Vegetarian Restaurant, and McFarlane’s carriage-building depot.", "sk": "There is Mortimer’s, the tobacconist, the newspaper shop, the bank, the restaurant, and the carriage-building depot.", "skk": "모티머네 담배 가게, 신문 가판대, 은행, 식당, 마차 제작소가 있죠.", "ko": "\"모티머네 담배 가게, 작은 신문 가판대, 시티 앤드 서버번 은행 코버그 지점, 채식 식당, 그리고 맥팔레인네 마차 제작소가 있습니다.\"", "pi": 28}, {"t": "That carries us right on to the other block.", "sk": "That carries us right on to the other block.", "skk": "그게 우리를 다음 블록까지 곧장 데려다주죠.", "ko": "\"그렇게 하면 곧장 다음 블록까지 이어집니다.\"", "pi": 28}, {"t": "And now, Doctor, we’ve done our work, so it’s time we had some play.", "sk": "And now, Doctor, we’ve done our work, so it’s time we had some play.", "skk": "자, 의사 선생, 우리 일은 끝났으니 이제 놀 시간이에요.", "ko": "\"자, 의사 선생, 우리는 할 일을 다 했으니 이제 놀 시간입니다.\"", "pi": 28}, {"t": "A sandwich and a cup of coffee, and then off to violin-land, where all is sweetness and delicacy and harmony, and there are no red-headed clients to vex us with their conundrums.’", "sk": "A sandwich and a cup of coffee, and then off to violin-land, and there are no red-headed clients to vex us with their conundrums.", "skk": "샌드위치와 커피 한 잔, 그러고 나서 바이올린의 나라로, 거기엔 우리를 골치 아프게 할 빨간 머리 손님이 없죠.", "ko": "\"'샌드위치와 커피 한 잔을 들고, 그러고 나서 바이올린의 나라로 갑시다, 그곳은 온통 달콤함과 섬세함과 조화로 가득하고, 우리를 수수께끼로 골치 아프게 할 빨간 머리 손님도 없는 곳이니까요.'\"", "pi": 28}, {"t": "My friend was an enthusiastic musician, being himself not only a very capable performer but a composer of no ordinary merit.", "sk": "My friend was an enthusiastic musician, being himself not only a very capable performer but a composer of no ordinary merit.", "skk": "제 친구는 열정적인 음악가였습니다, 그 자신이 뛰어난 연주자일 뿐 아니라 보통이 아닌 재능을 가진 작곡가이기도 했죠.", "ko": "\"제 친구는 열정적인 음악가였습니다, 그 자신이 매우 뛰어난 연주자일 뿐만 아니라 보통이 아닌 재능을 지닌 작곡가이기도 했습니다.\"", "pi": 28}, {"t": "All the afternoon he sat in the stalls wrapped in the most perfect happiness, gently waving his long, thin fingers in time to the music, while his gently smiling face and his languid, dreamy eyes were as unlike those of Holmes the sleuth-hound, Holmes the relentless, keen-witted, ready-handed criminal agent, as it was possible to conceive.", "sk": "All the afternoon he sat in the stalls wrapped in happiness, waving his fingers in time to the music, while his smiling face and his dreamy eyes were as unlike those of Holmes the sleuth-hound as it was possible to conceive.", "skk": "오후 내내 그는 스톨석에 앉아 행복에 흠뻑 잠긴 채, 음악에 맞춰 손가락을 흔들었습니다, 웃음 짓는 얼굴과 몽롱한 눈이 명탐정 홈즈의 그것과는 상상할 수 없을 만큼 달랐습니다.", "ko": "\"오후 내내 그는 스톨석에 앉아 더없는 행복에 흠뻑 잠긴 채, 음악에 맞춰 길고 가느다란 손가락을 부드럽게 흔들었습니다, 그의 부드럽게 웃는 얼굴과 몽롱하고 꿈꾸는 듯한 눈은 냉철하고 예리하며 즉각적인 범죄 수사관인 명탐정 홈즈의 그것과는 도저히 상상할 수 없을 만큼 달랐습니다.\"", "pi": 28}, {"t": "In his singular character the dual nature alternately asserted itself, and his extreme exactness and astuteness represented, as I have often thought, the reaction against the poetic and contemplative mood which occasionally predominated in him.", "sk": "In his singular character the dual nature alternately asserted itself, and his extreme exactness and astuteness represented the reaction against the poetic and contemplative mood which occasionally predominated in him.", "skk": "그의 특이한 성격에서는 이중적인 본성이 번갈아 나타났습니다, 극도의 정확함과 영민함은 이따금 그를 지배하던 시적이고 사색적인 기분에 대한 반작용이었죠.", "ko": "\"그의 유별난 성격 속에서는 이중적인 본성이 번갈아 나타났습니다, 그리고 그의 극도의 정확함과 기민함은, 제가 자주 생각해왔듯, 이따금 그를 지배하던 시적이고 사색적인 기분에 대한 반작용이었습니다.\"", "pi": 28}, {"t": "The swing of his nature took him from extreme languor to devouring energy; and, as I knew well, he was never so truly formidable as when, for days on end, he had been lounging in his armchair amid his improvisations and his black-letter editions.", "sk": "The swing of his nature took him from extreme languor to devouring energy; and he was never so truly formidable as when he had been lounging in his armchair amid his improvisations and his black-letter editions.", "skk": "그의 성정은 극도의 나른함에서 맹렬한 에너지로 오갔습니다, 그리고 그가 안락의자에 파묻혀 즉흥 연주와 고서들 속에 며칠씩 뒹굴었을 때만큼 진짜 무서웠던 적이 없었죠.", "ko": "\"그의 성정은 극도의 나른함에서 맹렬한 에너지로 오갔습니다, 그리고 제가 잘 알고 있듯, 그가 며칠씩 안락의자에 파묻혀 즉흥 연주와 고딕 활자체로 인쇄된 옛 책들 속에서 뒹굴고 있을 때만큼 그가 진정으로 무서웠던 적은 없었습니다.\"", "pi": 28}, {"t": "Then it was that the lust of the chase would suddenly come upon him, and that his brilliant reasoning power would rise to the level of intuition, until those who were unacquainted with his methods would look askance at him as on a man whose knowledge was not that of other mortals.", "sk": "Then it was that the lust of the chase would suddenly come upon him, and that his brilliant reasoning power would rise to the level of intuition, until those who were unacquainted with his methods would look askance at him.", "skk": "그럴 때면 갑자기 추적에 대한 갈망이 그를 사로잡았고, 뛰어난 추리력이 직관의 경지에 올랐죠, 그의 방법을 모르는 사람들이 그를 의심스레 곁눈질할 정도로.", "ko": "\"바로 그럴 때면 갑자기 추적에 대한 갈망이 그를 사로잡았고, 그의 뛰어난 추리력이 직관의 경지까지 치솟았습니다, 그의 방법을 잘 모르는 사람들이 그를 보통 사람과는 다른 지식을 가진 사람처럼 의심스레 곁눈질할 정도로요.\"", "pi": 28}, {"t": "When I saw him that afternoon so enwrapped in the music at St. James’s Hall I felt that an evil time might be coming upon those whom he had set himself to hunt down.", "sk": "When I saw him that afternoon so enwrapped in the music I felt that an evil time might be coming upon those whom he had set himself to hunt down.", "skk": "그날 오후 세인트 제임스 홀에서 음악에 그토록 빠진 그를 보면서, 그가 뒤쫓기로 마음먹은 자들에게 안 좋은 시간이 다가오고 있다고 느꼈습니다.", "ko": "\"그날 오후 세인트 제임스 홀에서 음악에 그토록 깊이 빠져 있는 그를 보면서, 저는 그가 뒤쫓기로 마음먹은 자들에게 험한 시간이 다가오고 있음을 느꼈습니다.\"", "pi": 28}, {"t": "‘You want to go home, no doubt, Doctor,’ he remarked as we emerged.", "sk": "You want to go home, no doubt, Doctor, he remarked as we emerged.", "skk": "집에 가고 싶으시죠, 의사 선생, 우리가 나오면서 그가 말했다.", "ko": "\"'집에 가고 싶으시겠죠, 의사 선생,' 우리가 밖으로 나오면서 그가 말했습니다.\"", "pi": 28}, {"t": "‘Yes, it would be as well.’", "sk": "Yes, it would be as well.", "skk": "네, 그러는 게 낫겠어요.", "ko": "\"'네, 그러는 편이 낫겠습니다.'\"", "pi": 28}, {"t": "‘And I have some business to do which will take some hours.", "sk": "And I have some business to do which will take some hours.", "skk": "그리고 몇 시간 걸릴 일이 좀 있어요.", "ko": "\"'그리고 저는 몇 시간쯤 걸릴 일이 좀 있습니다.'\"", "pi": 29}, {"t": "This business at Coburg Square is serious.’", "sk": "This business at Coburg Square is serious.", "skk": "이 코버그 스퀘어 건은 심각해요.", "ko": "\"'이 코버그 스퀘어 건은 심각합니다.'\"", "pi": 29}, {"t": "‘Why serious?’", "sk": "Why serious?", "skk": "왜 심각한데요?", "ko": "\"'왜 심각한가요?'\"", "pi": 29}, {"t": "‘A considerable crime is in contemplation.", "sk": "A considerable crime is in contemplation.", "skk": "상당한 범죄가 계획되고 있어요.", "ko": "\"'상당한 범죄가 계획되고 있습니다.'\"", "pi": 29}, {"t": "I have every reason to believe that we shall be in time to stop it.", "sk": "I have every reason to believe that we shall be in time to stop it.", "skk": "우리가 그걸 막을 시간이 있다고 믿을 만한 충분한 이유가 있어요.", "ko": "\"우리가 그것을 막기에 늦지 않을 것이라 믿을 만한 충분한 이유가 있습니다.\"", "pi": 29}, {"t": "But to-day being Saturday rather complicates matters.", "sk": "But to-day being Saturday rather complicates matters.", "skk": "하지만 오늘이 토요일이라는 게 일을 좀 복잡하게 만드네요.", "ko": "\"하지만 오늘이 토요일이라는 점이 일을 다소 복잡하게 만듭니다.\"", "pi": 29}, {"t": "I shall want your help to-night.’", "sk": "I shall want your help to-night.", "skk": "오늘 밤 당신 도움이 필요할 거예요.", "ko": "\"'오늘 밤 당신의 도움이 필요할 겁니다.'\"", "pi": 29}, {"t": "‘At what time?’", "sk": "At what time?", "skk": "몇 시에요?", "ko": "\"'몇 시에 말입니까?'\"", "pi": 29}, {"t": "‘Ten will be early enough.’", "sk": "Ten will be early enough.", "skk": "10시면 이를 거예요.", "ko": "\"'10시면 충분히 이를 겁니다.'\"", "pi": 29}, {"t": "‘I shall be at Baker Street at ten.’", "sk": "I shall be at Baker Street at ten.", "skk": "10시에 베이커가에 갈게요.", "ko": "\"'10시에 베이커 가에 가 있겠습니다.'\"", "pi": 29}, {"t": "‘Very well.", "sk": "Very well.", "skk": "좋아요.", "ko": "\"'좋습니다.'\"", "pi": 29}, {"t": "And, I say, Doctor, there may be some little danger, so kindly put your army revolver in your pocket.’", "sk": "And, I say, Doctor, there may be some little danger, so kindly put your army revolver in your pocket.", "skk": "그리고, 저기, 의사 선생, 약간의 위험이 있을 수 있으니 군용 리볼버를 주머니에 넣어와요.", "ko": "\"그리고, 저기, 의사 선생, 약간의 위험이 있을 수도 있으니 부디 군용 리볼버를 주머니에 챙겨 오시죠.'\"", "pi": 29}, {"t": "He waved his hand, turned on his heel, and disappeared in an instant among the crowd.", "sk": "He waved his hand, turned on his heel, and disappeared in an instant among the crowd.", "skk": "그는 손을 흔들고, 홱 돌아서더니, 순식간에 인파 속으로 사라졌습니다.", "ko": "\"그는 손을 흔들고, 발꿈치를 축으로 홱 돌아서더니, 순식간에 인파 속으로 사라져버렸습니다.\"", "pi": 30}, {"t": "I trust that I am not more dense than my neighbours, but I was always oppressed with a sense of my own stupidity in my dealings with Sherlock Holmes.", "sk": "I trust that I am not more dense than my neighbours, but I was always oppressed with a sense of my own stupidity in my dealings with Sherlock Holmes.", "skk": "제가 남들보다 특별히 둔하지는 않다고 믿지만, 셜록 홈즈와 얽힐 때면 늘 제 자신의 어리석음이라는 감각에 짓눌렸습니다.", "ko": "\"저는 제가 이웃들보다 특별히 둔한 사람은 아니라고 믿지만, 셜록 홈즈와의 거래에서만큼은 언제나 제 자신의 어리석음에 대한 자각에 짓눌리곤 했습니다.\"", "pi": 30}, {"t": "Here I had heard what he had heard, I had seen what he had seen, and yet from his words it was evident that he saw clearly not only what had happened but what was about to happen, while to me the whole business was still confused and grotesque.", "sk": "I had heard what he had heard, I had seen what he had seen, and yet it was evident that he saw clearly what was about to happen, while to me the whole business was still confused and grotesque.", "skk": "저도 그가 들은 걸 듣고 본 걸 봤는데도, 그는 앞으로 일어날 일까지 또렷이 보고 있는 게 분명했습니다, 저에게는 이 사건 전체가 여전히 혼란스럽고 기괴했지만요.", "ko": "\"저도 여기서 그가 들은 것을 들었고, 그가 본 것을 보았는데도, 그의 말로 미루어 보면 그는 이미 일어난 일뿐 아니라 앞으로 일어날 일까지 또렷이 보고 있는 것이 분명했습니다, 반면 저에게는 이 사건 전체가 여전히 혼란스럽고 기괴하기만 했습니다.\"", "pi": 30}, {"t": "As I drove home to my house in Kensington I thought over it all, from the extraordinary story of the red-headed copier of the Encyclopædia down to the visit to Saxe-Coburg Square, and the ominous words with which he had parted from me.", "sk": "As I drove home to my house in Kensington I thought over it all, from the story of the red-headed copier down to the visit to Saxe-Coburg Square, and the ominous words with which he had parted from me.", "skk": "켄싱턴 집으로 차를 몰고 가면서 저는 그 모든 일을 되짚어봤습니다, 빨간 머리 필경사 이야기부터 색스코버그 스퀘어 방문, 그리고 그가 헤어지며 남긴 불길한 말까지.", "ko": "\"켄싱턴에 있는 제 집으로 차를 몰고 돌아가면서 저는 그 모든 일을 처음부터 되짚어봤습니다, 백과사전을 베끼던 그 빨간 머리 남자의 기이한 이야기부터 색스코버그 스퀘어 방문, 그리고 그가 저와 헤어지며 남긴 불길한 말까지 말입니다.\"", "pi": 30}, {"t": "What was this nocturnal expedition, and why should I go armed?", "sk": "What was this nocturnal expedition, and why should I go armed?", "skk": "이 야간 원정은 뭐고, 왜 무장하고 가야 하지?", "ko": "\"이 야간 원정은 도대체 무엇이고, 왜 무장을 하고 가야 하는 걸까?\"", "pi": 30}, {"t": "Where were we going, and what were we to do?", "sk": "Where were we going, and what were we to do?", "skk": "우리는 어디로 가는 거고, 뭘 하게 되는 걸까?", "ko": "\"우리는 대체 어디로 가고 있으며, 무엇을 하게 될 것인가?\"", "pi": 30}, {"t": "I had the hint from Holmes that this smooth-faced pawnbroker’s assistant was a formidable man—a man who might play a deep game.", "sk": "I had the hint from Holmes that this smooth-faced pawnbroker’s assistant was a formidable man—a man who might play a deep game.", "skk": "홈즈에게서 이 매끈한 얼굴의 전당포 조수가 만만치 않은 사람이라는, 깊은 속셈을 품고 있을지 모를 사람이라는 암시를 받았습니다.", "ko": "\"저는 홈즈에게서 이 매끈한 얼굴의 전당포 조수가 만만치 않은 사람이라는, 즉 뭔가 깊은 속셈을 꾸미고 있을지도 모를 사람이라는 암시를 받았습니다.\"", "pi": 30}, {"t": "I tried to puzzle it out, but gave it up in despair and set the matter aside until night should bring an explanation.", "sk": "I tried to puzzle it out, but gave it up in despair and set the matter aside until night should bring an explanation.", "skk": "곰곰이 풀어보려 했지만, 절망 속에 포기하고 밤이 설명을 가져다줄 때까지 그 문제를 제쳐뒀습니다.", "ko": "\"저는 그것을 곰곰이 풀어보려 애썼지만, 결국 절망 속에 포기하고, 밤이 되면 답이 나오겠거니 하며 그 문제를 제쳐두었습니다.\"", "pi": 30}, {"t": "It was a quarter-past nine when I started from home and made my way across the Park, and so through Oxford Street to Baker Street.", "sk": "It was a quarter-past nine when I started from home and made my way across the Park, and so through Oxford Street to Baker Street.", "skk": "9시 15분에 집을 나서 공원을 가로질러, 옥스퍼드 가를 지나 베이커 가로 향했습니다.", "ko": "\"9시 15분이 되어서야 저는 집을 나서서 공원을 가로질렀고, 그렇게 옥스퍼드 가를 지나 베이커 가로 향했습니다.\"", "pi": 30}, {"t": "Two hansoms were standing at the door, and as I entered the passage I heard the sound of voices from above.", "sk": "Two hansoms were standing at the door, and as I entered the passage I heard the sound of voices from above.", "skk": "이륜마차 두 대가 문 앞에 서 있었고, 통로에 들어서자 위층에서 말소리가 들렸습니다.", "ko": "\"이륜마차 두 대가 문 앞에 서 있었고, 제가 통로로 들어서자 위층에서 말소리가 들려왔습니다.\"", "pi": 30}, {"t": "On entering his room, I found Holmes in animated conversation with two men, one of whom I recognised as Peter Jones, the official police agent, while the other was a long, thin, sad-faced man, with a very shiny hat and oppressively respectable frock-coat.", "sk": "On entering his room, I found Holmes in animated conversation with two men, one of whom I recognised as Peter Jones, while the other was a long, thin, sad-faced man, with a very shiny hat and frock-coat.", "skk": "방에 들어서자 홈즈가 두 남자와 활기차게 대화하고 있었습니다, 한 명은 피터 존스로 알아봤고, 다른 한 명은 길고 마른 수심 어린 얼굴의 남자로, 반들반들한 모자와 프록코트 차림이었습니다.", "ko": "\"그의 방에 들어서자 저는 홈즈가 두 남자와 활기차게 대화를 나누고 있는 것을 보았습니다, 그중 한 명은 공식 경찰 요원인 피터 존스로 알아보았고, 다른 한 명은 길고 마른, 수심 어린 얼굴의 남자로, 반들반들한 모자와 답답할 만큼 점잖은 프록코트 차림이었습니다.\"", "pi": 30}, {"t": "‘Ha! Our party is complete,’ said Holmes, buttoning up his pea-jacket and taking his heavy hunting crop from the rack.", "sk": "Ha! Our party is complete, said Holmes, buttoning up his pea-jacket and taking his heavy hunting crop from the rack.", "skk": "하! 일행이 다 모였네요, 피코트 단추를 채우고 걸이에서 묵직한 채찍을 집으며 홈즈가 말했다.", "ko": "\"'하! 일행이 다 모였군요,' 피코트 단추를 채우고 걸이에서 묵직한 사냥용 채찍을 집어 들며 홈즈가 말했습니다.\"", "pi": 30}, {"t": "‘Watson, I think you know Mr. Jones, of Scotland Yard?", "sk": "Watson, I think you know Mr. Jones, of Scotland Yard?", "skk": "왓슨, 스코틀랜드 야드의 존스 씨는 알죠?", "ko": "\"'왓슨, 스코틀랜드 야드의 존스 씨는 알고 계시죠?'\"", "pi": 31}, {"t": "Let me introduce you to Mr. Merryweather, who is to be our companion in to-night’s adventure.’", "sk": "Let me introduce you to Mr. Merryweather, who is to be our companion in to-night’s adventure.", "skk": "메리웨더 씨를 소개할게요, 오늘 밤 모험에서 우리와 함께할 분이에요.", "ko": "\"'메리웨더 씨를 소개해드리죠, 오늘 밤 모험에서 우리와 동행하실 분입니다.'\"", "pi": 31}, {"t": "‘We’re hunting in couples again, Doctor, you see,’ said Jones in his consequential way.", "sk": "We’re hunting in couples again, Doctor, you see, said Jones in his consequential way.", "skk": "우리가 또 짝지어 사냥하네요, 의사 선생, 존스가 거들먹거리며 말했다.", "ko": "\"'또 짝을 지어 사냥에 나섰습니다, 의사 선생,' 존스가 거들먹거리는 투로 말했습니다.\"", "pi": 31}, {"t": "‘Our friend here is a wonderful man for starting a chase.", "sk": "Our friend here is a wonderful man for starting a chase.", "skk": "이 친구는 추적을 시작하는 데는 대단한 사람이죠.", "ko": "\"'여기 이 친구는 추적을 시작하는 데는 대단한 사람입니다.'\"", "pi": 31}, {"t": "All he wants is an old dog to help him to do the running down.’", "sk": "All he wants is an old dog to help him to do the running down.", "skk": "그에게 필요한 건 뒤쫓는 걸 도와줄 늙은 사냥개뿐이에요.", "ko": "\"'그에게 필요한 것은 그를 도와 끝까지 뒤쫓아 잡아줄 늙은 사냥개 한 마리뿐이죠.'\"", "pi": 31}, {"t": "‘I hope a wild goose may not prove to be the end of our chase,’ observed Mr. Merryweather gloomily.", "sk": "I hope a wild goose may not prove to be the end of our chase, observed Mr. Merryweather gloomily.", "skk": "우리 추적의 끝이 헛수고로 밝혀지지 않길 바라요, 메리웨더 씨가 침울하게 말했다.", "ko": "\"'우리 추적의 끝이 헛수고로 판명되지 않기를 바랍니다,' 메리웨더 씨가 침울하게 말했습니다.\"", "pi": 31}, {"t": "‘You may place considerable confidence in Mr. Holmes, sir,’ said the police agent loftily.", "sk": "You may place considerable confidence in Mr. Holmes, sir, said the police agent loftily.", "skk": "홈즈 씨를 상당히 신뢰하셔도 됩니다, 경찰관이 거만하게 말했다.", "ko": "\"'홈즈 씨를 상당히 신뢰하셔도 됩니다,' 그 경찰 요원이 거만한 투로 말했습니다.\"", "pi": 31}, {"t": "‘He has his own little methods, which are, if he won’t mind my saying so, just a little too theoretical and fantastic, but he has the makings of a detective in him.", "sk": "He has his own little methods, which are just a little too theoretical and fantastic, but he has the makings of a detective in him.", "skk": "그만의 방법이 있어요, 이런 말 해도 될지 모르겠지만 다소 지나치게 이론적이고 기발하죠, 그래도 그에겐 탐정으로서의 자질이 있어요.", "ko": "\"'그에게는 나름의 방법이 있죠, 이런 말씀을 드려도 될지 모르겠지만, 다소 지나치게 이론적이고 기발한 면이 있습니다, 하지만 그에게는 분명 탐정으로서의 자질이 있습니다.\"", "pi": 31}, {"t": "It is not too much to say that once or twice, as in that business of the Sholto murder and the Agra treasure, he has been more nearly correct than the official force.’", "sk": "It is not too much to say that once or twice he has been more nearly correct than the official force.", "skk": "한두 번은, 숄토 살인 사건과 아그라 보물 사건에서처럼, 그가 정식 경찰보다 더 정확했다고 해도 과언이 아니에요.", "ko": "\"'한두 번은, 저 숄토 살인 사건과 아그라 보물 사건에서처럼, 그가 정식 경찰력보다도 더 정확했다고 해도 과언이 아닙니다.'\"", "pi": 31}, {"t": "‘Oh, if you say so, Mr. Jones, it is all right,’ said the stranger with deference.", "sk": "Oh, if you say so, Mr. Jones, it is all right, said the stranger with deference.", "skk": "아, 존스 씨가 그렇다면 괜찮겠죠, 낯선 남자가 정중하게 말했다.", "ko": "\"'아, 존스 씨께서 그렇게 말씀하신다면야 괜찮겠지요,' 그 낯선 남자가 정중하게 말했습니다.\"", "pi": 31}, {"t": "‘Still, I confess that I miss my rubber.", "sk": "Still, I confess that I miss my rubber.", "skk": "그래도 카드 게임 한 판을 놓쳐서 아쉽네요.", "ko": "\"'그래도, 솔직히 말해 카드 게임 한 판을 놓치는 게 아쉽습니다.'\"", "pi": 31}, {"t": "It is the first Saturday night for seven-and-twenty years that I have not had my rubber.’", "sk": "It is the first Saturday night for seven-and-twenty years that I have not had my rubber.", "skk": "27년 만에 카드 게임을 못 하는 첫 토요일 밤이거든요.", "ko": "\"'27년 만에 처음으로 카드 게임을 못 하는 토요일 밤이니까요.'\"", "pi": 31}, {"t": "‘I think you will find,’ said Sherlock Holmes, ‘that you will play for a higher stake to-night than you have ever done yet, and that the play will be more exciting.", "sk": "I think you will find, said Sherlock Holmes, that you will play for a higher stake to-night than you have ever done yet, and that the play will be more exciting.", "skk": "아마 알게 되실 거예요, 셜록 홈즈가 말했다, 오늘 밤엔 그 어느 때보다 큰 판돈을 걸고, 더 흥미진진한 게임을 하게 될 거라는 걸요.", "ko": "\"'아마 알게 되실 겁니다,' 셜록 홈즈가 말했습니다, '오늘 밤에는 지금까지 하신 그 어느 때보다도 큰 판돈을 걸고, 더 흥미진진한 게임을 하시게 될 거라는 걸 말이죠.'\"", "pi": 32}, {"t": "For you, Mr. Merryweather, the stake will be some £30,000; and for you, Jones, it will be the man upon whom you wish to lay your hands.’", "sk": "For you, Mr. Merryweather, the stake will be some thirty thousand pounds; and for you, Jones, it will be the man upon whom you wish to lay your hands.", "skk": "메리웨더 씨, 당신에게는 판돈이 약 3만 파운드일 거고, 존스 씨, 당신에게는 잡고 싶어 하던 그 사람이겠죠.", "ko": "\"'메리웨더 씨, 당신에게 그 판돈은 약 3만 파운드가 될 것이고, 존스 씨, 당신에게 그것은 당신이 그토록 붙잡고 싶어 하던 바로 그 사람이 될 겁니다.'\"", "pi": 32}, {"t": "‘John Clay, the murderer, thief, smasher, and forger.", "sk": "John Clay, the murderer, thief, smasher, and forger.", "skk": "존 클레이, 살인자, 도둑, 위조지폐범, 문서위조범이죠.", "ko": "\"'존 클레이, 살인자이자 도둑, 위조지폐범이자 문서위조범입니다.'\"", "pi": 32}, {"t": "He’s a young man, Mr. Merryweather, but he is at the head of his profession, and I would rather have my bracelets on him than on any criminal in London.", "sk": "He’s a young man, but he is at the head of his profession, and I would rather have my bracelets on him than on any criminal in London.", "skk": "젊은 사람이지만 자기 업계에서는 최고죠, 런던의 어떤 범죄자보다 이 사람에게 수갑을 채우고 싶어요.", "ko": "\"그는 젊은 사람입니다, 메리웨더 씨, 하지만 자기 업계에서는 최고에 올라 있는 자입니다, 런던의 그 어떤 범죄자보다도 이자에게 제 수갑을 채우고 싶습니다.\"", "pi": 32}, {"t": "He’s a remarkable man, is young John Clay.", "sk": "He’s a remarkable man, is young John Clay.", "skk": "대단한 사람이죠, 이 젊은 존 클레이가.", "ko": "\"대단한 사람이죠, 이 젊은 존 클레이라는 자는요.\"", "pi": 32}, {"t": "His grandfather was a royal duke, and he himself has been to Eton and Oxford.", "sk": "His grandfather was a royal duke, and he himself has been to Eton and Oxford.", "skk": "그의 할아버지는 왕실 공작이었고, 본인은 이튼과 옥스퍼드를 나왔죠.", "ko": "\"그의 할아버지는 왕실 공작이었고, 그 자신은 이튼 학교와 옥스퍼드 대학을 다녔습니다.\"", "pi": 32}, {"t": "His brain is as cunning as his fingers, and though we meet signs of him at every turn, we never know where to find the man himself.", "sk": "His brain is as cunning as his fingers, and though we meet signs of him at every turn, we never know where to find the man himself.", "skk": "머리는 손가락만큼이나 교활하고, 곳곳에서 그의 흔적을 만나지만 정작 그 사람 자체를 어디서 찾을지는 몰라요.", "ko": "\"그의 머리는 그의 손가락만큼이나 교활하고, 우리는 곳곳에서 그의 흔적을 마주치지만 정작 그 사람 자체를 어디서 찾아야 할지는 결코 알 수가 없습니다.\"", "pi": 32}, {"t": "He’ll crack a crib in Scotland one week, and be raising money to build an orphanage in Cornwall the next.", "sk": "He’ll crack a crib in Scotland one week, and be raising money to build an orphanage in Cornwall the next.", "skk": "이번 주엔 스코틀랜드에서 집을 털고, 다음 주엔 콘월에서 고아원 짓는다고 돈을 모으죠.", "ko": "\"어떤 주에는 스코틀랜드에서 남의 집을 털다가, 그다음 주에는 콘월에서 고아원을 짓겠다며 돈을 모으고 다니는 자입니다.\"", "pi": 32}, {"t": "I’ve been on his track for years and have never set eyes on him yet.’", "sk": "I’ve been on his track for years and have never set eyes on him yet.", "skk": "몇 년째 그를 쫓고 있는데 아직 한 번도 직접 본 적이 없어요.", "ko": "\"'저는 몇 년째 그를 추적해왔지만 아직 그의 얼굴 한 번 직접 본 적이 없습니다.'\"", "pi": 32}, {"t": "‘I hope that I may have the pleasure of introducing you to-night.", "sk": "I hope that I may have the pleasure of introducing you to-night.", "skk": "오늘 밤 두 분을 소개하는 기쁨을 누릴 수 있길 바라요.", "ko": "\"'오늘 밤 그자를 두 분께 소개해드리는 기쁨을 누릴 수 있기를 바랍니다.'\"", "pi": 32}, {"t": "I’ve had one or two little turns also with Mr. John Clay, and I agree with you that he is at the head of his profession.", "sk": "I’ve had one or two little turns also with Mr. John Clay, and I agree with you that he is at the head of his profession.", "skk": "저도 존 클레이 씨와 몇 번 얽힌 적이 있고, 그가 업계 최고라는 데 동의해요.", "ko": "\"저도 존 클레이 씨와 몇 차례 부딪친 적이 있고, 그가 자기 업계에서 최고 자리에 있다는 데 동의합니다.\"", "pi": 32}, {"t": "It is past ten, however, and quite time that we started.", "sk": "It is past ten, however, and quite time that we started.", "skk": "하지만 벌써 10시가 넘었으니 이제 출발할 때예요.", "ko": "\"하지만 벌써 10시가 지났으니, 이제 우리가 출발할 때입니다.\"", "pi": 32}, {"t": "‘If you two will take the first hansom, Watson and I will follow in the second.’", "sk": "If you two will take the first hansom, Watson and I will follow in the second.", "skk": "두 분이 첫 번째 마차를 타면, 왓슨과 저는 두 번째 마차로 따라갈게요.", "ko": "\"'두 분이 첫 번째 이륜마차를 타시면, 왓슨과 저는 두 번째 마차로 뒤따르겠습니다.'\"", "pi": 33}, {"t": "Sherlock Holmes was not very communicative during the long drive and lay back in the cab humming the tunes which he had heard in the afternoon.", "sk": "Sherlock Holmes was not very communicative during the long drive and lay back in the cab humming the tunes which he had heard in the afternoon.", "skk": "셜록 홈즈는 긴 이동 내내 말이 별로 없었고 마차에 기대 오후에 들은 곡조를 흥얼거렸습니다.", "ko": "\"셜록 홈즈는 긴 이동 내내 말이 별로 없었고, 마차에 등을 기댄 채 오후에 들었던 곡조를 흥얼거렸습니다.\"", "pi": 33}, {"t": "We rattled through an endless labyrinth of gas-lit streets until we emerged into Farrington Street.", "sk": "We rattled through an endless labyrinth of gas-lit streets until we emerged into Farrington Street.", "skk": "가스등 켜진 거리의 끝없는 미로를 덜컹거리며 지나 패링던 가로 나왔습니다.", "ko": "\"우리는 가스등이 켜진 거리들의 끝없는 미로를 덜컹거리며 지나, 마침내 패링던 가로 접어들었습니다.\"", "pi": 33}, {"t": "‘We are close there now,’ my friend remarked.", "sk": "We are close there now, my friend remarked.", "skk": "거의 다 왔어요, 제 친구가 말했다.", "ko": "\"'거의 다 왔습니다,' 제 친구가 말했습니다.\"", "pi": 33}, {"t": "‘This fellow Merryweather is a bank director, and personally interested in the matter.", "sk": "This fellow Merryweather is a bank director, and personally interested in the matter.", "skk": "이 메리웨더라는 사람은 은행 이사고, 이 일에 개인적으로 이해관계가 있어요.", "ko": "\"'이 메리웨더라는 사람은 은행 이사이고, 이 사건에 개인적인 이해관계가 있습니다.'\"", "pi": 33}, {"t": "I thought it as well to have Jones with us also.", "sk": "I thought it as well to have Jones with us also.", "skk": "존스도 우리와 함께 데려오는 게 낫겠다 싶었어요.", "ko": "\"존스도 우리와 함께 데려오는 편이 낫겠다 싶었습니다.\"", "pi": 33}, {"t": "He is not a bad fellow, though an absolute imbecile in his profession.", "sk": "He is not a bad fellow, though an absolute imbecile in his profession.", "skk": "나쁜 사람은 아니에요, 자기 일에서는 완전히 얼간이지만요.", "ko": "\"나쁜 사람은 아닙니다, 다만 자기 직업에서만큼은 완전히 얼간이지만요.\"", "pi": 33}, {"t": "He has one positive virtue.", "sk": "He has one positive virtue.", "skk": "확실한 장점이 하나 있죠.", "ko": "\"확실한 장점이 하나 있습니다.\"", "pi": 33}, {"t": "He is as brave as a bulldog and as tenacious as a lobster if he gets his claws upon anyone.", "sk": "He is as brave as a bulldog and as tenacious as a lobster if he gets his claws upon anyone.", "skk": "불도그처럼 용감하고, 누구든 손아귀에 넣으면 가재처럼 집요하죠.", "ko": "\"불도그만큼이나 용감하고, 일단 누군가를 손아귀에 넣으면 가재만큼이나 집요합니다.\"", "pi": 33}, {"t": "Here we are, and they are waiting for us.’", "sk": "Here we are, and they are waiting for us.", "skk": "다 왔네요, 저들이 우리를 기다리고 있어요.", "ko": "\"'다 왔군요, 저들이 우리를 기다리고 있습니다.'\"", "pi": 33}, {"t": "We had reached the same crowded thoroughfare in which we had found ourselves in the morning.", "sk": "We had reached the same crowded thoroughfare in which we had found ourselves in the morning.", "skk": "아침에 있었던 그 붐비는 큰길에 다시 다다랐습니다.", "ko": "\"우리는 아침에 서 있었던 바로 그 붐비는 큰길에 다시 다다랐습니다.\"", "pi": 33}, {"t": "Our cabs were dismissed, and, following the guidance of Mr. Merryweather, we passed down a narrow passage and through a side door, which he opened for us.", "sk": "Our cabs were dismissed, and, following the guidance of Mr. Merryweather, we passed down a narrow passage and through a side door, which he opened for us.", "skk": "마차를 돌려보내고, 메리웨더 씨를 따라 좁은 통로를 지나 그가 열어준 옆문을 통과했습니다.", "ko": "\"우리는 마차를 돌려보내고, 메리웨더 씨의 안내를 따라 좁은 통로를 지나, 그가 열어준 옆문을 통과했습니다.\"", "pi": 33}, {"t": "Within there was a small corridor, which ended in a very massive iron gate.", "sk": "Within there was a small corridor, which ended in a very massive iron gate.", "skk": "안에는 작은 복도가 있었고, 아주 육중한 철문으로 끝났습니다.", "ko": "\"안으로 들어서니 작은 복도가 있었는데, 그 끝은 아주 육중한 철문이었습니다.\"", "pi": 34}, {"t": "This also was opened, and led down a flight of winding stone steps, which terminated at another formidable gate.", "sk": "This also was opened, and led down a flight of winding stone steps, which terminated at another formidable gate.", "skk": "이것도 열렸고, 구불구불한 돌계단으로 이어졌으며, 또 다른 육중한 문에서 끝났습니다.", "ko": "\"이 철문도 열렸고, 안쪽은 구불구불한 돌계단으로 이어져 내려갔으며, 그 계단은 또 다른 육중한 문에서 끝났습니다.\"", "pi": 34}, {"t": "Mr. Merryweather stopped to light a lantern, and then conducted us down a dark, earth-smelling passage, and so, after opening a third door, into a huge vault or cellar, which was piled all round with crates and massive boxes.", "sk": "Mr. Merryweather stopped to light a lantern, and then conducted us down a dark, earth-smelling passage, and, after opening a third door, into a huge vault or cellar, which was piled all round with crates and massive boxes.", "skk": "메리웨더 씨는 멈춰서 랜턴을 켠 뒤, 어둡고 흙냄새 나는 통로로 우리를 안내했고, 세 번째 문을 연 뒤에는 상자와 궤짝이 잔뜩 쌓인 거대한 금고로 안내했습니다.", "ko": "\"메리웨더 씨는 걸음을 멈추고 랜턴을 켠 뒤, 어둡고 흙냄새 나는 통로로 우리를 이끌었고, 세 번째 문을 연 뒤에는 상자와 육중한 궤짝이 사방에 쌓인 거대한 금고, 즉 지하 저장고로 우리를 안내했습니다.\"", "pi": 34}, {"t": "‘You are not very vulnerable from above,’ Holmes remarked as he held up the lantern and gazed about him.", "sk": "You are not very vulnerable from above, Holmes remarked as he held up the lantern and gazed about him.", "skk": "위쪽에서는 그리 취약하지 않네요, 랜턴을 들고 주위를 둘러보며 홈즈가 말했다.", "ko": "\"'위쪽에서는 그리 취약하지 않군요,' 랜턴을 들어 올려 주위를 둘러보며 홈즈가 말했습니다.\"", "pi": 34}, {"t": "‘Nor from below,’ said Mr. Merryweather, striking his stick upon the flags which lined the floor.", "sk": "Nor from below, said Mr. Merryweather, striking his stick upon the flags which lined the floor.", "skk": "아래쪽도 그렇죠, 바닥에 깔린 포석을 지팡이로 두드리며 메리웨더 씨가 말했다.", "ko": "\"'아래쪽도 그렇습니다,' 바닥에 깔린 포석을 지팡이로 두드리며 메리웨더 씨가 말했습니다.\"", "pi": 34}, {"t": "‘Why, dear me, it sounds quite hollow!’ he remarked, looking up in surprise.", "sk": "Why, dear me, it sounds quite hollow! he remarked, looking up in surprise.", "skk": "아니 이런, 속이 텅 빈 소리가 나는데요! 놀라 올려다보며 그가 말했다.", "ko": "\"'아니 이런, 소리가 아주 텅 빈 것 같은데요!' 놀라 고개를 들며 그가 말했습니다.\"", "pi": 34}, {"t": "‘I must really ask you to be a little more quiet!’ said Holmes severely.", "sk": "I must really ask you to be a little more quiet! said Holmes severely.", "skk": "좀 더 조용히 해달라고 정말 부탁해야겠어요! 홈즈가 엄하게 말했다.", "ko": "\"'좀 더 조용히 해주시길 정말로 부탁드려야겠습니다!' 홈즈가 엄한 투로 말했습니다.\"", "pi": 34}, {"t": "‘You have already imperilled the whole success of our expedition.", "sk": "You have already imperilled the whole success of our expedition.", "skk": "벌써 우리 작전의 성공 전체를 위태롭게 했어요.", "ko": "\"'당신은 이미 우리 작전의 성공 전체를 위태롭게 했습니다.'\"", "pi": 34}, {"t": "Might I beg that you would have the goodness to sit down upon one of those boxes, and not to interfere?’", "sk": "Might I beg that you would have the goodness to sit down upon one of those boxes, and not to interfere?", "skk": "저 상자 중 하나에 앉아주시고, 방해하지 말아주시길 부탁드려도 될까요?", "ko": "\"'부디 저 상자들 중 하나에 앉으시고, 더는 방해하지 말아주시길 부탁드려도 되겠습니까?'\"", "pi": 34}, {"t": "The solemn Mr. Merryweather perched himself upon a crate, with a very injured expression upon his face, while Holmes fell upon his knees upon the floor and, with the lantern and a magnifying lens, began to examine minutely the cracks between the stones.", "sk": "The solemn Mr. Merryweather perched himself upon a crate, with a very injured expression upon his face, while Holmes fell upon his knees upon the floor and began to examine minutely the cracks between the stones.", "skk": "근엄한 메리웨더 씨는 억울한 표정으로 궤짝에 걸터앉았고, 홈즈는 바닥에 무릎을 꿇고 랜턴과 돋보기로 돌 틈을 세밀하게 살피기 시작했습니다.", "ko": "\"근엄한 메리웨더 씨는 몹시 억울하다는 표정으로 궤짝 위에 걸터앉았고, 그동안 홈즈는 바닥에 무릎을 꿇고 랜턴과 돋보기를 이용해 돌 틈새를 세밀하게 살피기 시작했습니다.\"", "pi": 34}, {"t": "A few seconds sufficed to satisfy him, for he sprang to his feet again and put his glass in his pocket.", "sk": "A few seconds sufficed to satisfy him, for he sprang to his feet again and put his glass in his pocket.", "skk": "몇 초면 그를 만족시키기에 충분했고, 그는 다시 벌떡 일어나 돋보기를 주머니에 넣었습니다.", "ko": "\"단 몇 초면 그를 만족시키기에 충분했고, 그는 이내 다시 벌떡 일어나 돋보기를 주머니에 집어넣었습니다.\"", "pi": 34}, {"t": "‘We have at least an hour before us,’ he remarked, ‘for they can hardly take any steps until the good pawnbroker is safely in bed.", "sk": "We have at least an hour before us, he remarked, for they can hardly take any steps until the good pawnbroker is safely in bed.", "skk": "적어도 한 시간은 여유가 있어요, 그가 말했다, 그 착한 전당포 주인이 무사히 잠자리에 들 때까지는 저들이 움직이기 힘들 테니까요.", "ko": "\"'적어도 한 시간은 여유가 있습니다,' 그가 말했습니다, '그 선량한 전당포 주인이 무사히 잠자리에 들 때까지는 저들도 좀처럼 움직이기 힘들 테니까요.'\"", "pi": 34}, {"t": "Then they will not lose a minute, for the sooner they do their work the longer time they will have for their escape.", "sk": "Then they will not lose a minute, for the sooner they do their work the longer time they will have for their escape.", "skk": "그다음엔 1분도 낭비하지 않을 거예요, 일을 빨리 끝낼수록 도망칠 시간이 더 많아지니까요.", "ko": "\"그다음부터는 저들이 1분도 낭비하지 않을 겁니다, 일을 빨리 해치울수록 도망칠 시간이 그만큼 더 늘어나니까요.\"", "pi": 35}, {"t": "We are at present, Doctor—as no doubt you have divined—in the cellar of the City branch of one of the principal London banks.", "sk": "We are at present, Doctor, in the cellar of the City branch of one of the principal London banks.", "skk": "의사 선생, 지금 우리는—틀림없이 짐작하셨겠지만—런던의 주요 은행 중 하나인 시티 지점의 지하 금고에 있어요.", "ko": "\"의사 선생, 지금 우리는—당신도 틀림없이 짐작하셨겠지만—런던의 주요 은행 가운데 한 곳인 시티 지점의 지하 금고에 있는 겁니다.\"", "pi": 35}, {"t": "Mr. Merryweather is the chairman of directors, and he will explain to you that there are reasons why the more daring criminals of London should take a considerable interest in this cellar at present.’", "sk": "Mr. Merryweather is the chairman of directors, and he will explain to you that there are reasons why the more daring criminals of London should take a considerable interest in this cellar at present.", "skk": "메리웨더 씨는 이사회 의장이고, 런던의 대담한 범죄자들이 이 금고에 상당한 관심을 가질 만한 이유를 설명해줄 거예요.", "ko": "\"'메리웨더 씨는 이사회 의장이시니, 런던의 대담한 범죄자들이 지금 이 지하 금고에 상당한 관심을 가질 만한 이유를 직접 설명해주실 겁니다.'\"", "pi": 35}, {"t": "‘It is our French gold,’ whispered the director.", "sk": "It is our French gold, whispered the director.", "skk": "우리 프랑스 금이에요, 이사가 속삭였다.", "ko": "\"'우리 프랑스 금입니다,' 그 이사가 속삭이듯 말했습니다.\"", "pi": 35}, {"t": "‘We have had several warnings that an attempt might be made upon it.’", "sk": "We have had several warnings that an attempt might be made upon it.", "skk": "그걸 노린 시도가 있을지 모른다는 경고를 여러 번 받았어요.", "ko": "\"'그것을 노린 시도가 있을지도 모른다는 경고를 여러 차례 받았습니다.'\"", "pi": 35}, {"t": "‘Your French gold?’", "sk": "Your French gold?", "skk": "당신들의 프랑스 금이라고요?", "ko": "\"'당신들의 프랑스 금이라고요?'\"", "pi": 35}, {"t": "‘Yes.", "sk": "Yes.", "skk": "네.", "ko": "\"'그렇습니다.'\"", "pi": 35}, {"t": "We had occasion some months ago to strengthen our resources and borrowed for that purpose 30,000 napoleons from the Bank of France.", "sk": "We had occasion some months ago to strengthen our resources and borrowed for that purpose 30,000 napoleons from the Bank of France.", "skk": "몇 달 전 자금을 보강할 일이 있어서 프랑스 은행에서 나폴레옹 금화 3만 개를 빌렸어요.", "ko": "\"몇 달 전 저희 자금을 보강할 일이 있어서, 그 목적으로 프랑스 은행에서 나폴레옹 금화 3만 개를 빌려왔습니다.\"", "pi": 35}, {"t": "It has become known that we have never had occasion to unpack the money, and that it is still lying in our cellar.", "sk": "It has become known that we have never had occasion to unpack the money, and that it is still lying in our cellar.", "skk": "그 돈을 풀어볼 일이 없었고, 여전히 지하 금고에 그대로 있다는 게 알려졌어요.", "ko": "\"저희가 그 돈을 풀어볼 일이 한 번도 없었고, 여전히 지하 금고에 그대로 놓여 있다는 사실이 알려지고 말았습니다.\"", "pi": 35}, {"t": "The crate upon which I sit contains 2,000 napoleons packed between layers of lead foil.", "sk": "The crate upon which I sit contains 2,000 napoleons packed between layers of lead foil.", "skk": "제가 앉은 이 궤짝에는 납박 층 사이에 나폴레옹 금화 2천 개가 들어 있어요.", "ko": "\"제가 지금 앉아 있는 이 궤짝만 해도 납박 층 사이에 나폴레옹 금화 2천 개가 담겨 있습니다.\"", "pi": 35}, {"t": "Our reserve of bullion is much larger at present than is usually kept in a single branch office, and the directors have had misgivings upon the subject.’", "sk": "Our reserve of bullion is much larger at present than is usually kept in a single branch office, and the directors have had misgivings upon the subject.", "skk": "현재 저희 금괴 보유량은 지점 한 곳에 보통 두는 것보다 훨씬 많아서, 이사진들도 이 문제에 불안을 느껴왔어요.", "ko": "\"'지금 저희가 보유한 금괴는 지점 한 곳에 보통 두는 양보다 훨씬 많아서, 이사진들도 이 문제로 줄곧 불안해했습니다.'\"", "pi": 35}, {"t": "‘Which were very well justified,’ observed Holmes.", "sk": "Which were very well justified, observed Holmes.", "skk": "그건 아주 타당한 불안이었죠, 홈즈가 말했다.", "ko": "\"'그 불안은 아주 타당한 것이었죠,' 홈즈가 말했습니다.\"", "pi": 35}, {"t": "‘And now it is time that we arranged our little plans.", "sk": "And now it is time that we arranged our little plans.", "skk": "자, 이제 우리 작은 계획을 짤 시간이에요.", "ko": "\"'자, 이제 저희끼리 작은 계획을 정리할 시간이군요.'\"", "pi": 36}, {"t": "I expect that within an hour matters will come to a head.", "sk": "I expect that within an hour matters will come to a head.", "skk": "한 시간 안에 일이 절정에 이를 거라고 봐요.", "ko": "\"한 시간 안에는 상황이 절정에 다다를 것으로 봅니다.\"", "pi": 36}, {"t": "In the meantime Mr. Merryweather, we must put the screen over that dark lantern.’", "sk": "In the meantime Mr. Merryweather, we must put the screen over that dark lantern.", "skk": "그동안 메리웨더 씨, 저 어둠상자 랜턴에 가리개를 씌워야 해요.", "ko": "\"'그동안 메리웨더 씨, 저 어둠상자 랜턴에 가리개를 씌워야겠습니다.'\"", "pi": 36}, {"t": "‘And sit in the dark?’", "sk": "And sit in the dark?", "skk": "그럼 어둠 속에 앉아 있으라고요?", "ko": "\"'그럼 어둠 속에 앉아 있으라는 말씀입니까?'\"", "pi": 36}, {"t": "‘I am afraid so.", "sk": "I am afraid so.", "skk": "유감이지만 그래요.", "ko": "\"'유감이지만 그렇습니다.'\"", "pi": 36}, {"t": "I had brought a pack of cards in my pocket, and I thought that, as we were a partie carrée, you might have your rubber after all.", "sk": "I had brought a pack of cards in my pocket, and I thought that, as we were a partie carrée, you might have your rubber after all.", "skk": "주머니에 카드 한 벌을 가져왔는데, 우리가 넷이니 결국 카드 게임을 하실 수 있겠다 싶었어요.", "ko": "\"주머니에 카드 한 벌을 챙겨 왔는데, 저희가 마침 넷이 모였으니 결국 카드 게임을 한 판 하실 수 있겠다 싶었습니다.\"", "pi": 36}, {"t": "But I see that the enemy’s preparations have gone so far that we cannot risk the presence of a light.", "sk": "But I see that the enemy’s preparations have gone so far that we cannot risk the presence of a light.", "skk": "하지만 적의 준비가 이미 너무 진행돼서 불빛을 켜는 위험을 감수할 수 없겠네요.", "ko": "\"하지만 보아하니 적들의 준비가 이미 너무 진척돼서, 불빛을 켜두는 위험을 감수할 수는 없겠습니다.\"", "pi": 36}, {"t": "And, first of all, we must choose our positions.", "sk": "And, first of all, we must choose our positions.", "skk": "그리고 우선 자리부터 정해야겠어요.", "ko": "\"그리고 무엇보다 먼저 각자 자리부터 정해야겠습니다.\"", "pi": 36}, {"t": "These are daring men, and though we shall take them at a disadvantage, they may do us some harm unless we are careful.", "sk": "These are daring men, and though we shall take them at a disadvantage, they may do us some harm unless we are careful.", "skk": "이들은 대담한 자들이니, 우리가 유리한 상황이어도 조심하지 않으면 해를 입힐 수 있어요.", "ko": "\"이자들은 대담한 자들이니, 우리가 유리한 위치에서 급습한다 해도, 조심하지 않으면 우리에게 해를 끼칠 수도 있습니다.\"", "pi": 36}, {"t": "I shall stand behind this crate, and do you conceal yourselves behind those.", "sk": "I shall stand behind this crate, and do you conceal yourselves behind those.", "skk": "저는 이 궤짝 뒤에 서 있을 테니, 여러분은 저것들 뒤에 숨어 계세요.", "ko": "\"저는 이 궤짝 뒤에 서 있을 테니, 여러분은 저 궤짝들 뒤에 몸을 숨기시죠.\"", "pi": 36}, {"t": "Then, when I flash a light upon them, close in swiftly.", "sk": "Then, when I flash a light upon them, close in swiftly.", "skk": "그러다 제가 그들에게 불빛을 비추면 재빨리 좁혀 들어오세요.", "ko": "\"그러다 제가 그들에게 불빛을 확 비추면, 그때 재빨리 좁혀 들어오시면 됩니다.\"", "pi": 36}, {"t": "If they fire, Watson, have no compunction about shooting them down.’", "sk": "If they fire, Watson, have no compunction about shooting them down.", "skk": "저들이 쏘면, 왓슨, 망설이지 말고 쏴서 쓰러뜨려요.", "ko": "\"'저들이 먼저 쏘거든, 왓슨, 거리낌 없이 쏴서 쓰러뜨리세요.'\"", "pi": 36}, {"t": "I placed my revolver, cocked, upon the top of the wooden case behind which I crouched.", "sk": "I placed my revolver, cocked, upon the top of the wooden case behind which I crouched.", "skk": "공이치기를 당긴 리볼버를 제가 웅크린 나무 상자 위에 올려뒀습니다.", "ko": "\"저는 공이치기를 당긴 리볼버를 제가 웅크리고 있던 나무 상자 위에 올려두었습니다.\"", "pi": 37}, {"t": "Holmes shot the slide across the front of his lantern and left us in pitch darkness—such an absolute darkness as I have never before experienced.", "sk": "Holmes shot the slide across the front of his lantern and left us in pitch darkness—such an absolute darkness as I have never before experienced.", "skk": "홈즈는 랜턴 앞의 가리개를 밀어 닫아 우리를 칠흑 같은 어둠 속에 남겨뒀습니다, 전에 겪어본 적 없는 완전한 어둠이었죠.", "ko": "\"홈즈는 랜턴 앞의 가리개를 스르륵 밀어 닫아 우리를 칠흑 같은 어둠 속에 남겨두었습니다, 이전에는 한 번도 경험해본 적 없는 완전한 어둠이었습니다.\"", "pi": 37}, {"t": "The smell of hot metal remained to assure us that the light was still there, ready to flash out at a moment’s notice.", "sk": "The smell of hot metal remained to assure us that the light was still there, ready to flash out at a moment’s notice.", "skk": "뜨거운 금속 냄새가 남아, 불빛이 언제든 확 켜질 준비가 된 채 여전히 거기 있다는 걸 알려줬습니다.", "ko": "\"뜨거운 금속 냄새만이 남아, 그 불빛이 즉각 켤 수 있는 채로 여전히 거기 있다는 사실을 우리에게 알려주었습니다.\"", "pi": 37}, {"t": "To me, with my nerves worked up to a pitch of expectancy, there was something depressing and subduing in the sudden gloom, and in the cold dank air of the vault.", "sk": "To me there was something depressing and subduing in the sudden gloom, and in the cold dank air of the vault.", "skk": "기대감으로 신경이 곤두선 저에게는, 갑작스러운 어둠과 금고의 차갑고 축축한 공기 속에 뭔가 마음을 짓누르는 게 있었습니다.", "ko": "\"기대감으로 신경이 잔뜩 곤두선 저에게는, 그 갑작스러운 어둠과, 금고의 차갑고 축축한 공기 속에 뭔가 마음을 짓누르고 가라앉히는 것이 있었습니다.\"", "pi": 37}, {"t": "‘They have but one retreat,’ whispered Holmes.", "sk": "They have but one retreat, whispered Holmes.", "skk": "저들에게 퇴로는 하나뿐이에요, 홈즈가 속삭였다.", "ko": "\"'저들에게 퇴로는 딱 하나뿐입니다,' 홈즈가 속삭였습니다.\"", "pi": 37}, {"t": "‘That is back through the house into Saxe-Coburg Square.", "sk": "That is back through the house into Saxe-Coburg Square.", "skk": "그건 그 집을 지나 다시 색스코버그 스퀘어로 나가는 길이죠.", "ko": "\"'그건 그 집을 지나 다시 색스코버그 스퀘어로 빠져나가는 길입니다.'\"", "pi": 37}, {"t": "I hope that you have done what I asked you, Jones?’", "sk": "I hope that you have done what I asked you, Jones?", "skk": "제가 부탁한 대로 해두셨길 바라요, 존스?", "ko": "\"'제가 부탁드린 대로 해두셨겠지요, 존스?'\"", "pi": 37}, {"t": "‘I have an inspector and two officers waiting at the front door.’", "sk": "I have an inspector and two officers waiting at the front door.", "skk": "경위 한 명과 경관 둘을 정문에 대기시켜뒀어요.", "ko": "\"'경위 한 명과 경관 두 명을 정문에 대기시켜두었습니다.'\"", "pi": 37}, {"t": "‘Then we have stopped all the holes.", "sk": "Then we have stopped all the holes.", "skk": "그럼 우리가 구멍을 다 막은 거네요.", "ko": "\"'그렇다면 우리가 빠져나갈 구멍은 다 막은 셈이군요.'\"", "pi": 37}, {"t": "And now we must be silent and wait.’", "sk": "And now we must be silent and wait.", "skk": "이제 조용히 기다려야 해요.", "ko": "\"'이제 우리는 조용히 기다리기만 하면 됩니다.'\"", "pi": 37}, {"t": "What a time it seemed!", "sk": "What a time it seemed!", "skk": "정말 긴 시간처럼 느껴졌습니다!", "ko": "\"정말이지 길게만 느껴지는 시간이었습니다!\"", "pi": 37}, {"t": "From comparing notes afterwards it was but an hour and a quarter, yet it appeared to me that the night must have almost gone, and the dawn be breaking above us.", "sk": "From comparing notes afterwards it was but an hour and a quarter, yet it appeared to me that the night must have almost gone, and the dawn be breaking above us.", "skk": "나중에 서로 맞춰보니 겨우 한 시간 십오 분이었지만, 저에게는 밤이 거의 다 지나 위에서 새벽이 밝아오는 것만 같았습니다.", "ko": "\"나중에 서로 시간을 맞춰보니 실제로는 겨우 한 시간 십오 분에 지나지 않았지만, 저에게는 밤이 거의 다 지나가고 위에서는 새벽이 밝아오고 있는 것만 같았습니다.\"", "pi": 37}, {"t": "My limbs were weary and stiff, for I feared to change my position; yet my nerves were worked up to the highest pitch of tension, and my hearing was so acute that I could not only hear the gentle breathing of my companions, but I could distinguish the deeper, heavier in-breath of the bulky Jones from the thin, sighing note of the bank director.", "sk": "My limbs were weary and stiff, for I feared to change my position; yet my nerves were worked up to the highest pitch of tension, and my hearing was so acute that I could distinguish the deeper, heavier in-breath of the bulky Jones from the thin, sighing note of the bank director.", "skk": "팔다리가 지치고 뻣뻣해졌습니다, 자세를 바꾸기가 두려웠거든요, 신경은 극도로 곤두섰고 청각이 예민해져서 덩치 큰 존스의 깊은 숨소리와 은행 이사의 가늘고 한숨 섞인 숨소리를 구분할 수 있었습니다.", "ko": "\"제 팔다리는 지치고 뻣뻣해졌습니다, 자세를 바꾸기가 두려웠기 때문이죠, 하지만 신경은 극도의 긴장 상태로 곤두서 있었고, 청각이 어찌나 예민해졌던지 덩치 큰 존스의 깊고 무거운 들숨과 은행 이사의 가늘고 한숨 섞인 숨소리까지 구분해낼 수 있었습니다.\"", "pi": 38}, {"t": "From my position I could look over the case in the direction of the floor.", "sk": "From my position I could look over the case in the direction of the floor.", "skk": "제 위치에서는 상자 너머로 바닥 쪽을 볼 수 있었습니다.", "ko": "\"제가 있던 자리에서는 상자 너머로 바닥 쪽을 내다볼 수 있었습니다.\"", "pi": 38}, {"t": "Suddenly my eyes caught the glint of a light.", "sk": "Suddenly my eyes caught the glint of a light.", "skk": "갑자기 제 눈에 불빛의 반짝임이 들어왔습니다.", "ko": "\"그런데 갑자기 제 눈에 불빛의 반짝임이 포착되었습니다.\"", "pi": 38}, {"t": "At first it was but a lurid spark upon the stone pavement.", "sk": "At first it was but a lurid spark upon the stone pavement.", "skk": "처음엔 돌바닥 위의 섬뜩한 불꽃 하나에 불과했습니다.", "ko": "\"처음에는 돌바닥 위에 이는 섬뜩한 불꽃 하나에 지나지 않았습니다.\"", "pi": 38}, {"t": "Then it lengthened out until it became a yellow line, and then, without any warning or sound, a gash seemed to open and a hand appeared, a white, almost womanly hand, which felt about in the centre of the little area of light.", "sk": "Then it lengthened out until it became a yellow line, and then, without any warning or sound, a gash seemed to open and a hand appeared, which felt about in the centre of the little area of light.", "skk": "그러다 점점 길어져 노란 선이 됐고, 그다음 아무 경고도 소리도 없이 틈이 벌어지는 듯하더니 손이 나타났습니다, 하얗고 거의 여자 같은 손이, 그 작은 빛 한가운데를 더듬었습니다.", "ko": "\"그러다 점점 길어져 하나의 노란 선이 되었고, 그런 다음 아무런 경고도 소리도 없이 갈라진 틈이 벌어지는 듯하더니 손 하나가 나타났습니다, 하얗고 거의 여자 손 같은 그 손은 그 작은 빛의 한가운데를 더듬거렸습니다.\"", "pi": 38}, {"t": "For a minute or more the hand, with its writhing fingers, protruded out of the floor.", "sk": "For a minute or more the hand, with its writhing fingers, protruded out of the floor.", "skk": "1분 넘게 그 손은, 꿈틀거리는 손가락과 함께, 바닥 밖으로 튀어나와 있었습니다.", "ko": "\"1분 남짓한 시간 동안 그 손은 꿈틀거리는 손가락을 매단 채 바닥 밖으로 튀어나와 있었습니다.\"", "pi": 38}, {"t": "Then it was withdrawn as suddenly as it appeared, and all was dark again save the single lurid spark which marked a chink between the stones.", "sk": "Then it was withdrawn as suddenly as it appeared, and all was dark again save the single lurid spark which marked a chink between the stones.", "skk": "그러다 나타났을 때만큼 갑자기 사라졌고, 돌 틈에 표시된 그 섬뜩한 불꽃 하나만 빼고 다시 온통 어두워졌습니다.", "ko": "\"그러더니 나타났을 때만큼이나 갑자기 손이 다시 들어가버렸고, 돌 틈 하나를 나타내는 그 섬뜩한 불꽃 하나만 남긴 채 다시 온통 어두워졌습니다.\"", "pi": 38}, {"t": "Its disappearance, however, was but momentary.", "sk": "Its disappearance, however, was but momentary.", "skk": "하지만 그 사라짐은 잠깐뿐이었습니다.", "ko": "\"하지만 그렇게 사라진 것도 잠깐뿐이었습니다.\"", "pi": 38}, {"t": "With a rending, tearing sound, one of the broad, white stones turned over upon its side and left a square, gaping hole, through which streamed the light of a lantern.", "sk": "With a rending, tearing sound, one of the broad, white stones turned over upon its side and left a square, gaping hole, through which streamed the light of a lantern.", "skk": "찢어지는 듯한 소리와 함께, 넓고 하얀 돌 하나가 옆으로 뒤집히며 네모난 구멍을 남겼고, 그 틈으로 랜턴 불빛이 흘러들었습니다.", "ko": "\"찢어지는 듯한 소리와 함께 넓고 하얀 돌 하나가 옆으로 뒤집히며 입을 쩍 벌린 네모난 구멍을 남겼고, 그 구멍을 통해 랜턴 불빛이 흘러들어왔습니다.\"", "pi": 38}, {"t": "Over the edge there peeped a clean-cut, boyish face, which looked keenly about it, and then, with a hand on either side of the aperture, drew itself shoulder-high and waist-high, until one knee rested upon the edge.", "sk": "Over the edge there peeped a clean-cut, boyish face, and then, with a hand on either side of the aperture, drew itself shoulder-high and waist-high, until one knee rested upon the edge.", "skk": "구멍 가장자리로 말끔하고 앳된 얼굴이 빼꼼 나타나 날카롭게 주위를 살피더니, 구멍 양쪽에 손을 짚고 어깨 높이, 허리 높이까지 몸을 끌어올려 결국 한쪽 무릎이 가장자리에 걸쳤습니다.", "ko": "\"구멍 가장자리로 말끔하고 앳된 얼굴 하나가 빼꼼 나타나 날카롭게 주위를 살피더니, 이내 구멍 양쪽에 손을 짚고 어깨 높이, 허리 높이까지 몸을 끌어올려 마침내 한쪽 무릎이 가장자리에 걸치게 되었습니다.\"", "pi": 38}, {"t": "In another instant he stood at the side of the hole and was hauling after him a companion, lithe and small like himself, with a pale face and a shock of very red hair.", "sk": "In another instant he stood at the side of the hole and was hauling after him a companion, lithe and small like himself, with a pale face and a shock of very red hair.", "skk": "다음 순간 그는 구멍 옆에 서서 자기처럼 날렵하고 작은 동료를, 창백한 얼굴에 새빨간 머리를 텁수룩하게 기른 동료를 끌어올리고 있었습니다.", "ko": "\"다음 순간 그는 구멍 옆에 서서, 자기처럼 날렵하고 몸집이 작은 데다 창백한 얼굴에 새빨간 머리를 텁수룩하게 기른 동료 한 명을 뒤이어 끌어올리고 있었습니다.\"", "pi": 38}, {"t": "‘It’s all clear,’ he whispered.", "sk": "It’s all clear, he whispered.", "skk": "다 안전해, 그가 속삭였다.", "ko": "\"'다 안전해,' 그가 속삭였습니다.\"", "pi": 38}, {"t": "‘Have you the chisel and the bags?", "sk": "Have you the chisel and the bags?", "skk": "끌이랑 자루 챙겼어?", "ko": "\"'끌이랑 자루는 챙겼어?'\"", "pi": 39}, {"t": "Great Scott!", "sk": "Great Scott!", "skk": "세상에!", "ko": "\"'세상에!'\"", "pi": 39}, {"t": "Jump, Archie, jump, and I’ll swing for it!’", "sk": "Jump, Archie, jump, and I’ll swing for it!", "skk": "뛰어, 아치, 뛰어, 그럼 내가 목이 매달리는 한이 있어도!", "ko": "\"'뛰어, 아치, 뛰어, 나야 목이 매달리는 한이 있어도 상관없어!'\"", "pi": 39}, {"t": "Sherlock Holmes had sprung out and seized the intruder by the collar.", "sk": "Sherlock Holmes had sprung out and seized the intruder by the collar.", "skk": "셜록 홈즈가 뛰쳐나가 침입자의 옷깃을 붙잡았습니다.", "ko": "\"셜록 홈즈가 어느새 뛰쳐나가 그 침입자의 옷깃을 붙잡고 있었습니다.\"", "pi": 39}, {"t": "The other dived down the hole, and I heard the sound of rending cloth as Jones clutched at his skirts.", "sk": "The other dived down the hole, and I heard the sound of rending cloth as Jones clutched at his skirts.", "skk": "다른 한 명은 구멍 속으로 뛰어들었고, 존스가 옷자락을 움켜쥐면서 옷이 찢어지는 소리가 들렸습니다.", "ko": "\"다른 한 명은 구멍 속으로 몸을 던졌고, 존스가 그의 옷자락을 움켜쥐면서 옷이 찢어지는 소리가 들려왔습니다.\"", "pi": 39}, {"t": "The light flashed upon the barrel of a revolver, but Holmes’ hunting crop came down on the man’s wrist, and the pistol clinked upon the stone floor.", "sk": "The light flashed upon the barrel of a revolver, but Holmes’ hunting crop came down on the man’s wrist, and the pistol clinked upon the stone floor.", "skk": "불빛이 권총 총신에 번쩍였지만, 홈즈의 승마용 채찍이 남자의 손목에 내리쳤고, 권총이 돌바닥에 쨍그랑 떨어졌습니다.", "ko": "\"불빛이 권총 총신에 번쩍였지만, 홈즈의 승마용 채찍이 그 남자의 손목에 내리쳤고, 권총은 돌바닥에 쨍그랑 소리를 내며 떨어지고 말았습니다.\"", "pi": 39}, {"t": "‘It’s no use, John Clay,’ said Holmes blandly.", "sk": "It’s no use, John Clay, said Holmes blandly.", "skk": "소용없어, 존 클레이, 홈즈가 태연하게 말했다.", "ko": "\"'소용없어, 존 클레이,' 홈즈가 태연하게 말했습니다.\"", "pi": 39}, {"t": "‘You have no chance at all.’", "sk": "You have no chance at all.", "skk": "넌 가망이 전혀 없어.", "ko": "\"'너는 가망이 전혀 없어.'\"", "pi": 39}, {"t": "‘So I see,’ the other answered with the utmost coolness.", "sk": "So I see, the other answered with the utmost coolness.", "skk": "그런 것 같군, 다른 남자가 더없이 침착하게 대답했다.", "ko": "\"'그런 것 같군,' 그 남자가 더없이 침착하게 대답했습니다.\"", "pi": 39}, {"t": "‘I fancy that my pal is all right, though I see you have got his coat-tails.’", "sk": "I fancy that my pal is all right, though I see you have got his coat-tails.", "skk": "내 동료는 괜찮을 것 같군, 자네가 그의 연미복 자락을 붙잡은 건 보이지만.", "ko": "\"'내 동료는 괜찮을 것 같군, 자네가 그의 연미복 자락을 붙잡은 건 보이지만 말이야.'\"", "pi": 39}, {"t": "‘There are three men waiting for him at the door,’ said Holmes.", "sk": "There are three men waiting for him at the door, said Holmes.", "skk": "문 앞에서 그를 기다리는 사람이 셋 있어, 홈즈가 말했다.", "ko": "\"'문 앞에서 그를 기다리고 있는 사람이 셋이나 있다네,' 홈즈가 말했습니다.\"", "pi": 39}, {"t": "‘Oh, indeed!", "sk": "Oh, indeed!", "skk": "오, 그런가!", "ko": "\"'오, 그런가!'\"", "pi": 39}, {"t": "You seem to have done the thing very completely.", "sk": "You seem to have done the thing very completely.", "skk": "이 일을 아주 완벽하게 해낸 것 같군.", "ko": "\"'이 일을 아주 완벽하게 해낸 모양이군.'\"", "pi": 40}, {"t": "I must compliment you.’", "sk": "I must compliment you.", "skk": "칭찬해야겠어.", "ko": "\"칭찬을 좀 해야겠어.'\"", "pi": 40}, {"t": "‘And I you,’ Holmes answered.", "sk": "And I you, Holmes answered.", "skk": "나도 자네를 칭찬하지, 홈즈가 대답했다.", "ko": "\"'나도 자네를 칭찬하지,' 홈즈가 대답했습니다.\"", "pi": 40}, {"t": "‘Your red-headed idea was very new and effective.’", "sk": "Your red-headed idea was very new and effective.", "skk": "자네의 빨간 머리 아이디어는 아주 참신하고 효과적이었어.", "ko": "\"'자네의 그 빨간 머리 아이디어는 아주 참신하고 효과적이었어.'\"", "pi": 40}, {"t": "‘You’ll see your pal again presently,’ said Jones.", "sk": "You’ll see your pal again presently, said Jones.", "skk": "곧 자네 동료를 다시 보게 될 거야, 존스가 말했다.", "ko": "\"'곧 자네 동료를 다시 보게 될 거야,' 존스가 말했습니다.\"", "pi": 40}, {"t": "‘He’s quicker at climbing down holes than I am.", "sk": "He’s quicker at climbing down holes than I am.", "skk": "그는 구멍 내려가는 데는 나보다 빠르니까.", "ko": "\"'그가 구멍으로 내려가는 데는 나보다 빠른 모양이니 말이야.'\"", "pi": 40}, {"t": "Just hold out while I fix the derbies.’", "sk": "Just hold out while I fix the derbies.", "skk": "내가 수갑을 채우는 동안 좀 참아.", "ko": "\"내가 수갑을 채우는 동안 잠깐만 참으라고.'\"", "pi": 40}, {"t": "‘I beg that you will not touch me with your filthy hands,’ remarked our prisoner as the handcuffs clattered upon his wrists.", "sk": "I beg that you will not touch me with your filthy hands, remarked our prisoner as the handcuffs clattered upon his wrists.", "skk": "더러운 손으로 날 만지지 말아주게, 수갑이 손목에 채워지면서 죄수가 말했다.", "ko": "\"'더러운 손으로 날 만지지 말아주었으면 하는데,' 수갑이 손목에서 철컥거리는 소리를 내는 가운데 그 죄수가 말했습니다.\"", "pi": 40}, {"t": "‘You may not be aware that I have royal blood in my veins.", "sk": "You may not be aware that I have royal blood in my veins.", "skk": "내 핏줄에 왕족의 피가 흐른다는 걸 모를 수도 있겠지.", "ko": "\"'자네들은 내 혈관에 왕족의 피가 흐른다는 사실을 모를 수도 있겠군.'\"", "pi": 40}, {"t": "Have the goodness, also, when you address me always to say ‘sir’ and ‘please.’’", "sk": "Have the goodness, also, when you address me always to say sir and please.", "skk": "또한 나를 부를 때는 항상 '님'과 '부디'를 붙이는 친절을 베풀도록.", "ko": "\"또한 나를 부를 때는 언제나 '님'과 '부디'를 붙여주는 친절을 베풀어주게.'\"", "pi": 40}, {"t": "‘All right,’ said Jones with a stare and a snigger.", "sk": "All right, said Jones with a stare and a snigger.", "skk": "알겠어, 존스가 빤히 쳐다보며 킥킥 웃으면서 말했다.", "ko": "\"'알겠수다,' 존스가 빤히 쳐다보며 킥킥 웃음을 흘리면서 말했습니다.\"", "pi": 40}, {"t": "‘Well, would you please, sir, march upstairs, where we can get a cab to carry your Highness to the police-station?’", "sk": "Well, would you please, sir, march upstairs, where we can get a cab to carry your Highness to the police-station?", "skk": "자, 님, 부디 위층으로 행진해주시겠소, 마차를 잡아서 전하를 경찰서로 모셔다드릴 수 있게?", "ko": "\"'자, 그럼 님, 부디 위층으로 행진이라도 해주시겠소, 마차를 한 대 잡아서 전하를 경찰서로 모셔다드릴 수 있게 말이오?'\"", "pi": 40}, {"t": "‘That is better,’ said John Clay serenely.", "sk": "That is better, said John Clay serenely.", "skk": "그게 낫군, 존 클레이가 태연하게 말했다.", "ko": "\"'그게 낫군,' 존 클레이가 유유히 말했습니다.\"", "pi": 41}, {"t": "He made a sweeping bow to the three of us and walked quietly off in the custody of the detective.", "sk": "He made a sweeping bow to the three of us and walked quietly off in the custody of the detective.", "skk": "그는 우리 셋에게 큰 절을 하고는 형사의 감시 아래 조용히 걸어나갔습니다.", "ko": "\"그는 우리 세 사람을 향해 큰 절을 한 번 하더니 형사의 감시를 받으며 조용히 걸어나갔습니다.\"", "pi": 41}, {"t": "‘Really, Mr. Holmes,’ said Mr. Merryweather as we followed them from the cellar, ‘I do not know how the bank can thank you or repay you.", "sk": "Really, Mr. Holmes, said Mr. Merryweather as we followed them from the cellar, I do not know how the bank can thank you or repay you.", "skk": "정말이지, 홈즈 씨, 메리웨더 씨가 우리가 그들을 뒤따라 지하 금고를 나서면서 말했다, 은행이 어떻게 당신께 감사하고 보답해야 할지 모르겠어요.", "ko": "\"'정말이지, 홈즈 씨,' 우리가 그들을 뒤따라 지하 금고를 나서면서 메리웨더 씨가 말했습니다, '은행이 당신께 어떻게 감사드리고 보답해야 할지 모르겠습니다.'\"", "pi": 41}, {"t": "There is no doubt that you have detected and defeated in the most complete manner one of the most determined attempts at bank robbery that have ever come within my experience.’", "sk": "There is no doubt that you have detected and defeated in the most complete manner one of the most determined attempts at bank robbery that have ever come within my experience.", "skk": "제 경험상 가장 결연했던 은행 강도 시도 중 하나를 당신이 가장 완벽하게 탐지하고 격퇴했다는 데는 의심의 여지가 없어요.", "ko": "\"제가 경험한 것 중 가장 결연했던 은행 강도 시도 하나를 당신이 더할 나위 없이 완벽하게 탐지하고 격퇴했다는 데는 의심의 여지가 없습니다.'\"", "pi": 41}, {"t": "‘I have had one or two little scores of my own to settle with Mr. John Clay,’ said Holmes.", "sk": "I have had one or two little scores of my own to settle with Mr. John Clay, said Holmes.", "skk": "저도 존 클레이 씨와 개인적으로 청산할 작은 빚이 한두 개 있었어요, 홈즈가 말했다.", "ko": "\"'저 역시 존 클레이 씨와 개인적으로 청산할 작은 빚이 한두 가지 있었습니다,' 홈즈가 말했습니다.\"", "pi": 41}, {"t": "‘I have been at some small expense over this matter, which I shall expect the bank to refund, but beyond that I am amply repaid by having had an experience which is in many ways unique, and by hearing the very remarkable narrative of the Red-headed League.’", "sk": "I have been at some small expense over this matter, which I shall expect the bank to refund, but beyond that I am amply repaid by having had an experience which is in many ways unique, and by hearing the very remarkable narrative of the Red-headed League.", "skk": "이 일에 약간의 비용이 들었는데 은행이 환급해주길 기대하지만, 그 외에는 여러모로 특별한 경험을 하고 붉은 머리 연맹의 정말 놀라운 이야기를 들은 것만으로도 충분히 보상받았어요.", "ko": "\"'이번 일로 약간의 비용이 들었으니 은행 측에서 환급해주시길 기대하지만, 그 외에는 여러모로 유례없는 경험을 하고 붉은 머리 연맹의 참으로 놀라운 이야기까지 듣게 된 것만으로도 이미 충분히 보상받은 셈입니다.'\"", "pi": 41}, {"t": "‘You see, Watson,’ he explained in the early hours of the morning as we sat over a glass of whisky and soda in Baker Street, ‘it was perfectly obvious from the first that the only possible object of this rather fantastic business of the advertisement of the League, and the copying of the Encyclopædia, must be to get this not over-bright pawnbroker out of the way for a number of hours every day.", "sk": "You see, Watson, he explained in the early hours of the morning as we sat over a glass of whisky and soda in Baker Street, it was perfectly obvious from the first that the only possible object of this rather fantastic business of the advertisement of the League, and the copying of the Encyclopædia, must be to get this not over-bright pawnbroker out of the way for a number of hours every day.", "skk": "알다시피, 왓슨, 이른 새벽 베이커 스트리트에서 위스키 소다를 마시며 그가 설명했다, 이 다소 기이한 연맹 광고와 백과사전 필사 사업의 유일하게 가능한 목적은 이 그리 똑똑하지 않은 전당포 주인을 매일 몇 시간씩 자리를 비우게 만드는 것이었음이 처음부터 완전히 명백했다.", "ko": "\"'알겠나, 왓슨,' 이른 새벽 베이커 스트리트에서 위스키 소다 잔을 앞에 두고 앉아 있을 때 그가 설명하기를, '이 다소 기이한 연맹 광고 사업과 백과사전 필사라는 것의 유일하게 가능한 목적이, 그다지 똑똑하지 못한 이 전당포 주인을 매일 몇 시간씩 자리를 비우게 만드는 데 있다는 것은 처음부터 완전히 명백한 일이었네.\"", "pi": 41}, {"t": "It was a curious way of managing it, but, really, it would be difficult to suggest a better.", "sk": "It was a curious way of managing it, but, really, it would be difficult to suggest a better.", "skk": "그건 기묘한 처리 방식이었지만, 사실 더 나은 방법을 제안하기도 어려울 거야.", "ko": "\"그건 참으로 기묘한 방식이었지만, 사실 그보다 더 나은 방법을 제안하기도 어려울 걸세.\"", "pi": 41}, {"t": "The method was no doubt suggested to Clay’s ingenious mind by the colour of his accomplice’s hair.", "sk": "The method was no doubt suggested to Clay’s ingenious mind by the colour of his accomplice’s hair.", "skk": "그 방법은 틀림없이 공범의 머리색이 클레이의 기발한 머릿속에 떠올려준 것일 거야.", "ko": "\"그 방법은 틀림없이 자기 공범의 머리색을 보고서 클레이의 그 기발한 머릿속에 떠오른 것이었을 걸세.\"", "pi": 41}, {"t": "The £4 a week was a lure which must draw him, and what was it to them, who were playing for thousands?", "sk": "The £4 a week was a lure which must draw him, and what was it to them, who were playing for thousands?", "skk": "주급 4파운드는 그를 끌어들일 미끼였고, 수천 파운드를 노리는 그들에게 그게 뭐 대수였겠나?", "ko": "\"주급 4파운드는 틀림없이 그를 끌어들일 미끼였을 테고, 수천 파운드를 걸고 노름하는 그들에게 그 정도가 뭐 그리 대수였겠나?\"", "pi": 41}, {"t": "They put in the advertisement, one rogue has the temporary office, the other rogue incites the man to apply for it, and together they manage to secure his absence every morning in the week.", "sk": "They put in the advertisement, one rogue has the temporary office, the other rogue incites the man to apply for it, and together they manage to secure his absence every morning in the week.", "skk": "그들은 광고를 냈고, 한 악당은 임시 사무실을 차지하고, 다른 악당은 그 남자가 지원하도록 부추기고, 함께 매일 아침 그의 부재를 확보해낸다.", "ko": "\"그들은 광고를 내고, 악당 한 명은 임시 사무실을 차지하며, 다른 한 명은 그 남자를 부추겨 지원하게 만들고, 이렇게 둘이서 함께 매일 아침 그의 자리를 비워두게 만드는 데 성공한 것이지.\"", "pi": 41}, {"t": "From the time that I heard of the assistant having come for half wages, it was obvious to me that he had some strong motive for securing the situation.’", "sk": "From the time that I heard of the assistant having come for half wages, it was obvious to me that he had some strong motive for securing the situation.", "skk": "그 조수가 절반 급여에도 왔다는 걸 들었을 때부터, 그가 그 자리를 얻으려는 강한 동기가 있었음이 내겐 명백했지.", "ko": "\"그 조수가 절반의 급여에도 그 자리에 왔다는 이야기를 들은 순간부터, 그에게 그 일자리를 얻어내려는 강한 동기가 있었다는 게 내게는 명백해 보였다네.'\"", "pi": 41}, {"t": "‘But how could you guess what the motive was?’", "sk": "But how could you guess what the motive was?", "skk": "근데 동기가 뭔지 어떻게 짐작했어?", "ko": "\"'그런데 그 동기가 무엇인지는 대체 어떻게 짐작하셨습니까?'\"", "pi": 42}, {"t": "‘Had there been women in the house, I should have suspected a mere vulgar intrigue.", "sk": "Had there been women in the house, I should have suspected a mere vulgar intrigue.", "skk": "그 집에 여자가 있었다면 단순히 저속한 치정극을 의심했을 거야.", "ko": "\"'그 집에 여자가 있었더라면, 나는 그저 흔한 저속한 치정극쯤을 의심했을 걸세.'\"", "pi": 42}, {"t": "That, however, was out of the question.", "sk": "That, however, was out of the question.", "skk": "하지만 그건 있을 수 없는 일이었지.", "ko": "\"하지만 그건 애초에 있을 수 없는 일이었네.\"", "pi": 42}, {"t": "The man’s business was a small one, and there was nothing in his house which could account for such elaborate preparations, and such an expenditure as they were at.", "sk": "The man’s business was a small one, and there was nothing in his house which could account for such elaborate preparations, and such an expenditure as they were at.", "skk": "그 남자의 사업은 작았고, 그런 정교한 준비와 지출을 설명할 만한 게 그의 집엔 없었어.", "ko": "\"그 남자의 가게는 작은 규모였고, 그런 정교한 준비와 그 정도의 지출을 설명해줄 만한 것이 그의 집 안에는 아무것도 없었네.\"", "pi": 42}, {"t": "It must, then, be something out of the house.", "sk": "It must, then, be something out of the house.", "skk": "그럼 뭔가 집 밖에 있는 게 틀림없었어.", "ko": "\"그렇다면 뭔가 집 밖에 있는 것이 틀림없었지.\"", "pi": 42}, {"t": "What could it be?", "sk": "What could it be?", "skk": "그게 뭘 수 있을까?", "ko": "\"그게 대체 무엇일 수 있을까?\"", "pi": 42}, {"t": "I thought of the assistant’s fondness for photography, and his trick of vanishing into the cellar.", "sk": "I thought of the assistant’s fondness for photography, and his trick of vanishing into the cellar.", "skk": "조수가 사진을 좋아한다는 것과 지하실로 사라지는 버릇이 떠올랐지.", "ko": "\"그 조수가 사진에 대해 갖고 있던 애착과, 지하실로 사라지곤 하던 그 버릇이 떠올랐네.\"", "pi": 42}, {"t": "The cellar!", "sk": "The cellar!", "skk": "지하실!", "ko": "\"지하실이라니!\"", "pi": 42}, {"t": "There was the end of this tangled clue.", "sk": "There was the end of this tangled clue.", "skk": "그게 바로 이 엉킨 실마리의 끝이었어.", "ko": "\"바로 그것이 이 얽히고설킨 실마리의 끝이었네.\"", "pi": 42}, {"t": "Then I made inquiries as to this mysterious assistant and found that I had to deal with one of the coolest and most daring criminals in London.", "sk": "Then I made inquiries as to this mysterious assistant and found that I had to deal with one of the coolest and most daring criminals in London.", "skk": "그다음 이 수상한 조수에 대해 조사했고 런던에서 가장 냉철하고 대담한 범죄자 중 하나를 상대하고 있다는 걸 알았지.", "ko": "\"그래서 나는 이 수상쩍은 조수에 대해 이런저런 조사를 해보았고, 런던에서 가장 냉철하고 가장 대담한 범죄자 중 한 명을 상대하고 있다는 사실을 알게 되었네.\"", "pi": 42}, {"t": "He was doing something in the cellar—something which took many hours a day for months on end.", "sk": "He was doing something in the cellar, something which took many hours a day for months on end.", "skk": "그는 지하실에서 뭔가를 하고 있었어, 몇 달 동안 매일 몇 시간씩 걸리는 무언가를.", "ko": "\"그는 지하실에서 무언가를 하고 있었네, 몇 달 동안이나 매일 몇 시간씩 걸리는 그 무언가를 말이야.\"", "pi": 42}, {"t": "What could it be, once more?", "sk": "What could it be, once more?", "skk": "또다시, 그게 뭘 수 있을까?", "ko": "\"또다시 말이지만, 그게 대체 무엇일 수 있었을까?\"", "pi": 42}, {"t": "I could think of nothing save that he was running a tunnel to some other building.", "sk": "I could think of nothing save that he was running a tunnel to some other building.", "skk": "다른 건물로 이어지는 터널을 파고 있다는 것 말고는 생각할 수 없었어.", "ko": "\"그가 다른 건물로 이어지는 터널을 파고 있다는 것 말고는 아무것도 생각할 수 없었네.'\"", "pi": 43}, {"t": "‘So far I had got when we went to visit the scene of action.", "sk": "So far I had got when we went to visit the scene of action.", "skk": "우리가 현장을 살펴보러 갔을 때까지는 여기까지 파악했었지.", "ko": "\"'우리가 현장을 살펴보러 갔을 때 나는 거기까지 파악한 상태였네.'\"", "pi": 43}, {"t": "I surprised you by beating upon the pavement with my stick.", "sk": "I surprised you by beating upon the pavement with my stick.", "skk": "지팡이로 보도를 두드려서 자넬 놀라게 했었지.", "ko": "\"지팡이로 보도를 두드려서 자네를 놀라게 했었지.\"", "pi": 43}, {"t": "I was ascertaining whether the cellar stretched out in front or behind.", "sk": "I was ascertaining whether the cellar stretched out in front or behind.", "skk": "지하실이 앞쪽으로 뻗어 있는지 뒤쪽으로 뻗어 있는지 확인하고 있었던 거야.", "ko": "\"지하실이 앞쪽으로 뻗어 있는지 뒤쪽으로 뻗어 있는지를 확인하고 있었던 걸세.\"", "pi": 43}, {"t": "It was not in front.", "sk": "It was not in front.", "skk": "앞쪽은 아니었어.", "ko": "\"앞쪽은 아니었네.\"", "pi": 43}, {"t": "Then I rang the bell, and, as I hoped, the assistant answered it.", "sk": "Then I rang the bell, and, as I hoped, the assistant answered it.", "skk": "그다음 벨을 눌렀고, 바랐던 대로, 조수가 나와서 응대했어.", "ko": "\"그다음 벨을 눌렀고, 내가 바랐던 대로 그 조수가 직접 나와서 응대했지.\"", "pi": 43}, {"t": "We have had some skirmishes, but we had never set eyes upon each other before.", "sk": "We have had some skirmishes, but we had never set eyes upon each other before.", "skk": "우리끼리 몇 번 신경전은 있었지만, 서로 얼굴을 마주한 적은 전에 없었지.", "ko": "\"우리끼리 몇 차례 신경전은 있었지만, 서로 얼굴을 마주한 적은 그전까지 한 번도 없었네.\"", "pi": 43}, {"t": "I hardly looked at his face.", "sk": "I hardly looked at his face.", "skk": "그의 얼굴은 거의 보지 않았어.", "ko": "\"그의 얼굴은 거의 쳐다보지도 않았네.\"", "pi": 43}, {"t": "His knees were what I wished to see.", "sk": "His knees were what I wished to see.", "skk": "내가 보고 싶었던 건 그의 무릎이었지.", "ko": "\"내가 정작 보고 싶었던 건 그의 무릎이었으니까.\"", "pi": 43}, {"t": "You must yourself have remarked how worn, wrinkled, and stained they were.", "sk": "You must yourself have remarked how worn, wrinkled, and stained they were.", "skk": "자네도 분명 그게 얼마나 닳고 주름지고 얼룩졌는지 알아챘을 거야.", "ko": "\"자네도 분명 그 무릎이 얼마나 닳고 주름지고 얼룩져 있었는지 알아챘을 걸세.\"", "pi": 43}, {"t": "They spoke of those hours of burrowing.", "sk": "They spoke of those hours of burrowing.", "skk": "그건 굴을 파느라 보낸 시간들을 말해주고 있었지.", "ko": "\"그것들은 굴을 파느라 보낸 그 숱한 시간을 말없이 증언하고 있었지.\"", "pi": 43}, {"t": "The only remaining point was what they were burrowing for.’", "sk": "The only remaining point was what they were burrowing for.", "skk": "남은 유일한 문제는 그들이 뭘 위해 굴을 파고 있느냐는 것이었어.", "ko": "\"이제 남은 유일한 문제는 그들이 대체 무엇을 위해 그 굴을 파고 있느냐는 것이었네.'\"", "pi": 43}, {"t": "I walked round the corner, saw the City and Suburban Bank abutted on our friend’s premises, and felt that I had solved my problem.", "sk": "I walked round the corner, saw the City and Suburban Bank abutted on our friend’s premises, and felt that I had solved my problem.", "skk": "모퉁이를 돌아 시티 앤드 서버번 은행이 우리 친구의 건물에 붙어 있는 걸 보고, 문제를 풀었다고 느꼈지.", "ko": "\"모퉁이를 돌아가서 시티 앤드 서버번 은행이 바로 그 친구의 건물에 붙어 있는 것을 보았고, 그제야 내 문제를 풀었다고 느꼈네.\"", "pi": 44}, {"t": "When you drove home after the concert I called upon Scotland Yard and upon the chairman of the bank directors, with the result that you have seen.’", "sk": "When you drove home after the concert I called upon Scotland Yard and upon the chairman of the bank directors, with the result that you have seen.", "skk": "자네가 연주회 후 집으로 가는 동안 나는 스코틀랜드 야드와 은행 이사회 의장을 찾아갔고, 결과는 자네도 본 대로야.", "ko": "\"자네가 연주회를 마치고 마차로 집에 가는 동안, 나는 스코틀랜드 야드와 은행 이사회 의장을 찾아갔고, 그 결과는 자네도 이미 본 그대로일세.'\"", "pi": 44}, {"t": "‘And how could you tell that they would make their attempt to-night?’ I asked.", "sk": "And how could you tell that they would make their attempt to-night? I asked.", "skk": "근데 그들이 오늘 밤 시도할 거라는 걸 어떻게 알았어? 내가 물었다.", "ko": "\"'그런데 그들이 하필 오늘 밤 시도할 거라는 건 어떻게 아셨습니까?' 내가 물었습니다.\"", "pi": 44}, {"t": "‘Well, when they closed their League offices that was a sign that they cared no longer about Mr. Jabez Wilson’s presence—in other words, that they had completed their tunnel.", "sk": "Well, when they closed their League offices that was a sign that they cared no longer about Mr. Jabez Wilson’s presence, that they had completed their tunnel.", "skk": "음, 그들이 연맹 사무실을 닫았다는 건 더 이상 윌슨 씨의 존재를 신경 쓰지 않는다는 신호였지, 다시 말해 굴을 완성했다는 뜻이었어.", "ko": "\"'음, 그들이 연맹 사무실을 닫았다는 것은 더 이상 제이비즈 윌슨 씨의 존재를 신경 쓰지 않게 됐다는 신호였네—다시 말해, 굴을 다 완성했다는 뜻이었지.'\"", "pi": 44}, {"t": "But it was essential that they should use it soon, as it might be discovered, or the bullion might be removed.", "sk": "But it was essential that they should use it soon, as it might be discovered, or the bullion might be removed.", "skk": "하지만 발각되거나 금괴가 옮겨질 수도 있으니 곧 써야 한다는 게 필수적이었어.", "ko": "\"하지만 발각되거나 금괴가 다른 곳으로 옮겨질 수도 있으니, 그 굴을 곧 써야만 한다는 것이 필수적이었지.\"", "pi": 44}, {"t": "Saturday would suit them better than any other day, as it would give them two days for their escape.", "sk": "Saturday would suit them better than any other day, as it would give them two days for their escape.", "skk": "토요일이 다른 어느 날보다 그들에게 나았지, 도주할 이틀을 벌어주니까.", "ko": "\"토요일이 다른 어느 날보다 그들에게 유리했을 걸세, 도주할 이틀의 여유를 벌어다 줄 테니 말이야.\"", "pi": 44}, {"t": "For all these reasons I expected them to come to-night.’", "sk": "For all these reasons I expected them to come to-night.", "skk": "이런 이유들로 나는 그들이 오늘 밤 올 거라 예상했지.", "ko": "\"이런 모든 이유로, 나는 그들이 다름 아닌 오늘 밤 올 것이라 예상했던 걸세.'\"", "pi": 44}, {"t": "‘You reasoned it out beautifully,’ I exclaimed in unfeigned admiration.", "sk": "You reasoned it out beautifully, I exclaimed in unfeigned admiration.", "skk": "정말 훌륭하게 추리해내셨군요, 나는 진심 어린 감탄으로 외쳤다.", "ko": "\"'정말 훌륭하게 추리해내셨군요,' 나는 꾸밈없는 감탄에 겨워 외쳤습니다.\"", "pi": 44}, {"t": "‘It is so long a chain, and yet every link rings true.’", "sk": "It is so long a chain, and yet every link rings true.", "skk": "이렇게 긴 사슬인데도 고리 하나하나가 다 맞아떨어지네요.", "ko": "\"'이렇게 긴 사슬인데도 고리 하나하나가 다 진짜처럼 들어맞는군요.'\"", "pi": 44}, {"t": "‘It saved me from ennui,’ he answered, yawning.", "sk": "It saved me from ennui, he answered, yawning.", "skk": "그게 날 권태에서 구해줬지, 하품하며 그가 대답했다.", "ko": "\"'그게 나를 권태로움에서 구해줬지,' 그가 하품을 하며 대답했습니다.\"", "pi": 44}, {"t": "‘Alas!", "sk": "Alas!", "skk": "아아!", "ko": "\"'아아!'\"", "pi": 44}, {"t": "I already feel it closing in upon me.", "sk": "I already feel it closing in upon me.", "skk": "벌써 그게 나를 조여오는 걸 느껴.", "ko": "\"벌써 그것이 다시 나를 조여오는 게 느껴지는군.\"", "pi": 44}, {"t": "My life is spent in one long effort to escape from the commonplaces of existence.", "sk": "My life is spent in one long effort to escape from the commonplaces of existence.", "skk": "내 인생은 존재의 평범함에서 벗어나려는 하나의 긴 노력에 바쳐져 있어.", "ko": "\"내 인생은 존재의 평범함에서 벗어나려는 하나의 기나긴 노력에 온통 바쳐져 있다네.\"", "pi": 45}, {"t": "These little problems help me to do so.’", "sk": "These little problems help me to do so.", "skk": "이런 자잘한 문제들이 그렇게 하도록 날 도와주지.", "ko": "\"이런 자잘한 문제들이 바로 그렇게 하도록 날 도와주는 걸세.'\"", "pi": 45}, {"t": "‘And you are a benefactor of the race,’ said I.", "sk": "And you are a benefactor of the race, said I.", "skk": "그리고 당신은 인류의 은인이시군요, 내가 말했다.", "ko": "\"'그리고 당신은 인류의 은인이시로군요,' 제가 말했습니다.\"", "pi": 45}, {"t": "He shrugged his shoulders.", "sk": "He shrugged his shoulders.", "skk": "그는 어깨를 으쓱했다.", "ko": "\"그는 그저 어깨를 으쓱해 보였습니다.\"", "pi": 45}, {"t": "‘Well, perhaps, after all, it is of some little use,’ he remarked.", "sk": "Well, perhaps, after all, it is of some little use, he remarked.", "skk": "음, 어쩌면, 결국, 그게 조금은 쓸모가 있겠지, 그가 말했다.", "ko": "\"'뭐, 어쩌면, 결국 조금은 쓸모가 있는 셈이겠지,' 그가 말했습니다.\"", "pi": 45}, {"t": "‘“L’homme c’est rien—l’œuvre c’est tout,” as Gustave Flaubert wrote to George Sand.’", "sk": "as Gustave Flaubert wrote to George Sand.", "skk": "귀스타브 플로베르가 조르주 상드에게 쓴 대로.", "ko": "\"'\"사람은 아무것도 아니고, 작품이 전부다,\" 귀스타브 플로베르가 조르주 상드에게 그렇게 썼지.'\"", "pi": 45}];
